:root{
    --stone-900:#120d09;
    --stone-800:#1a1410;
    --stone-700:#2b2118;
    --stone-600:#3d2f22;
    --sandstone:#c9a876;
    --sandstone-lt:#e8c896;
    --gold:#d4af37;
    --gold-bright:#f4d35e;
    --gold-dim:#8a6d24;
    --lapis:#1e3a5f;
    --turquoise:#2e8b7d;
    --torch:#ff8c42;
    --torch-lt:#ffb347;
    --shadow-deep:#07050300;
    --papyrus:#f0e4c8;
    --ease-heavy: cubic-bezier(.22,.61,.16,1);
  }

  *{ margin:0; padding:0; box-sizing:border-box; }

  html{ scroll-behavior:smooth; background:var(--stone-900); }

  body{
    background:var(--stone-900);
    color:var(--papyrus);
    font-family:'Cormorant Garamond', serif;
    overflow-x:hidden;
    width:100%;
  }

  ::selection{ background:var(--gold-dim); color:var(--papyrus); }

  h1,h2,.display{
    font-family:'Cinzel', serif;
    letter-spacing:.04em;
  }

  a, button, input{ font-family:inherit; }

  /* Focus visibility (accessibility floor) */
  a:focus-visible, button:focus-visible, input:focus-visible{
    outline:2px solid var(--gold-bright);
    outline-offset:3px;
    border-radius:4px;
  }

  /* ============================================================
     SHARED — noise / grain filter (cheap stone texture)
  ============================================================ */
  .grain{
    position:absolute; inset:0;
    background:transparent;
    opacity:.05;
    mix-blend-mode:overlay;
    pointer-events:none;
  }

  /* ============================================================
     GLOBAL DUST LAYER
  ============================================================ */
  #dustLayer{
    position:fixed; inset:0;
    pointer-events:none;
    z-index:40;
    overflow:hidden;
  }
  .mote{
    position:absolute;
    bottom:-4%;
    width:3px; height:3px;
    border-radius:50%;
    background:radial-gradient(circle, rgba(244,211,94,.9), rgba(244,211,94,0) 70%);
    opacity:0;
    animation-name: floatUp;
    animation-timing-function: linear;
    animation-iteration-count: infinite;
  }
  @keyframes floatUp{
    0%   { transform:translate(0,0); opacity:0; }
    8%   { opacity:.75; }
    92%  { opacity:.4; }
    100% { transform:translate(var(--drift,20px), -110vh); opacity:0; }
  }

  /* ============================================================
     ENTRANCE SECTION
  ============================================================ */
  .entrance{
    position:relative;
    width:100%;
    min-height:100vh;
    overflow:hidden;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:flex-end;
    isolation:isolate;
  }

  .sky{
    position:absolute; inset:0;
    background:
      radial-gradient(ellipse 90% 70% at 50% 8%, #f4d9a0 0%, #e8ad5f 22%, #c97a45 42%, #7a4a3a 62%, var(--stone-800) 82%),
      linear-gradient(to bottom, transparent 0%, var(--stone-900) 100%);
    z-index:0;
  }

  .sun-disc{
    position:absolute;
    top:9%; left:50%;
    width:min(22vw, 240px); height:min(22vw,240px);
    transform:translateX(-50%);
    border-radius:50%;
    background:radial-gradient(circle, #fff6da 0%, #ffdf8a 35%, #ffb347 62%, rgba(255,140,66,0) 75%);
    box-shadow:0 0 90px 40px rgba(255,183,71,.35);
    z-index:1;
    animation: sunBreathe 8s ease-in-out infinite;
  }
  @keyframes sunBreathe{
    0%,100%{ opacity:.85; transform:translateX(-50%) scale(1); }
    50%    { opacity:1;   transform:translateX(-50%) scale(1.035); }
  }

  .godrays{
    position:absolute;
    top:-15%; left:50%;
    width:150%; height:120%;
    transform:translateX(-50%);
    background: conic-gradient(from 0deg,
      transparent 0deg, rgba(255,214,150,.22) 4deg, transparent 9deg,
      transparent 26deg, rgba(255,214,150,.16) 31deg, transparent 36deg,
      transparent 52deg, rgba(255,214,150,.2) 56deg, transparent 62deg,
      transparent 80deg, rgba(255,214,150,.14) 85deg, transparent 90deg,
      transparent 108deg, rgba(255,214,150,.18) 113deg, transparent 118deg,
      transparent 300deg, rgba(255,214,150,.12) 306deg, transparent 312deg);
    -webkit-mask-image: radial-gradient(circle at 50% 18%, black 0%, black 30%, transparent 68%);
    mask-image: radial-gradient(circle at 50% 18%, black 0%, black 30%, transparent 68%);
    mix-blend-mode:screen;
    opacity:.55;
    z-index:1;
    animation: rayTurn 120s linear infinite;
    pointer-events:none;
  }
  @keyframes rayTurn{
    to{ transform:translateX(-50%) rotate(360deg); }
  }

  .fog{
    position:absolute;
    left:-15%;
    width:130%; height:34%;
    background:radial-gradient(ellipse at center, rgba(230,200,150,.14) 0%, rgba(230,200,150,0) 70%);
    filter:blur(6px);
    z-index:5;
    pointer-events:none;
  }
  .fog-back{ bottom:14%; opacity:.55; animation: fogDrift 34s ease-in-out infinite; }
  .fog-front{ bottom:0; height:22%; opacity:.8; animation: fogDrift 22s ease-in-out infinite reverse; }
  @keyframes fogDrift{
    0%,100%{ transform:translateX(-3%); }
    50%    { transform:translateX(3%); }
  }

  /* --- Obelisks (far background) --- */
  .obelisk{
    position:absolute;
    bottom:18%;
    width:min(5.5vw,64px);
    height:42%;
    background:linear-gradient(to right, var(--stone-700), var(--sandstone) 45%, var(--stone-700));
    clip-path:polygon(20% 100%, 80% 100%, 100% 8%, 50% 0%, 0% 8%);
    z-index:2;
    opacity:.85;
    box-shadow: inset 0 0 30px rgba(0,0,0,.5);
  }
  .obelisk::after{
    content:"";
    position:absolute; top:0; left:44%;
    width:12%; height:6%;
    background:radial-gradient(circle, #fff2c4, transparent 70%);
    opacity:.9;
  }
  .obelisk-left{ left:6%; }
  .obelisk-right{ right:6%; }

  /* --- Pylon towers (gate frame) --- */
  .pylon{
    position:absolute;
    bottom:0;
    width:min(17vw,196px);
    height:82%;
    background:
      linear-gradient(to bottom, var(--stone-700) 0%, var(--stone-800) 100%);
    z-index:3;
    box-shadow: inset -20px 0 40px rgba(0,0,0,.5), inset 20px 0 40px rgba(0,0,0,.5);
  }
  .pylon-left{  left:8%;  clip-path:polygon(0 100%, 100% 100%, 82% 0, 0 0); }
  .pylon-right{ right:8%; clip-path:polygon(0 100%, 100% 100%, 100% 0, 18% 0); }
 .pylon .hiero-panel{ position:absolute; inset:8% 12%; opacity:.5; }

  /* --- Pylon relief carvings: a readable narrative band, not texture noise --- */
  .pylon .pylon-relief{
    position:absolute;
    inset:10% 14% 14%;
    display:flex;
    flex-direction:column;
    justify-content:space-evenly;
    gap:6%;
  }
  .pylon .relief-row{
    display:block;
    height:9%;
    background:
      repeating-linear-gradient(90deg,
        rgba(212,175,55,.5) 0 8%,
        rgba(20,15,10,.35) 8% 14%,
        rgba(212,175,55,.32) 14% 20%,
        rgba(20,15,10,.35) 20% 26%);
    border-top:1px solid rgba(212,175,55,.25);
    border-bottom:1px solid rgba(0,0,0,.4);
    opacity:.8;
  }
  .pylon .relief-row:nth-child(2){ background-position:20% 0; opacity:.65; }
  .pylon .relief-row:nth-child(3){ background-position:40% 0; opacity:.7; }
  .pylon .relief-cartouche{
    display:block;
    width:56%;
    height:16%;
    margin:4% auto 0;
    border:2px solid rgba(212,175,55,.55);
    border-radius:50% / 22%;
    background:radial-gradient(ellipse at 50% 40%, rgba(212,175,55,.14), transparent 70%);
  }

  /* --- Architrave: the lintel that unites both pylons into one monument --- */
  .gate-architrave{
    position:absolute;
    bottom:68%; left:50%;
    transform:translateX(-50%);
    width:min(62vw,560px);
    height:6.5%;
    z-index:5;
    background:linear-gradient(to bottom, var(--sandstone-lt) 0%, var(--sandstone) 55%, var(--stone-700) 100%);
    box-shadow:0 6px 18px rgba(0,0,0,.5), inset 0 -6px 10px rgba(0,0,0,.35);
    border-radius:3px;
  }
  .architrave-sundisc{
    position:absolute; top:-58%; left:50%;
    transform:translateX(-50%);
    width:13%; aspect-ratio:1;
    border-radius:50%;
    background:radial-gradient(circle, #fff6da 0%, var(--gold-bright) 45%, var(--gold-dim) 80%);
    box-shadow:0 0 22px 6px rgba(244,211,94,.45);
  }
  .architrave-sundisc::before,
  .architrave-sundisc::after{
    content:"";
    position:absolute; top:48%; width:220%; height:14%;
    background:linear-gradient(90deg, transparent, var(--gold-dim) 30%, var(--gold-bright) 50%, var(--gold-dim) 70%, transparent);
  }
  .architrave-sundisc::before{ left:-210%; transform:translateY(-50%) rotate(4deg); }
  .architrave-sundisc::after{  left:110%;  transform:translateY(-50%) rotate(-4deg); }
  .architrave-band{
    position:absolute; inset:30% 6%;
    background:repeating-linear-gradient(90deg, rgba(43,33,24,.4) 0 3%, transparent 3% 6%);
    opacity:.7;
  }

  /* --- Distant skyline: implies a whole necropolis beyond this one temple --- */
  .skyline-silhouette{
    position:absolute;
    bottom:15%; left:-5%;
    width:110%; height:9%;
    background:var(--stone-900);
    opacity:.5;
    clip-path:polygon(
      0% 100%, 0% 60%, 4% 60%, 6% 30%, 9% 60%, 14% 60%, 14% 75%, 20% 75%,
      22% 40%, 24% 75%, 30% 75%, 30% 55%, 34% 55%, 36% 20%, 38% 55%, 44% 55%,
      44% 80%, 55% 80%, 57% 45%, 60% 80%, 70% 80%, 70% 60%, 74% 60%, 76% 25%,
      79% 60%, 84% 60%, 84% 75%, 92% 75%, 94% 45%, 96% 75%, 100% 75%, 100% 100%
    );
    z-index:1;
    pointer-events:none;
    filter:blur(.4px);
  }

  /* --- Ruin fragment: one specific broken monument, not generic scatter --- */
  .ruin-fragment{
    position:absolute;
    bottom:1%;
    width:min(6vw,58px);
    height:min(9vw,84px);
    background:linear-gradient(105deg, var(--stone-700) 0%, var(--sandstone) 50%, var(--stone-600) 100%);
    clip-path:polygon(10% 100%, 90% 100%, 100% 55%, 62% 0%, 30% 18%, 0% 62%);
    opacity:.85;
    z-index:2;
    box-shadow:inset 0 0 14px rgba(0,0,0,.5);
    filter:drop-shadow(0 6px 8px rgba(0,0,0,.4));
  }
  .ruin-fragment::after{
    content:"";
    position:absolute; bottom:-6%; left:-30%;
    width:160%; height:22%;
    background:radial-gradient(ellipse at center, rgba(201,168,118,.5), transparent 70%);
    border-radius:50%;
  }
  .ruin-fragment-left{ left:29%; transform:rotate(-8deg); }
  .ruin-fragment-right{ right:29%; transform:rotate(9deg) scaleX(-1); }

  /* --- Great Gate --- */
  .gate-wrap{
    position:absolute;
    bottom:0; left:50%;
    transform:translateX(-50%);
    width:min(54vw,500px);
    height:76%;
    perspective:1400px;
    z-index:4;
  }
  .gate-glow{
    position:absolute; inset:6%;
    background:radial-gradient(ellipse at 50% 40%, rgba(255,178,90,.9), rgba(255,140,60,.25) 55%, transparent 75%);
    filter:blur(4px);
    opacity:.9;
    z-index:0;
  }
  .door{
    position:absolute;
    top:0; width:50%; height:100%;
    background:
      linear-gradient(to bottom, var(--stone-600), var(--stone-800) 85%);
    background-size:100% 100%;
    box-shadow: inset 0 0 60px rgba(0,0,0,.6);
    transform-style:preserve-3d;
    transition:transform .1s linear;
  }
  .door::before{
    content:"";
    position:absolute; inset:6%;
    border:2px solid rgba(212,175,55,.35);
  }
  .door-left{ left:0; transform-origin:left center; transform:rotateY(-2deg); }
  .door-right{ right:0; transform-origin:right center; transform:rotateY(2deg); }

  /* --- Staircase --- */
  .stairs{
    position:absolute;
    bottom:0; left:50%;
    transform:translateX(-50%);
    width:min(56vw,520px);
    height:12%;
    z-index:3;
    background:repeating-linear-gradient(
      to top,
      var(--stone-700) 0, var(--stone-700) 8%,
      var(--stone-600) 8%, var(--stone-600) 9.5%
    );
    clip-path:polygon(0 100%, 100% 100%, 88% 0, 12% 0);
    box-shadow:0 -6px 24px rgba(0,0,0,.45);
  }

  /* --- Guardian statues --- */
  .statue{
    position:absolute;
    bottom:11%;
    width:min(8vw,84px);
    z-index:6;
    filter:drop-shadow(0 12px 14px rgba(0,0,0,.55));
  }
  .statue-left{ left:20%; }
  .statue-right{ right:20%; transform:scaleX(-1); }
  .statue svg{ width:100%; display:block; }

  /* --- Massive foreground columns --- */
  .column{
    position:absolute;
    bottom:0;
    width:min(7vw,72px);
    height:98%;
    z-index:7;
    background:
      repeating-linear-gradient(to right,
        var(--sandstone) 0 6%, var(--stone-600) 6% 9%),
      linear-gradient(to bottom, var(--sandstone-lt), var(--sandstone) 60%, var(--stone-700) 100%);
    background-blend-mode:multiply, normal;
    box-shadow: inset -10px 0 20px rgba(0,0,0,.5), inset 10px 0 16px rgba(255,220,170,.15);
  }
  .column::before{ /* capital */
    content:"";
    position:absolute; top:-3%; left:-22%;
    width:144%; height:8%;
    background:linear-gradient(to bottom, var(--gold-dim), var(--sandstone));
    border-radius:6px 6px 2px 2px;
    box-shadow:0 4px 10px rgba(0,0,0,.4);
  }
  .column::after{ /* base */
    content:"";
    position:absolute; bottom:0; left:-16%;
    width:132%; height:4%;
    background:var(--stone-700);
    border-radius:2px;
  }
  .column-left{ left:2%; }
  .column-right{ right:2%; }

  /* ============================================================
     TORCHES (shared component, used in entrance + corridor)
  ============================================================ */
  .torch{
    position:absolute;
    width:26px; height:70px;
    z-index:8;
  }
  .torch .sconce{
    position:absolute; bottom:0; left:50%; transform:translateX(-50%);
    width:14px; height:34px;
    background:linear-gradient(to bottom, var(--gold-dim), var(--stone-700));
    border-radius:2px;
    box-shadow:0 0 8px rgba(0,0,0,.5);
  }
  .torch .flame{
    position:absolute; bottom:28px; left:50%;
    transform:translateX(-50%);
    width:20px; height:34px;
    background:radial-gradient(circle at 50% 70%, var(--torch-lt) 0%, var(--torch) 45%, rgba(255,140,60,0) 75%);
    clip-path:path('M10 0 C15 8 20 16 16 24 C13 30 7 30 4 24 C0 16 5 8 10 0 Z');
    filter:blur(.3px);
    animation: flicker 2.6s ease-in-out infinite;
    transform-origin:bottom center;
  }
  .torch .glow{
    position:absolute; bottom:24px; left:50%;
    transform:translateX(-50%);
    width:90px; height:90px;
    background:radial-gradient(circle, rgba(255,171,90,.55), rgba(255,140,60,0) 70%);
    filter:blur(4px);
    animation: glowPulse 2.6s ease-in-out infinite;
    z-index:-1;
  }
  @keyframes flicker{
    0%,100%{ transform:translateX(-50%) scaleY(1) skewX(0deg); opacity:1; }
    20%    { transform:translateX(-50%) scaleY(1.08) skewX(-2deg); opacity:.95; }
    40%    { transform:translateX(-48%) scaleY(.94) skewX(2deg); opacity:1; }
    60%    { transform:translateX(-52%) scaleY(1.05) skewX(-1deg); opacity:.92; }
    80%    { transform:translateX(-50%) scaleY(.97) skewX(1deg); opacity:1; }
  }
  @keyframes glowPulse{
    0%,100%{ opacity:.65; transform:translateX(-50%) scale(1); }
    50%    { opacity:.9;  transform:translateX(-50%) scale(1.12); }
  }
  .torch-entrance-left{ left:14%; bottom:6%; }
  .torch-entrance-right{ right:14%; bottom:6%; }

  /* ============================================================
     HERO CONTENT
  ============================================================ */
  .hero-content{
    position:relative;
    z-index:20;
    display:flex;
    flex-direction:column;
    align-items:center;
    padding:0 20px 6vh;
    width:100%;
  }

  .title{
    font-size:clamp(2.1rem, 6.6vw, 5rem);
    font-weight:700;
    text-align:center;
    line-height:1.05;
    background:linear-gradient(180deg, #fff3d0 0%, var(--gold-bright) 35%, var(--gold) 60%, var(--gold-dim) 100%);
    -webkit-background-clip:text;
    background-clip:text;
    color:transparent;
    filter:drop-shadow(0 2px 1px rgba(0,0,0,.6)) drop-shadow(0 0 26px rgba(212,175,55,.35));
    position:relative;
    margin-bottom:.35em;
    opacity:0;
    animation: titleRise 1.4s var(--ease-heavy) forwards .3s;
  }
  .title::after{
    content:"";
    position:absolute; inset:0;
    background:linear-gradient(100deg, transparent 30%, rgba(255,255,255,.75) 45%, transparent 60%);
    background-size:250% 100%;
    background-position:150% 0;
    -webkit-background-clip:text;
    background-clip:text;
    color:transparent;
    mix-blend-mode:overlay;
    animation: titleShimmer 2.2s ease-out 1.6s 1;
  }
  .title small{
    display:block;
    font-family:'Cormorant Garamond', serif;
    font-style:italic;
    font-weight:500;
    font-size:.28em;
    letter-spacing:.5em;
    color:var(--sandstone-lt);
    -webkit-text-fill-color:var(--sandstone-lt);
    margin-top:.4em;
    text-transform:uppercase;
  }
  @keyframes titleRise{
    from{ opacity:0; transform:translateY(26px) scale(.97); }
    to  { opacity:1; transform:translateY(0) scale(1); }
  }
  @keyframes titleShimmer{
    to{ background-position:-50% 0; }
  }

  /* ============================================================
     ANKH SEARCH BAR
  ============================================================ */
  .ankh{
    position:relative;
    display:flex;
    flex-direction:column;
    align-items:center;
    opacity:0;
    transform:scale(.82);
    animation: ankhOpen 1s var(--ease-heavy) forwards 1.05s;
  }
  @keyframes ankhOpen{
    0%  { opacity:0; transform:scale(.78) translateY(10px); }
    60% { opacity:1; }
    100%{ opacity:1; transform:scale(1) translateY(0); }
  }

  .ankh-burst{
    position:absolute;
    top:18%; left:50%;
    width:10px; height:10px;
    transform:translate(-50%,-50%);
    border-radius:50%;
    background:radial-gradient(circle, #fff6da, rgba(255,246,218,0));
    animation: burst 1.1s ease-out forwards 1.15s;
    pointer-events:none;
    z-index:5;
  }
  @keyframes burst{
    0%  { opacity:.9; transform:translate(-50%,-50%) scale(1); }
    100%{ opacity:0;  transform:translate(-50%,-50%) scale(38); }
  }

  .ankh-loop-wrap{
    position:relative;
    width:clamp(170px, 24vw, 250px);
    height:clamp(128px, 18vw, 188px);
  }
  .ankh-loop-frame{
    position:absolute; inset:-6px;
    border-radius:50% 50% 46% 46% / 58% 58% 42% 42%;
    background:linear-gradient(160deg, var(--gold-bright), var(--gold) 45%, var(--gold-dim) 100%);
    box-shadow:0 0 0 2px rgba(0,0,0,.3), 0 8px 30px rgba(212,175,55,.25);
    z-index:0;
  }
  .ankh-input{
    position:absolute; inset:6px;
    border-radius:50% 50% 46% 46% / 58% 58% 42% 42%;
    border:none;
    background:radial-gradient(ellipse at 50% 35%, #241a11 0%, #150f0a 75%);
    color:var(--papyrus);
    text-align:center;
    font-family:'Cormorant Garamond', serif;
    font-style:italic;
    font-size:clamp(.95rem, 1.6vw, 1.15rem);
    padding:0 20% 8%;
    box-shadow:inset 0 0 24px rgba(0,0,0,.7), inset 0 0 0 1px rgba(212,175,55,.4);
    transition:box-shadow .5s var(--ease-heavy), background .5s;
    z-index:1;
  }
  .ankh-input::placeholder{ color:rgba(240,228,200,.5); }
  .ankh-input:hover{
    box-shadow:inset 0 0 30px rgba(0,0,0,.6), inset 0 0 0 1px rgba(244,211,94,.6), 0 0 26px rgba(244,211,94,.35);
  }
  .ankh-input:focus{
    outline:none;
    box-shadow:inset 0 0 34px rgba(0,0,0,.55), inset 0 0 0 2px var(--gold-bright), 0 0 46px rgba(244,211,94,.55);
    background:radial-gradient(ellipse at 50% 35%, #2c2013 0%, #170f09 75%);
  }

  .ankh-crossbar{
    width:clamp(190px, 27vw, 280px);
    height:22px;
    margin-top:-10px;
    border-radius:5px;
    background:linear-gradient(180deg, var(--gold-bright), var(--gold) 60%, var(--gold-dim));
    box-shadow:0 4px 14px rgba(0,0,0,.4), 0 0 18px rgba(212,175,55,.3);
    position:relative;
    z-index:2;
  }
  .ankh-crossbar::after{
    content:"";
    position:absolute; top:50%; left:50%;
    width:12px; height:12px;
    transform:translate(-50%,-50%) rotate(45deg);
    background:radial-gradient(circle, var(--turquoise), #17564c);
    box-shadow:0 0 10px rgba(46,139,125,.7);
  }
  .ankh-stem{
    width:clamp(34px,4.4vw,48px);
    height:clamp(60px,8vw,96px);
    margin-top:-2px;
    background:linear-gradient(180deg, var(--gold), var(--gold-dim));
    clip-path:polygon(18% 0, 82% 0, 100% 100%, 0% 100%);
    box-shadow:0 6px 16px rgba(0,0,0,.4);
    z-index:1;
  }

  .quick-tags{
    display:flex;
    gap:12px;
    flex-wrap:wrap;
    justify-content:center;
    margin-top:2.4em;
    opacity:0;
    animation: fadeUp .9s var(--ease-heavy) forwards 1.5s;
  }
  @keyframes fadeUp{
    from{ opacity:0; transform:translateY(10px); }
    to  { opacity:1; transform:translateY(0); }
  }
  .tag{
    font-family:'Cinzel', serif;
    font-size:.68rem;
    letter-spacing:.12em;
    text-transform:uppercase;
    color:var(--sandstone-lt);
    background:linear-gradient(180deg, rgba(61,47,34,.75), rgba(20,15,10,.8));
    border:1px solid rgba(212,175,55,.4);
    border-radius:4px;
