  /* ============================================================
   LEVEL 5 — TEMPLE EXIT
   FINAL DAWN / DESERT SCENE
   ============================================================ */

.temple-exit {
  position: relative;
  width: 100%;
  min-height: 210vh;
  overflow: hidden;
  isolation: isolate;

  background:
    linear-gradient(
      to bottom,
      #030304 0%,
      #080604 16%,
      #20140c 38%,
      #8b512b 62%,
      #d49a52 78%,
      #c58b45 100%
    );
}


/* ============================================================
   SKY
   ============================================================ */

.temple-exit .exit-sky {
  position: absolute;
  inset: 0;
  z-index: 0;

  background:
    radial-gradient(
      circle at 50% 67%,
      rgba(255, 197, 101, .75) 0%,
      rgba(239, 151, 69, .32) 14%,
      rgba(121, 66, 42, .18) 30%,
      transparent 54%
    ),
    linear-gradient(
      to bottom,
      #020205 0%,
      #08070d 22%,
      #28151b 43%,
      #7a3f28 65%,
      #d3914d 82%,
      #e4ae65 100%
    );

  transition:
    background 1s ease;
}


/* warm horizon */

.temple-exit .exit-sky::after {
  content: "";

  position: absolute;

  left: 50%;
  bottom: 22%;

  width: min(55vw, 700px);
  height: min(55vw, 700px);

  transform: translateX(-50%);

  border-radius: 50%;

  background:
    radial-gradient(
      circle,
      rgba(255, 224, 157, .95) 0%,
      rgba(255, 190, 92, .55) 22%,
      rgba(255, 153, 61, .22) 45%,
      transparent 72%
    );

  filter: blur(8px);

  opacity: .85;
}


/* ============================================================
   STARS
   ============================================================ */

.temple-exit .exit-sky::before {
  content: "";

  position: absolute;
  inset: 0;

  background-image:
    radial-gradient(circle at 12% 14%, rgba(255,255,255,.7) 0 1px, transparent 2px),
    radial-gradient(circle at 24% 22%, rgba(255,255,255,.5) 0 1px, transparent 2px),
    radial-gradient(circle at 39% 10%, rgba(255,255,255,.65) 0 1px, transparent 2px),
    radial-gradient(circle at 57% 18%, rgba(255,255,255,.55) 0 1px, transparent 2px),
    radial-gradient(circle at 72% 11%, rgba(255,255,255,.65) 0 1px, transparent 2px),
    radial-gradient(circle at 87% 24%, rgba(255,255,255,.45) 0 1px, transparent 2px),
    radial-gradient(circle at 94% 9%, rgba(255,255,255,.55) 0 1px, transparent 2px);

  opacity: .75;

  animation:
    exitStarsFade 12s ease forwards;
}

@keyframes exitStarsFade {

  0% {
    opacity: .8;
  }

  55% {
    opacity: .45;
  }

  100% {
    opacity: 0;
  }

}


/* ============================================================
   DISTANT MOUNTAINS
   ============================================================ */

.temple-exit::before {

  content: "";

  position: absolute;

  left: -10%;
  right: -10%;
  bottom: 37%;

  height: 25%;

  z-index: 1;

  background:
    linear-gradient(
      135deg,
      transparent 20%,
      #21130e 20%,
      #21130e 34%,
      transparent 34%
    ),
    linear-gradient(
      45deg,
      transparent 30%,
      #2b1810 30%,
      #2b1810 47%,
      transparent 47%
    );

  opacity: .8;

  transform: scaleX(1.2);
}


/* ============================================================
   TEMPLE GATE
   ============================================================ */

.temple-exit .exit-gate-wrap {

  position: absolute;

  left: 50%;
  top: 7%;

  width: min(62vw, 570px);
  height: min(76vh, 650px);

  transform:
    translateX(-50%);

  z-index: 5;

  perspective: 1500px;

  filter:
    drop-shadow(
      0 35px 50px
      rgba(0,0,0,.75)
    );
}


/* ============================================================
   GATE GLOW
   ============================================================ */

.temple-exit .exit-gate-glow {

  position: absolute;

  left: 50%;
  top: 20%;

  width: 58%;
  height: 62%;

  transform: translateX(-50%);

  background:
    radial-gradient(
      ellipse,
      rgba(255, 231, 167, .95) 0%,
      rgba(255, 185, 74, .65) 22%,
      rgba(218, 126, 41, .28) 48%,
      transparent 76%
    );

  filter: blur(16px);

  opacity: .35;

  z-index: 0;
}


/* ============================================================
   TEMPLE FRAME
   ============================================================ */

.temple-exit .exit-gate-wrap::before {

  content: "";

  position: absolute;

  left: 50%;
  top: 0;

  width: 100%;
  height: 100%;

  transform: translateX(-50%);

  background:
    linear-gradient(
      90deg,
      #24170d 0%,
      #6d4b25 9%,
      #9b7139 14%,
      #513619 19%,
      transparent 19%,
      transparent 81%,
      #513619 81%,
      #9b7139 86%,
      #6d4b25 91%,
      #24170d 100%
    );

  border:
    4px solid #9c753d;

  box-shadow:
    inset 0 0 40px rgba(0,0,0,.8),
    0 15px 35px rgba(0,0,0,.65);

  z-index: 1;

}


/* ============================================================
   TEMPLE CROWN
   ============================================================ */

.temple-exit .exit-gate-wrap::after {

  content: "𓂀";

  position: absolute;

  left: 50%;
  top: -42px;

  transform: translateX(-50%);

  width: 100px;
  height: 62px;

  display: flex;
  align-items: center;
  justify-content: center;

  background:
    linear-gradient(
      to bottom,
      #c69b50,
      #765126
    );

  border:
    3px solid #3c2814;

  color: #e8c56c;

  font-family: Georgia, serif;

  font-size: 38px;

  text-shadow:
    0 0 14px rgba(238,195,87,.45);

  z-index: 10;
}


/* ============================================================
   DOORS
   ============================================================ */

.temple-exit .exit-door {

  position: absolute;

  top: 8%;

  width: 42%;
  height: 84%;

  background:
    linear-gradient(
      90deg,
      #2b1b0d,
      #65451f 16%,
      #a0783b 45%,
      #745225 72%,
      #2b1b0d
    );

  border:
    3px solid #3c2813;

  box-shadow:
    inset 0 0 35px rgba(0,0,0,.75),
    inset 0 0 0 5px rgba(211,171,87,.08);

  transform-style: preserve-3d;

  transition:
    transform 1.8s cubic-bezier(.2,.8,.2,1);
}


/* inner carving */

.temple-exit .exit-door::before {

  content: "";

  position: absolute;

  inset: 22px;

  border:
    2px solid rgba(205,166,83,.28);

  box-shadow:
    inset 0 0 0 5px rgba(205,166,83,.04);
}


/* hieroglyphic engraving */

.temple-exit .exit-door::after {

  content: "𓂀 𓋹 𓆣 𓇳";

  position: absolute;

  left: 50%;
  top: 48%;

  transform:
    translate(-50%,-50%)
    rotate(90deg);

  white-space: nowrap;

  color: rgba(65,43,19,.75);

  font-size: 24px;

  letter-spacing: 18px;
}


.temple-exit .exit-door-left {

  left: 9%;

  transform-origin: left center;

  transform:
    rotateY(0deg);
}


.temple-exit .exit-door-right {

  right: 9%;

  transform-origin: right center;

  transform:
    rotateY(0deg);
}


/* ============================================================
   DOOR LIGHT
   ============================================================ */

.temple-exit .exit-gate-wrap {

  --exit-door-open: 0deg;
}


/* ============================================================
   DESERT GROUND
   ============================================================ */

.temple-exit {

  --sand-1: #c68a43;
  --sand-2: #a96e35;
  --sand-3: #714522;
  --sand-shadow: #3b2413;
}


.temple-exit .exit-ground {

  position: absolute;

  left: -10%;
  right: -10%;
  bottom: 0;

  height: 58%;

  z-index: 3;

  transform:
    perspective(700px)
    rotateX(58deg);

  transform-origin: bottom;

  background:

    radial-gradient(
      ellipse at 50% 15%,
      rgba(255,212,128,.3),
      transparent 45%
    ),

    repeating-linear-gradient(
      172deg,
      rgba(91,53,26,.16) 0px,
      rgba(91,53,26,.16) 2px,
      transparent 2px,
      transparent 18px
    ),

    linear-gradient(
      to bottom,
      #b77839,
      #8b5629 45%,
      #4d2d18 100%
    );

  clip-path:
    polygon(
      35% 0,
      65% 0,
      100% 100%,
      0 100%
    );

  box-shadow:
    0 -20px 50px rgba(237,166,75,.18);
}


/* ============================================================
   SAND DUNES
   ============================================================ */

.temple-exit .exit-ground::before,
.temple-exit .exit-ground::after {

  content: "";

  position: absolute;

  left: -10%;
  width: 120%;

  border-radius: 50%;

  pointer-events: none;
}


.temple-exit .exit-ground::before {

  top: 8%;

  height: 90px;

  background:
    radial-gradient(
      ellipse,
      rgba(221,162,83,.55),
      rgba(168,104,49,.15) 55%,
      transparent 70%
    );

}


.temple-exit .exit-ground::after {

  bottom: 8%;

  height: 130px;

  background:
    radial-gradient(
      ellipse,
      rgba(42,24,12,.4),
      transparent 68%
    );
}


/* ============================================================
   SAND RIPPLE LINES
   ============================================================ */

.temple-exit .exit-ground {

  background-image:

    repeating-radial-gradient(
      ellipse at 50% 100%,
      transparent 0 20px,
      rgba(55,31,15,.18) 21px 23px,
      transparent 24px 46px
    ),

    linear-gradient(
      to bottom,
      #c28645,
      #8a5428 48%,
      #4a2b17
    );
}


/* ============================================================
   SNAKES
   ============================================================ */

.temple-exit::after {

  content: "";

  position: absolute;

  left: 18%;
  bottom: 13%;

  width: 100px;
  height: 5px;

  z-index: 7;

  border-radius: 50%;

  background:
    linear-gradient(
      90deg,
      transparent 0%,
      #2d1a0d 12%,
      #513019 30%,
      #25150b 50%,
      #5b351a 70%,
      #211209 88%,
      transparent 100%
    );

  box-shadow:
    0 0 0 1px rgba(195,145,65,.12);

  animation:
    exitSnakeMove 7s ease-in-out infinite;
}


@keyframes exitSnakeMove {

  0% {
    transform:
      translateX(-30px)
      translateY(0)
      rotate(-3deg);
  }

  25% {
    transform:
      translateX(45px)
      translateY(-4px)
      rotate(5deg);
  }

  50% {
    transform:
      translateX(100px)
      translateY(3px)
      rotate(-4deg);
  }

  75% {
    transform:
      translateX(145px)
      translateY(-3px)
      rotate(4deg);
  }

  100% {
    transform:
      translateX(210px)
      translateY(0)
      rotate(-2deg);
  }

}


/* ============================================================
   SECOND SNAKE
   ============================================================ */

.temple-exit .exit-farewell::before {

  content: "";

  position: absolute;

  left: 8%;
  bottom: 10%;

  width: 70px;
  height: 4px;

  border-radius: 50%;

  background:
    linear-gradient(
      90deg,
      transparent,
      #3a2110,
      #68401d,
      #2b170a,
      transparent
    );

  animation:
    exitSnakeSmall 9s ease-in-out infinite;
}


@keyframes exitSnakeSmall {

  0%,100% {
    transform: translateX(0);
  }

  50% {
    transform: translateX(180px);
  }

}


/* ============================================================
   DUST PARTICLES
   ============================================================ */

.temple-exit .exit-fade-overlay {

  position: absolute;

  inset: 0;

  z-index: 20;

  pointer-events: none;

  background:
    radial-gradient(
      ellipse at 50% 50%,
      transparent 35%,
      rgba(0,0,0,.72) 100%
    );

  opacity: .45;
}


/* ============================================================
   FAREWELL
   ============================================================ */

.temple-exit .exit-farewell {

  position: absolute;

  left: 50%;
  top: 58%;

  width: min(650px, 88%);

  transform:
    translate(-50%, 20px);

  z-index: 15;

  text-align: center;

  opacity: 0;

  transition:
    opacity 1s ease,
    transform 1s ease;

  text-shadow:
    0 3px 18px rgba(0,0,0,.85);
}


.temple-exit .exit-farewell.visible {

  opacity: 1;

  transform:
    translate(-50%,0);
}


.temple-exit .exit-farewell h2 {

  margin: 0;

  font-family:
    Georgia,
    serif;

  font-size:
    clamp(1.8rem,4vw,3rem);

  letter-spacing:
    .08em;

  color:
    #f0d18a;

  text-shadow:
    0 0 22px rgba(239,191,88,.25),
    0 3px 15px #000;
}


.temple-exit .exit-farewell p {

  color:
    #e1c998;

  font-size:
    clamp(.95rem,1.7vw,1.2rem);

  font-style:
    italic;

  line-height:
    1.7;
}


/* ============================================================
   RETURN BUTTON
   ============================================================ */

.temple-exit .back-home-btn {

  margin-top: 20px;

  padding: 12px 28px;

  border:
    1px solid #b18a4c;

  border-radius: 3px;

  background:
    linear-gradient(
      to bottom,
      #b78b45,
      #69471f
    );

  color:
    #f5dda1;

  font-family:
    Georgia,
    serif;

  letter-spacing:
    .08em;

  cursor:
    pointer;

  box-shadow:
    0 8px 25px rgba(0,0,0,.45);

  transition:
    .25s ease;
}


.temple-exit .back-home-btn:hover {

  transform:
    translateY(-3px);

  box-shadow:
    0 12px 30px rgba(0,0,0,.6);
}


/* ============================================================
   INFORMATION AREA
   ============================================================ */

.temple-exit .exit-footer {

  position: relative;

  z-index: 12;

  max-width: 1180px;

  margin:
    0 auto;

  padding:
    90px 6vw 70px;

  display:
    grid;

  grid-template-columns:
    repeat(4,1fr);

  gap:
    24px;
}


.temple-exit .exit-card {

  position: relative;

  padding:
    28px 22px;

  background:

    linear-gradient(
      145deg,
      rgba(83,58,28,.9),
      rgba(34,21,11,.96)
    );

  border:
    2px solid rgba(195,150,73,.45);

  border-radius:
    2px;

  box-shadow:

    inset 0 0 0 5px rgba(0,0,0,.18),

    inset 0 0 25px rgba(0,0,0,.4),

    0 18px 35px rgba(0,0,0,.55);
}


.temple-exit .exit-card::before {

  content: "𓋹";

  position: absolute;

  left: 50%;
  top: -17px;

  transform:
    translateX(-50%);

  width: 34px;
  height: 34px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  background:
    #5c3e1e;

  border:
    1px solid #b48a45;

  color:
    #dfbc68;

  font-size:
    17px;
}


.temple-exit .exit-card h3 {

  margin:
    0 0 15px;

  padding-bottom:
    12px;

  border-bottom:
    1px solid rgba(208,166,86,.25);

  color:
    #e4c578;

  font-family:
    Georgia,
    serif;

  font-size:
    .9rem;

  letter-spacing:
    .12em;

  text-transform:
    uppercase;
}


.temple-exit .exit-card p,
.temple-exit .exit-card a {

  color:
    #d3bf91;

  font-size:
    .92rem;

  line-height:
    1.7;

  text-decoration:
    none;
}


.temple-exit .exit-card a:hover {

  color:
    #f0d27e;

}


/* ============================================================
   SOCIAL
   ============================================================ */

.temple-exit .social-row {

  display:
    flex;

  flex-wrap:
    wrap;

  gap:
    8px;
}


.temple-exit .social-pill {

  padding:
    7px 12px;

  border:
    1px solid rgba(203,163,79,.4);

  border-radius:
    2px;

  color:
    #d7c18c !important;

  font-size:
    .7rem !important;

  letter-spacing:
    .08em;
}


/* ============================================================
   SIGN OFF
   ============================================================ */

.temple-exit .exit-signoff {

  position:
    relative;

  z-index:
    12;

  margin:
    0;

  padding:
    0 6vw 70px;

  text-align:
    center;

  color:
    #a88a52;

  font-family:
    Georgia,
    serif;

  font-size:
    .72rem;

  letter-spacing:
    .3em;

  text-transform:
    uppercase;
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width:900px){

  .temple-exit .exit-footer {

    grid-template-columns:
      repeat(2,1fr);

  }

  .temple-exit .exit-gate-wrap {

    width:
      min(78vw,500px);

  }

}


@media (max-width:560px){

  .temple-exit {

    min-height:
      230vh;

  }

  .temple-exit .exit-footer {

    grid-template-columns:
      1fr;

    padding:
      70px 7vw;

  }

  .temple-exit .exit-gate-wrap {

    width:
      90vw;

    height:
      60vh;

  }

  .temple-exit .exit-farewell {

    top:
      54%;

  }

}


/* ============================================================
   REDUCED MOTION
   ============================================================ */

@media (prefers-reduced-motion:reduce){

  .temple-exit .exit-door {

    transition:
      none;

  }

  .temple-exit .exit-sky::before,
  .temple-exit::after,
  .temple-exit .exit-farewell::before {

    animation:
      none;

  }

}

