.temple-tablet{
  position:relative;
  cursor:pointer;
  border:none;
  -webkit-tap-highlight-color:transparent;
  display:flex;
  flex-direction:column;
  align-items:center;
  text-align:center;
  padding:2.2em 1.4em 1.8em;
  min-height:220px;
  color:inherit;
  font-family:inherit;

  background:
    radial-gradient(ellipse at 30% 15%, rgba(255,240,200,.10), transparent 55%),
    linear-gradient(155deg, var(--sandstone-lt) 0%, var(--sandstone) 42%, var(--stone-600) 100%);

  clip-path:polygon(
    3% 6%, 22% 0%, 78% 2%, 97% 8%,
    100% 30%, 98% 70%, 100% 92%,
    80% 100%, 24% 98%, 2% 94%,
    0% 68%, 3% 32%
  );

  box-shadow:
    0 0 0 3px var(--stone-800),
    0 0 0 5px rgba(212,175,55,.4),
    0 18px 34px rgba(0,0,0,.55),
    inset 0 0 40px rgba(0,0,0,.4),
    inset 0 2px 0 rgba(255,236,190,.25);

  transition:
    transform .5s var(--ease-heavy),
    box-shadow .5s var(--ease-heavy),
    filter .5s var(--ease-heavy);
  transform:translateY(0) scale(1);
  isolation:isolate;
  overflow:hidden;
}

.temple-tablet::before{
  content:"";
  position:absolute; inset:10px;
  border:1px solid rgba(212,175,55,.55);
  background-image:
    repeating-linear-gradient(0deg, rgba(43,33,24,.35) 0 2px, transparent 2px 22px),
    repeating-linear-gradient(90deg, rgba(43,33,24,.28) 0 2px, transparent 2px 22px);
  opacity:.5;
  mix-blend-mode:multiply;
  pointer-events:none;
  z-index:1;
}

.temple-tablet::after{
  content:"";
  position:absolute; inset:0;
  box-shadow:inset 0 0 0 1px rgba(244,211,94,0);
  border-radius:2px;
  pointer-events:none;
  z-index:5;
  transition:box-shadow .5s var(--ease-heavy);
}
.temple-tablet:hover::after,
.temple-tablet:focus-visible::after{
  box-shadow:inset 0 0 0 1px rgba(244,211,94,.9), inset 0 0 26px rgba(244,211,94,.25);
}

/* middle tablet receives slightly more light */
.temple-tablet:nth-child(2){
  background:
    radial-gradient(ellipse at 35% 12%, rgba(255,246,220,.22), transparent 60%),
    linear-gradient(155deg, var(--sandstone-lt) 0%, var(--sandstone) 40%, var(--stone-600) 100%);
  box-shadow:
    0 0 0 3px var(--stone-800),
    0 0 0 5px rgba(244,211,94,.55),
    0 20px 40px rgba(0,0,0,.55),
    inset 0 0 40px rgba(0,0,0,.35),
    inset 0 2px 0 rgba(255,246,220,.4),
    0 0 34px rgba(244,211,94,.18);
}

.temple-tablet:hover,
.temple-tablet:focus-visible{
  transform:translateY(-8px) scale(1.03);
  box-shadow:
    0 0 0 3px var(--stone-800),
    0 0 0 5px var(--gold-bright),
    0 26px 46px rgba(0,0,0,.6),
    inset 0 0 40px rgba(0,0,0,.3),
    inset 0 2px 0 rgba(255,246,220,.4),
    0 0 44px rgba(244,211,94,.35);
}
.temple-tablet:active{
  transform:translateY(-2px) scale(.98);
  transition-duration:.12s;
}

.temple-tablet-glow{
  position:absolute; inset:-20%;
  background:radial-gradient(circle at 50% 30%, rgba(46,139,125,.35), rgba(212,175,55,.15) 45%, transparent 72%);
  opacity:.3;
  transition:opacity .5s var(--ease-heavy);
  z-index:0;
  pointer-events:none;
  animation:tabletAura 5s ease-in-out infinite;
}
@keyframes tabletAura{
  0%,100%{ opacity:.25; }
  50%    { opacity:.5; }
}
.temple-tablet:hover .temple-tablet-glow,
.temple-tablet:focus-visible .temple-tablet-glow{ opacity:.85; }

.temple-tablet-sweep{
  position:absolute; inset:0;
  background:linear-gradient(100deg, transparent 30%, rgba(255,255,255,.35) 45%, transparent 60%);
  background-size:250% 100%;
  background-position:150% 0;
  mix-blend-mode:overlay;
  opacity:0;
  z-index:3;
  pointer-events:none;
  transition:opacity .3s;
}
.temple-tablet:hover .temple-tablet-sweep,
.temple-tablet:focus-visible .temple-tablet-sweep{
  opacity:1;
  animation:titleShimmer 1.4s ease-out; /* reuses existing @keyframes titleShimmer, unmodified */
}

.temple-tablet-icon{
  position:relative; z-index:4;
  display:flex; align-items:center; justify-content:center;
  width:56px; height:56px;
  margin-bottom:.5em;
  color:var(--gold);
  filter:drop-shadow(0 0 6px rgba(212,175,55,.4));
  transition:transform .5s var(--ease-heavy), color .5s, filter .5s;
}
.tablet-icon-svg{ width:100%; height:100%; }
.temple-tablet:hover .temple-tablet-icon,
.temple-tablet:focus-visible .temple-tablet-icon{
  color:var(--gold-bright);
  filter:drop-shadow(0 0 14px rgba(244,211,94,.85)) drop-shadow(0 0 22px rgba(46,139,125,.4));
  transform:rotate(3deg) scale(1.06);
}

.temple-tablet-title{
  position:relative; z-index:4;
  display:block;
  font-family:'Cinzel', serif;
  font-weight:700;
  font-size:clamp(.92rem,1.6vw,1.08rem);
  letter-spacing:.09em;
  color:var(--stone-900);
  text-shadow:
    0 1px 0 rgba(255,246,220,.5),
    0 -1px 1px rgba(0,0,0,.45);
  margin-bottom:.4em;
  transition:text-shadow .5s var(--ease-heavy);
}
.temple-tablet:hover .temple-tablet-title,
.temple-tablet:focus-visible .temple-tablet-title{
  text-shadow:
    0 1px 0 rgba(255,246,220,.7),
    0 -1px 1px rgba(0,0,0,.5),
    0 0 16px rgba(244,211,94,.35);
}

.temple-tablet-desc{
  position:relative; z-index:4;
  display:block;
  font-style:italic;
  font-size:.82rem;
  color:var(--stone-700);
  opacity:.85;
  max-width:22ch;
}

/* click ripple + gold flash — classes toggled by the small JS addition below */
.temple-tablet-ripple{
  position:absolute; top:50%; left:50%;
  width:16px; height:16px;
  margin:-8px 0 0 -8px;
  border-radius:50%;
  border:2px solid var(--gold-bright);
  opacity:.9;
  z-index:6;
  pointer-events:none;
  animation:templeRippleOut .7s var(--ease-heavy) forwards;
}
@keyframes templeRippleOut{
  to{ width:340px; height:340px; margin:-170px 0 0 -170px; opacity:0; }
}

.temple-tablet-flash{
  position:absolute; inset:0;
  background:radial-gradient(circle at 50% 40%, rgba(244,211,94,.55), transparent 70%);
  opacity:0;
  z-index:6;
  pointer-events:none;
  animation:templeFlash .5s ease-out forwards;
}
@keyframes templeFlash{
  0%{ opacity:.9; }
  100%{ opacity:0; }
}

.temple-tablet.is-clicked{
