/* ==========================================================
   PATCH: STATISTICS SECTION — SANDSTONE TABLET UPGRADE
   Pure override layer. Original .stat-grid / .stat-card /
   .stat-icon / .stat-number / .stat-label rules, spacing,
   and the visible/hover reveal transition are all left intact.
========================================================== */

#statGrid.stat-grid{ align-items:end; } /* lets the raised middle tablet read as taller, no gap/column change */

/* stacking context so decorative layers can sit behind existing content */
.stat-card.stat-card--relic{ isolation:isolate; overflow:visible; }

/* keep original background/border as base, layer tablet look on top */
.stat-card.stat-card--relic{
  background:
    radial-gradient(ellipse at 30% 10%, rgba(255,240,200,.14), transparent 55%),
    linear-gradient(160deg, var(--sandstone-lt) 0%, var(--sandstone) 45%, var(--stone-600) 100%);
  border-color:rgba(212,175,55,.4);
  box-shadow:
    0 0 0 3px var(--stone-800),
    0 0 0 5px rgba(212,175,55,.35),
    0 26px 50px rgba(0,0,0,.6),
    inset 0 0 46px rgba(0,0,0,.4),
    inset 0 2px 0 rgba(255,236,190,.25);
}
.stat-card.stat-card--relic:hover{
  box-shadow:
    0 0 0 3px var(--stone-800),
    0 0 0 5px var(--gold-bright),
    0 32px 60px rgba(0,0,0,.65),
    inset 0 0 46px rgba(0,0,0,.35),
    inset 0 2px 0 rgba(255,246,220,.35),
    0 0 34px rgba(244,211,94,.28);
  border-color:var(--gold-bright);
}

/* visual hierarchy — cosmetic transform only, no spacing/grid change */
.stat-card.stat-card--relic.visible{ transform:translateY(-4px); }
.stat-card.stat-card--relic.stat-card--tall.visible{ transform:translateY(-22px) scale(1.05); }
.stat-card.stat-card--relic.visible:hover{ transform:translateY(-16px); }
.stat-card.stat-card--relic.stat-card--tall.visible:hover{ transform:translateY(-34px) scale(1.06); }

/* carved stone striations */
.stat-card-texture{
  position:absolute; inset:10px;
  border:1px solid rgba(212,175,55,.5);
  background-image:
    repeating-linear-gradient(0deg, rgba(43,33,24,.32) 0 2px, transparent 2px 20px),
    repeating-linear-gradient(90deg, rgba(43,33,24,.24) 0 2px, transparent 2px 20px);
  opacity:.45;
  mix-blend-mode:multiply;
  pointer-events:none;
  z-index:0;
  border-radius:inherit;
}

/* warm ambient glow, breathing like the entrance torch-glow */
.stat-card-glow{
  position:absolute; inset:-18%;
  background:radial-gradient(ellipse at 50% 30%, rgba(255,183,90,.28), rgba(212,175,55,.1) 45%, transparent 72%);
  opacity:.35;
  z-index:-1;
  pointer-events:none;
  animation:statGlowPulse 5s ease-in-out infinite;
}
@keyframes statGlowPulse{ 0%,100%{ opacity:.3; } 50%{ opacity:.6; } }
.stat-card.stat-card--relic:hover .stat-card-glow{ opacity:.9; }

/* carved hieroglyph watermark, unique per tablet via JS-injected content */
.stat-hieroglyph{

    position:absolute;

    top:18px;
    left:50%;

    transform:translateX(-50%);

    width:58px;
    height:58px;

    opacity:.14;

    color:#3d2b18;

    filter:none;

    z-index:0;

    pointer-events:none;

}

/* torches — positioning only; visuals/animation come from your existing .torch rules */
.stat-torch{ top:-14%; z-index:1; transform:scale(.78); transition:transform .5s var(--ease-heavy); }
.stat-torch-left{ left:-6%; }
.stat-torch-right{ right:-6%; }
.stat-card.stat-card--relic:hover .stat-torch{ transform:scale(.9); }

/* stone plinth beneath each tablet */
.stat-pedestal{
  position:absolute; bottom:-14px; left:50%;
  transform:translateX(-50%);
  width:70%; height:14px;
  border-radius:4px 4px 10px 10px;
  background:linear-gradient(to bottom, var(--stone-600), var(--stone-800));
  box-shadow:0 10px 18px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,220,170,.2);
  z-index:0;
}

/* lift existing icon/number/label above the new decorative layers — no spacing/size change */
.stat-card.stat-card--relic .stat-icon,
.stat-card.stat-card--relic .stat-number,
.stat-card.stat-card--relic .stat-label{
  position:relative;
  z-index:2;
}

/* gold medallion ring around the original icon — box-shadow only, no width/margin/padding change */
.stat-card.stat-card--relic .stat-icon{
  border-radius:50%;
  box-shadow:
    0 0 0 8px rgba(20,15,10,.4),
    0 0 0 10px rgba(212,175,55,.55),
    0 8px 14px rgba(0,0,0,.4);
  transition:box-shadow .5s var(--ease-heavy), transform .5s var(--ease-heavy);
}
.stat-card.stat-card--relic:hover .stat-icon{
  transform:rotate(4deg) scale(1.06);
  box-shadow:
    0 0 0 8px rgba(20,15,10,.4),
    0 0 0 10px var(--gold-bright),
    0 0 20px rgba(244,211,94,.5);
}

/* numbers read as chiselled into stone — same gradient fill, added engraved shadow */
.stat-card.stat-card--relic .stat-number{
  text-shadow:
    0 1px 0 rgba(255,236,190,.4),
    0 -1px 1px rgba(0,0,0,.6),
    0 2px 6px rgba(0,0,0,.35);
}
.stat-card.stat-card--relic:hover .stat-number{
  text-shadow:
    0 1px 0 rgba(255,246,220,.6),
    0 -1px 1px rgba(0,0,0,.65),
    0 0 14px rgba(244,211,94,.5);
}
.stat-card.stat-card--relic .stat-label{
  text-shadow:0 1px 0 rgba(0,0,0,.5);
}

/* localized floating dust */
.stat-dust{ position:absolute; inset:0; overflow:hidden; pointer-events:none; z-index:0; border-radius:inherit; }
.stat-dust-mote{
  position:absolute; bottom:-6%;
  width:2.4px; height:2.4px; border-radius:50%;
  background:radial-gradient(circle, rgba(244,211,94,.9), rgba(244,211,94,0) 70%);
  opacity:0;
  animation-name:statDustFloat;
  animation-timing-function:linear;
  animation-iteration-count:infinite;
}
@keyframes statDustFloat{
  0%  { transform:translate(0,0); opacity:0; }
  10% { opacity:.7; }
  88% { opacity:.3; }
  100%{ transform:translate(var(--sdrift,10px), -125%); opacity:0; }
}

@media (max-width:720px){
  #statGrid.stat-grid{ align-items:stretch; }
  .stat-card.stat-card--relic.stat-card--tall.visible{ transform:translateY(0) scale(1); }
  .stat-card.stat-card--relic.stat-card--tall.visible:hover{ transform:translateY(-12px); }
  .stat-torch{ display:none; }
}

@media (prefers-reduced-motion: reduce){
  .stat-card-glow, .stat-dust-mote{ animation:none !important; }
}

