/* ============================================================
   CONTINUOUS TEMPLE JOURNEY
   Reduce dead space between major halls
============================================================ */

.corridor {
    min-height: 45vh;
}

.hall {
    min-height: 145vh;
}

.stories {
    min-height: 185vh;
}

.games-chamber {
    min-height: 155vh;
}

.student-hall {
    min-height: 95vh;
}

.temple-exit {
    min-height: 130vh;
}
/* ============================================================
   TEMPLE WORLD FLOW — TEST 01
   Connect halls visually without changing their heights
============================================================ */

/* 1. Give every hall a visible threshold at its bottom.
   This is NOT a new corridor and does not add page height. */

.hall,
.stories,
.games-chamber,
.student-hall {
    position: relative;
}


/* 2. A physical stone threshold between rooms */

.hall::after,
.stories::after,
.games-chamber::after,
.student-hall::after {
    content: "";
    position: absolute;
    left: 7%;
    right: 7%;
    bottom: 0;

    height: 42px;

    background:
        linear-gradient(
            to bottom,
            #8f713f 0%,
            #5b4328 35%,
            #2b2118 100%
        );

    border-top: 2px solid rgba(244,211,94,.35);

    box-shadow:
        0 -8px 20px rgba(0,0,0,.35),
        inset 0 3px 4px rgba(255,230,170,.15),
        0 12px 28px rgba(0,0,0,.65);

    z-index: 20;
    pointer-events: none;
}


/* 3. Gold path line.
   It visually tells the eye: "keep going". */

.hall::before,
.stories::before,
.games-chamber::before,
.student-hall::before {
    content: "";

    position: absolute;
    left: 50%;
    bottom: 0;

    width: 2px;
    height: 120px;

    transform: translateX(-50%);

    background:
        linear-gradient(
            to bottom,
            transparent,
            rgba(244,211,94,.18),
            rgba(244,211,94,.65)
        );

    box-shadow:
        0 0 14px rgba(244,211,94,.22);

    z-index: 21;
    pointer-events: none;
}


/* 4. Don't let the next section begin as a hard black cut.
   Only its FIRST 90px receive a subtle architectural glow. */

.stories {
    background-color: #0a0705;
}

.games-chamber {
    background-color: #070503;
}

.student-hall {
    background-color: #100b07;
}

.stories-entry-glow,
.chamber-entry-glow,
.student-entry-glow {
    height: 90px;
    opacity: .55;
}


/* 5. The actual transition is created by the existing
   entry glow + threshold, not by adding another section. */

.hall + .stories,
.stories + .games-chamber,
.games-chamber + .student-hall,
.student-hall + .temple-exit {
    position: relative;
}


/* 6. Slightly reveal the next area before the previous one
   completely disappears. */

.hall + .stories::after,
.stories + .games-chamber::after,
.games-chamber + .student-hall::after,
.student-hall + .temple-exit::after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;

    height: 70px;

    background:
        linear-gradient(
            to bottom,
            rgba(212,175,55,.08),
            transparent
        );

    pointer-events: none;
    z-index: 4;
}
/* =========================================================
   TEST — TIGHTEN GAMES CHAMBER END
   Does not change section height
========================================================= */

.games-chamber .portal-grid {
    padding-bottom: 4vh;
}
/* ============================================================
   TEMPLE DESCENT
   Entrance → Descending Stair → Library Services Hall
============================================================ */

.corridor {
    position: relative;
    min-height: 80vh;
    overflow: hidden;
    perspective: 1200px;
}


/* Remove old flat floor */

.corridor-floor {
    display: none !important;
}


/* ============================================================
   DESCENT WORLD
============================================================ */

.temple-descent {
    position: absolute;

    left: 50%;
    bottom: 0;

    transform: translateX(-50%);

    width: 100%;
    height: 100%;

    z-index: 6;

    perspective: 1200px;
}


/* ============================================================
   SIDE TEMPLE WALLS
============================================================ */

.descent-wall {
    position: absolute;

    bottom: 0;

    width: 30%;
    height: 99%;

    background:
        linear-gradient(
            145deg,
            #71502d 0%,
            #4b3420 35%,
            #241910 75%,
            #120c08 100%
        );

    border-top: 2px solid rgba(244,211,94,.38);

    box-shadow:
        inset 0 0 45px rgba(0,0,0,.65),
        inset 0 0 12px rgba(255,220,160,.08),
        0 0 30px rgba(0,0,0,.45);
}


/* Left */

.descent-wall-left {
    left: 0;

    clip-path: polygon(
        0 0,
        100% 16%,
        100% 100%,
        0 100%
    );
}


/* Right */

.descent-wall-right {
    right: 0;

    clip-path: polygon(
        0 16%,
        100% 0,
        100% 100%,
        0 100%
    );
}


/* Hieroglyphs */

.wall-relief {
    position: absolute;

    top: 30%;
    left: 25%;

    color: rgba(244,211,94,.28);

    font-family: serif;

    font-size: clamp(1.2rem, 2.5vw, 2rem);

    letter-spacing: .35em;

    writing-mode: vertical-rl;

    text-shadow:
        0 0 10px rgba(212,175,55,.15);
}

.wall-relief.second {
    top: 55%;
    left: 55%;

    opacity: .6;
}


/* ============================================================
   BIG DESCENDING STAIR
============================================================ */

.descent-stairs {

    position: absolute;

    left: 50%;
    bottom: 24%;

    transform: translateX(-50%);

    width: 64%;
    height: 60%;

    z-index: 8;

    display: flex;

    flex-direction: column;

    justify-content: flex-end;

    align-items: center;

}


/* Every stair */

.step {

    position: relative;

    flex-shrink: 0;

    height: 7.5%;

    background:
        linear-gradient(
            to bottom,
            #9b7743 0%,
            #6c4d2b 22%,
            #3b291b 65%,
            #21170f 100%
        );

    border-top:
        2px solid rgba(244,211,94,.42);

    box-shadow:
        0 -2px 5px rgba(255,220,150,.08),
        0 8px 15px rgba(0,0,0,.65);

}


/* Perspective */

.step-1  { width:100%; }
.step-2  { width:94%; }
.step-3  { width:88%; }
.step-4  { width:82%; }
.step-5  { width:76%; }
.step-6  { width:70%; }
.step-7  { width:64%; }
.step-8  { width:58%; }
.step-9  { width:52%; }
.step-10 { width:46%; }
.step-11 { width:40%; }
.step-12 { width:34%; }


/* Golden edges */

.descent-stairs::before,
.descent-stairs::after {

    content: "";

    position: absolute;

    bottom: 0;

    width: 5px;
    height: 100%;

    background:
        linear-gradient(
            to top,
            #f4d35e,
            rgba(244,211,94,.15)
        );

    box-shadow:
        0 0 18px rgba(244,211,94,.25);

    z-index: 20;
}

.descent-stairs::before {
    left: 0;
}

.descent-stairs::after {
    right: 0;
}


/* ============================================================
   TORCHES
============================================================ */

.descent-torch {

    position: absolute;

    width: 14px;
    height: 42px;

    bottom: 43%;

    background:
        linear-gradient(
            to bottom,
            #ffb14e,
            #c87825 25%,
            #3b2918 26%,
            #17100a 100%
        );

    border-radius: 8px 8px 3px 3px;

    box-shadow:
        0 0 15px rgba(255,145,55,.7),
        0 0 40px rgba(255,145,55,.25);

    z-index: 30;
}

.descent-torch.left {
    left: 17%;
}

.descent-torch.right {
    right: 17%;
}


/* ============================================================
   NEXT HALL — LARGE PHARAONIC ENTRANCE
============================================================ */

.next-hall-gate {

    position: absolute;

    left: 50%;
    bottom: 0;

    transform: translateX(-50%);

    width: 62%;
    height: 62%;

    z-index: 25;

}


/* Massive gate pillars */

.gate-pillar {

    position: absolute;

    bottom: 0;

    width: 15%;

    height: 100%;

    background:
        repeating-linear-gradient(
            to right,
            #c49a59 0 8%,
            #806036 8% 13%,
            #d4ad6b 13% 18%
        );

    box-shadow:
        inset -10px 0 18px rgba(0,0,0,.5),
        inset 8px 0 12px rgba(255,230,180,.15);
}

.gate-pillar-left {
    left: 0;
}

.gate-pillar-right {
    right: 0;
}


/* Pillar capitals */

.gate-pillar::before {

    content: "";

    position: absolute;

    top: -3%;

    left: -20%;

    width: 140%;
    height: 8%;

    background:
        linear-gradient(
            to bottom,
            #f0cf7b,
            #9c7539
        );

    border-radius: 4px;

    box-shadow:
        0 4px 12px rgba(0,0,0,.6);
}


/* ============================================================
   GATE TOP
============================================================ */

.gate-top {

    position: absolute;

    top: -4%;
    left: 7%;

    width: 86%;
    height: 18%;

    background:
        linear-gradient(
            to bottom,
            #d6b36b,
            #806034 45%,
            #3a2818
        );

    clip-path:
        polygon(
            5% 100%,
            10% 30%,
            25% 0,
            75% 0,
            90% 30%,
            95% 100%
        );

    border-bottom:
        3px solid rgba(244,211,94,.55);

    box-shadow:
        0 0 30px rgba(212,175,55,.15);
}

.gate-top span {

    position: absolute;

    left: 50%;
    top: 15%;

    transform: translateX(-50%);

    color: #f4d35e;

    font-size: clamp(1.5rem, 3vw, 2.5rem);

    text-shadow:
        0 0 14px rgba(244,211,94,.7);
}


/* ============================================================
   DARK GATE OPENING
============================================================ */

.gate-opening {

    position: absolute;

    left: 15%;
    right: 15%;

    bottom: 0;

    height: 84%;

    overflow: hidden;

    background:
        radial-gradient(
            ellipse at 50% 45%,
            rgba(255,190,100,.38),
            rgba(212,175,55,.08) 38%,
            #080604 75%
        );

    border:
        2px solid rgba(212,175,55,.45);

    box-shadow:
        inset 0 0 55px rgba(0,0,0,.85),
        0 0 35px rgba(212,175,55,.16);
}


/* Light coming from the next hall */

.gate-light {

    position: absolute;

    left: 50%;
    top: 20%;

    transform: translateX(-50%);

    width: 75%;
    height: 70%;

    background:
        radial-gradient(
            ellipse,
            rgba(255,220,150,.35),
            rgba(212,175,55,.08) 45%,
            transparent 75%
        );

    filter: blur(12px);

    animation:
        templeGateGlow 4s ease-in-out infinite;
}

@keyframes templeGateGlow {

    0%,100% {
        opacity: .55;
        transform: translateX(-50%) scale(.95);
    }

    50% {
        opacity: .9;
        transform: translateX(-50%) scale(1.05);
    }

}


/* ============================================================
   GATE TEXT
============================================================ */

.gate-title {

    position: absolute;

    left: 50%;
    top: 48%;

    transform: translate(-50%, -50%);

    width: 90%;

    text-align: center;

    font-family: 'Cinzel', serif;

    font-size: clamp(.85rem, 1.8vw, 1.3rem);

    letter-spacing: .18em;

    color: #f4d35e;

    text-shadow:
        0 0 12px rgba(244,211,94,.45);

    z-index: 5;
}

.gate-subtitle {

    position: absolute;

    left: 50%;
    top: 59%;

    transform: translateX(-50%);

    width: 90%;

    text-align: center;

    font-family: 'Cormorant Garamond', serif;

    font-style: italic;

    font-size: clamp(1rem, 1.8vw, 1.4rem);

    color: #d8bb83;

    opacity: .8;

    z-index: 5;
}


/* ============================================================
   DARKEN OLD CORRIDOR CENTER
============================================================ */

.corridor::after {

    content: "";

    position: absolute;

    left: 50%;
    bottom: 0;

    transform: translateX(-50%);

    width: 55%;
    height: 85%;

    background:
        radial-gradient(
            ellipse at 50% 70%,
            transparent 0%,
            rgba(0,0,0,.18) 55%,
            rgba(0,0,0,.65) 100%
        );

    z-index: 5;

    pointer-events: none;
}


/* Keep the stair above the atmosphere */

.temple-descent,
.next-hall-gate {
    isolation: isolate;
}


/* ============================================================
   MOBILE
============================================================ */

@media (max-width:720px) {

    .corridor {
        min-height: 84vh;
    }

    .descent-wall {
        width: 27%;
    }

    .descent-stairs {
        width: 72%;
    }

    .next-hall-gate {
        width: 78%;
        height: 58%;
    }

    .gate-title {
        letter-spacing: .08em;
    }

    .descent-torch.left {
        left: 10%;
    }

    .descent-torch.right {
        right: 10%;
    }
}
/* ============================================================
   CONTINUOUS FLOOR — FROM GATE TO SERVICES
============================================================ */

/* ============================================================
   INNER TEMPLE CEILING
============================================================ */

.hall-entry-glow{
    height:42vh !important;

    background:
        radial-gradient(
            ellipse at 50% 5%,
            rgba(255,210,130,.42),
            rgba(212,175,55,.12) 38%,
