    position:absolute;

    top:12px;
    left:50%;

    transform:translateX(-50%);

    color:
        rgba(244,211,94,.45);

    font-size:20px;

    text-shadow:
        0 0 12px rgba(244,211,94,.25);
}


.relic-station:hover{

    transform:
        translateY(-12px);

    background:
