}
.relic-btn:hover .relic-figure,
.relic-btn:focus-visible .relic-figure{
  filter:
    sepia(.35) saturate(1.4) hue-rotate(-6deg)
    drop-shadow(0 2px 0 rgba(255,246,220,.5))
    drop-shadow(0 -1px 1px rgba(0,0,0,.55))
    drop-shadow(0 0 22px rgba(244,211,94,.75));
}
 
/* ---------- 6. Pedestal becomes a small engraved gold seal ---------- */
.relic-pedestal{
  position:relative;
  z-index:3;
  width:54px !important;
  height:54px !important;
  margin-top:10px;
  border-radius:50%;
  background:radial-gradient(circle at 35% 30%, var(--gold-bright), var(--gold-dim) 70%, var(--stone-700) 100%);
  border:2px solid rgba(20,15,10,.5);
  box-shadow:
    inset 0 0 10px rgba(0,0,0,.5),
    inset 0 2px 2px rgba(255,246,220,.4),
    0 6px 12px rgba(0,0,0,.5);
