    inset 0 0 55px rgba(0,0,0,.5),
    inset 0 3px 0 rgba(255,236,190,.14),
    inset 0 -10px 22px rgba(0,0,0,.5),
    0 0 34px rgba(244,211,94,.28);
}

/* Subtle carved-stone grain (organic, not a grid) + thin engraved
   antique-gold inner border */
.relic-btn::before{
  content:"";
  position:absolute; inset:9px;
  border:1px solid rgba(212,175,55,.45);
  box-shadow:
    inset 0 0 0 1px rgba(0,0,0,.35),
    inset 0 0 22px rgba(0,0,0,.4);
  background-image:
    radial-gradient(circle at 18% 22%, rgba(0,0,0,.25) 0 6px, transparent 7px),
    radial-gradient(circle at 76% 14%, rgba(0,0,0,.2) 0 5px, transparent 6px),
    radial-gradient(circle at 62% 68%, rgba(0,0,0,.22) 0 7px, transparent 8px),
    radial-gradient(circle at 30% 82%, rgba(0,0,0,.2) 0 5px, transparent 6px),
    radial-gradient(circle at 85% 55%, rgba(255,220,170,.05) 0 6px, transparent 7px),
    radial-gradient(circle at 12% 60%, rgba(255,220,170,.04) 0 5px, transparent 6px);
  opacity:.6;
  mix-blend-mode:multiply;
  pointer-events:none;
  z-index:1;
}

/* Small ornamental frieze band near the top, with hieroglyphs woven in —
   replaces the earlier single centered glyph */
.relic-btn::after{
  content:"𓉐 𓋹 𓊪 𓆣 𓊪 𓋹 𓉐";
  position:absolute;
  top:9px; left:12%; right:12%;
  text-align:center;
  font-size:9px;
  letter-spacing:.12em;
  line-height:1;
  color:rgba(212,175,55,.55);
  text-shadow:0 1px 0 rgba(0,0,0,.5);
