.threshold-lintel::after{ /* engraved band detail */
  content:"";
  position:absolute; inset:30% 6%;
  background:repeating-linear-gradient(90deg, rgba(43,33,24,.4) 0 3%, transparent 3% 6%);
  opacity:.7;
}

/* ---------- Doorway opening + glow ---------- */
.threshold-opening{
  position:absolute; left:50%; top:27.5%; bottom:0;
  transform:translateX(-50%);
  width:min(30vw,280px);
  background:radial-gradient(ellipse at 50% 30%, rgba(255,190,110,.28), #0a0503 70%);
  border-left:2px solid rgba(212,175,55,.4);
  border-right:2px solid rgba(212,175,55,.4);
  box-shadow:inset 0 0 60px rgba(0,0,0,.85);
