  background:radial-gradient(ellipse at 50% 20%, rgba(255,210,140,.55), transparent 65%);
  animation:thresholdBreathe 6s ease-in-out infinite;
}
@keyframes thresholdBreathe{
  0%,100%{ opacity:.55; }
  50%    { opacity:.95; }
}

/* ---------- Dust particles inside the doorway ---------- */
.threshold-dust{
  position:absolute; inset:0;
  background-image:
    radial-gradient(circle at 30% 70%, rgba(244,211,94,.8) 0 1.5px, transparent 2px),
    radial-gradient(circle at 65% 40%, rgba(244,211,94,.6) 0 1px,   transparent 2px),
    radial-gradient(circle at 50% 85%, rgba(244,211,94,.7) 0 1.5px, transparent 2px),
    radial-gradient(circle at 20% 30%, rgba(244,211,94,.5) 0 1px,   transparent 2px),
    radial-gradient(circle at 80% 60%, rgba(244,211,94,.6) 0 1.5px, transparent 2px);
  animation:thresholdDustDrift 7s linear infinite;
}
@keyframes thresholdDustDrift{
  0%  { transform:translateY(0)    scale(1);   opacity:.7; }
  50% { transform:translateY(-8%)  scale(1.03); opacity:1;  }
  100%{ transform:translateY(0)    scale(1);   opacity:.7; }
}

/* ---------- Caption ---------- */
.threshold-caption{
  position:absolute; bottom:4%; left:50%;
  transform:translateX(-50%);
  width:min(80vw,420px);
  text-align:center;
  font-style:italic;
  font-size:clamp(.95rem,1.8vw,1.15rem);
  color:var(--sandstone-lt);
  text-shadow:0 2px 10px rgba(0,0,0,.7);
  opacity:.85;
}

/* ---------- Hover interaction (activates on hover anywhere in the hall) ---------- */
.hall:hover .threshold-light{ animation-duration:3.4s; }
