            108deg,
            transparent 49.5%,
            rgba(212,175,55,.12) 50%,
            transparent 50.5%
        );

    opacity:.7;
}


/* horizontal carved floor cuts */

.arch-floor::after{
    content:"";
    position:absolute;
    inset:0;

    background:
        repeating-linear-gradient(
            to top,
            transparent 0 11%,
            rgba(0,0,0,.35) 11% 11.8%
        );

