    align-items: start !important;
}

/* ---------------------------------------------------------
   CARD BASE
--------------------------------------------------------- */

.relic-grid > * {
    position: relative;
    isolation: isolate;

    transform:
        translateY(var(--card-y, 0px))
        rotate(var(--card-rotate, 0deg));

    transition:
        transform 0.45s cubic-bezier(.2,.8,.2,1),
        filter 0.45s ease,
        box-shadow 0.45s ease;

    will-change: transform;
}


/* ---------------------------------------------------------
   DIFFERENT HEIGHTS
   الكروت مش كلها على خط واحد
--------------------------------------------------------- */

.relic-grid > *:nth-child(1) {
    --card-y: 25px;
    --card-rotate: -0.7deg;
}

.relic-grid > *:nth-child(2) {
    --card-y: -18px;
    --card-rotate: 0.5deg;
}

.relic-grid > *:nth-child(3) {
    --card-y: 32px;
    --card-rotate: -0.4deg;
}

.relic-grid > *:nth-child(4) {
    --card-y: -28px;
    --card-rotate: 0.8deg;
}

.relic-grid > *:nth-child(5) {
    --card-y: 15px;
}

.relic-grid > *:nth-child(6) {
    --card-y: -22px;
}


/* ---------------------------------------------------------
   ANCIENT FLOATING MOTION
--------------------------------------------------------- */

@keyframes relicFloat1 {
    0%,100% {
        transform:
            translateY(var(--card-y))
            rotate(var(--card-rotate));
    }

    50% {
        transform:
            translateY(calc(var(--card-y) - 7px))
            rotate(calc(var(--card-rotate) + .25deg));
    }
}

@keyframes relicFloat2 {
    0%,100% {
        transform:
            translateY(var(--card-y))
            rotate(var(--card-rotate));
    }

    50% {
        transform:
            translateY(calc(var(--card-y) + 8px))
            rotate(calc(var(--card-rotate) - .25deg));
    }
}

.relic-grid > *:nth-child(odd) {
    animation:
        relicFloat1 5.5s ease-in-out infinite;
}

.relic-grid > *:nth-child(even) {
    animation:
        relicFloat2 6.5s ease-in-out infinite;
}


/* ---------------------------------------------------------
   CARD ATMOSPHERE
--------------------------------------------------------- */

.relic-grid > *::before {
    content: "";

    position: absolute;
    inset: 1px;

    pointer-events: none;

    z-index: -1;

    background:
        radial-gradient(
            ellipse at 50% 15%,
            rgba(244,211,94,.12),
            transparent 48%
        );

    opacity: .55;

    transition:
        opacity .4s ease,
        transform .5s ease;
}


/* ---------------------------------------------------------
   GOLDEN EDGE
--------------------------------------------------------- */

.relic-grid > *::after {
    content: "";

    position: absolute;

    left: 10%;
    right: 10%;
    bottom: 5px;

    height: 1px;

    pointer-events: none;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(212,175,55,.75),
            rgba(244,211,94,.95),
            rgba(212,175,55,.75),
            transparent
        );

    opacity: .35;

    box-shadow:
        0 0 8px rgba(212,175,55,.25);

    transition:
        opacity .4s ease,
        box-shadow .4s ease;
}


/* ---------------------------------------------------------
   HOVER — CARD AWAKENS
--------------------------------------------------------- */

.relic-grid > *:hover {

    z-index: 20;

    animation-play-state: paused;

    transform:
        translateY(calc(var(--card-y) - 10px))
        rotate(0deg)
        scale(1.035);

    filter:
        drop-shadow(0 12px 18px rgba(0,0,0,.55))
        drop-shadow(0 0 18px rgba(212,175,55,.22));
}


.relic-grid > *:hover::before {
    opacity: 1;

    transform:
        scale(1.05);
}


.relic-grid > *:hover::after {

    opacity: 1;

    box-shadow:
        0 0 8px rgba(212,175,55,.45),
        0 0 20px rgba(212,175,55,.18);
}


/* ---------------------------------------------------------
   GOLDEN SHIMMER
--------------------------------------------------------- */

.relic-grid > * {
    overflow: hidden;
}

.relic-grid > * .card-shimmer {
    position: absolute;

    top: -20%;
    left: -80%;

    width: 35%;
    height: 140%;

    pointer-events: none;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,225,130,.18),
            rgba(255,240,180,.38),
            transparent
        );

    transform: skewX(-18deg);

    opacity: 0;

    z-index: 30;
}


.relic-grid > *:hover .card-shimmer {
    opacity: 1;

    animation:
        relicShimmer 1.1s ease-out;
}


@keyframes relicShimmer {

    0% {
        left: -80%;
    }

    100% {
        left: 150%;
    }

}


/* ---------------------------------------------------------
   ICON / RELIC INSIDE CARD
--------------------------------------------------------- */

.relic-grid > * img,
.relic-grid > * svg {

    transition:
        transform .45s cubic-bezier(.2,.8,.2,1),
        filter .45s ease;
}


.relic-grid > *:hover img,
.relic-grid > *:hover svg {

    transform:
        translateY(-5px)
        scale(1.04);

    filter:
        drop-shadow(0 0 5px rgba(244,211,94,.55))
        drop-shadow(0 0 15px rgba(212,175,55,.3));
}


/* ---------------------------------------------------------
   EYE / GOLDEN BUTTON
--------------------------------------------------------- */

.relic-grid > * button,
.relic-grid > * .portal,
.relic-grid > * .relic-button {

    transition:
        transform .35s ease,
        box-shadow .35s ease,
        background .35s ease;
}


.relic-grid > *:hover button,
.relic-grid > *:hover .portal,
.relic-grid > *:hover .relic-button {

    transform:
        translateY(-2px);

    box-shadow:
        0 0 8px rgba(212,175,55,.28),
        inset 0 0 10px rgba(244,211,94,.08);
}


/* ---------------------------------------------------------
   ANCIENT CORNER MARKS
--------------------------------------------------------- */

.relic-grid > * {
    --corner-color: rgba(212,175,55,.42);
}


/* top left */
.relic-grid > * {
    background-clip: padding-box;
}


/* ---------------------------------------------------------
   HOVER LIGHT
--------------------------------------------------------- */

.relic-grid > * {
    --mouse-x: 50%;
    --mouse-y: 50%;
}

.relic-grid > * .card-light {

    position: absolute;

    left: var(--mouse-x);
    top: var(--mouse-y);

    width: 140px;
    height: 140px;

    transform:
        translate(-50%, -50%);

    border-radius: 50%;

    pointer-events: none;

    background:
        radial-gradient(
            circle,
            rgba(244,211,94,.12),
            transparent 70%
        );

    opacity: 0;

    transition:
        opacity .25s ease;

    z-index: 2;
}

.relic-grid > *:hover .card-light {
    opacity: 1;
}


/* ---------------------------------------------------------
   MOBILE
--------------------------------------------------------- */

@media (max-width: 900px) {

    .relic-grid > *:nth-child(n) {
        --card-y: 0px;
        --card-rotate: 0deg;
    }

    .relic-grid > *:nth-child(odd),
    .relic-grid > *:nth-child(even) {
        animation:
            relicFloat1 6s ease-in-out infinite;
    }

}


@media (prefers-reduced-motion: reduce) {

    .relic-grid > * {
        animation: none !important;
        transition: none !important;
    }

}
/* =========================================================
   GU LIBRARY — LIVING TEMPLE RELICS
   FINAL CARD REDESIGN
   ---------------------------------------------------------
   Same HTML
   Same SVGs
   Same links
   New visual behavior only
========================================================= */

/* ---------------------------------------------------------
   1. STATIONS — different heights / positions
--------------------------------------------------------- */

.relic-grid .relic-station {
    position: relative;
    perspective: 1200px;
    z-index: 10;
}

/* اختلاف واضح لكن هادي بين البطاقات */
.relic-grid .relic-station:nth-child(1) {
    transform: translateY(-18px);
}

.relic-grid .relic-station:nth-child(2) {
    transform: translateY(8px);
}

.relic-grid .relic-station:nth-child(3) {
    transform: translateY(-8px);
}

.relic-grid .relic-station:nth-child(4) {
    transform: translateY(18px);
}


/* ---------------------------------------------------------
   2. THE ACTUAL TEMPLE TABLET
--------------------------------------------------------- */

.relic-btn {

    position: relative !important;

    width: min(100%, 270px) !important;
    min-height: 350px !important;

    padding: 28px 18px 20px !important;

    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: flex-start !important;

    cursor: pointer;

    color: inherit;

    overflow: hidden;

    transform-style: preserve-3d;

    transform:
        perspective(1100px)
        rotateX(var(--card-rx, 0deg))
        rotateY(var(--card-ry, 0deg))
        translateY(var(--card-lift, 0px))
        scale(var(--card-scale, 1));

    transition:
        transform .18s cubic-bezier(.2,.8,.2,1),
        box-shadow .4s ease,
        border-color .4s ease;

    /*
       Ancient stone plaque
    */
    background:

        /* warm light behind artifact */
        radial-gradient(
            ellipse at 50% 28%,
            rgba(244,211,94,.22),
            transparent 48%
        ),

        /* stone vertical cuts */
        repeating-linear-gradient(
            90deg,
            rgba(255,220,150,.035) 0 2px,
            transparent 2px 15px
        ),

        /* top stone light */
        linear-gradient(
            180deg,
            rgba(255,225,165,.12),
            transparent 20%
        ),

        /* deep sandstone */
        linear-gradient(
            145deg,
            #503b27 0%,
            #3a291b 38%,
            #24170d 72%,
            #120b06 100%
        ) !important;

    /*
       Ancient carved shape
    */
    clip-path: polygon(
        4% 5%,
        10% 2%,
        24% 0%,
        76% 0%,
        90% 2%,
        96% 5%,

        100% 12%,
        98% 30%,
        100% 50%,
        98% 70%,
        100% 88%,

        96% 95%,
        90% 98%,
        76% 100%,
        24% 100%,
        10% 98%,
        4% 95%,

        0% 88%,
        2% 70%,
        0% 50%,
        2% 30%,
        0% 12%
    ) !important;

    border: none !important;

    box-shadow:

        /* outer stone shadow */
        0 24px 45px rgba(0,0,0,.75),

        /* dark outer edge */
        0 0 0 2px #110a05,

        /* gold carved border */
        0 0 0 4px rgba(184,139,48,.45),

        /* internal stone depth */
        inset 0 0 45px rgba(0,0,0,.72),

        inset 0 3px 0 rgba(255,230,170,.10),

        inset 0 -18px 25px rgba(0,0,0,.45);

    will-change: transform;
}


/* ---------------------------------------------------------
   3. INNER CARVED BORDER
--------------------------------------------------------- */

.relic-btn::before {

    content: "";

    position: absolute;

    inset: 13px;

    border: 1px solid rgba(238,201,105,.45);

    box-shadow:

        inset 0 0 0 1px rgba(0,0,0,.45),

        inset 0 0 22px rgba(0,0,0,.4),

        0 0 8px rgba(212,175,55,.08);

    opacity: .85;

    pointer-events: none;

    z-index: 1;
}


/* ---------------------------------------------------------
   4. TOP PHARAONIC FRIEZE
--------------------------------------------------------- */

.relic-btn::after {

    content: "𓂀 𓋹 𓏏 𓆣 𓅓 𓂀";

    position: absolute;

    top: 13px;

    left: 18px;
    right: 18px;

    padding-bottom: 9px;

    text-align: center;

    font-family: serif;

    font-size: 10px;

    letter-spacing: .32em;

    color: rgba(244,211,94,.58);

    border-bottom:
        1px solid rgba(212,175,55,.25);

    text-shadow:
        0 0 6px rgba(244,211,94,.15);

    pointer-events: none;

    z-index: 5;

    transition:
        color .4s ease,
        text-shadow .4s ease,
        letter-spacing .5s ease;
}


/* ---------------------------------------------------------
   5. ICON AREA
--------------------------------------------------------- */

.relic-figure {

    position: relative;

    width: clamp(125px, 12vw, 155px) !important;

    height: auto;

    margin-top: 26px;

    z-index: 4;

    transform:
        translateZ(35px)
        translateY(0);

    transform-origin: center center;

    transition:
        transform .55s cubic-bezier(.16,1,.3,1),
        filter .45s ease;

    filter:
        drop-shadow(0 12px 12px rgba(0,0,0,.75))
        drop-shadow(0 0 10px rgba(212,175,55,.18));
}


/* ---------------------------------------------------------
   6. GOLDEN LIGHT BEHIND ICON
--------------------------------------------------------- */

.relic-glow-ring {

    position: absolute !important;

    top: 31% !important;

    left: 50% !important;

    width: 190% !important;
    height: 190% !important;

    padding: 0 !important;

    transform:
        translate(-50%,-50%)
        scale(.65) !important;

    border-radius: 50%;

    background:

        radial-gradient(
            circle,
            rgba(244,211,94,.26) 0%,
            rgba(212,175,55,.12) 28%,
            rgba(212,175,55,.035) 48%,
            transparent 70%
        ) !important;

    opacity: .5 !important;

    animation:
        relicAura 5s ease-in-out infinite;

    z-index: 2 !important;

    pointer-events: none;
}

@keyframes relicAura {

    0%,100% {
        opacity: .32;
        transform:
            translate(-50%,-50%)
            scale(.62);
    }

    50% {
        opacity: .62;
        transform:
            translate(-50%,-50%)
            scale(.76);
    }
}


/* ---------------------------------------------------------
   7. ARTIFACT FLOAT — ICON ONLY
--------------------------------------------------------- */

.relic-figure {
    animation:
        artifactBreathing 4.8s ease-in-out infinite;
}

@keyframes artifactBreathing {

    0%,100% {
        transform:
            translateZ(35px)
            translateY(0);
    }

    50% {
        transform:
            translateZ(35px)
            translateY(-7px);
    }
}


/* Different rhythm for each artifact */

.relic-station:nth-child(1) .relic-figure {
    animation-delay: -.8s;
}

.relic-station:nth-child(2) .relic-figure {
    animation-delay: -2.1s;
}

.relic-station:nth-child(3) .relic-figure {
    animation-delay: -3.4s;
}

.relic-station:nth-child(4) .relic-figure {
    animation-delay: -1.5s;
}


/* ---------------------------------------------------------
   8. HOVER — CARD COMES ALIVE
--------------------------------------------------------- */

.relic-btn:hover,
.relic-btn:focus-visible {

    --card-lift: -12px;
    --card-scale: 1.025;

    box-shadow:

        0 35px 55px rgba(0,0,0,.8),

        0 0 0 2px #120b06,

        0 0 0 4px rgba(244,211,94,.85),

        inset 0 0 40px rgba(0,0,0,.55),

        inset 0 3px 0 rgba(255,240,190,.15),

        0 0 45px rgba(244,211,94,.20);
}


/* Icon rises */

.relic-btn:hover .relic-figure,
.relic-btn:focus-visible .relic-figure {

    transform:
        translateZ(70px)
        translateY(-15px)
        scale(1.08);

    filter:

        drop-shadow(0 18px 15px rgba(0,0,0,.8))

        drop-shadow(
            0 0 18px
            rgba(244,211,94,.55)
        );
}


/* Frieze wakes up */

.relic-btn:hover::after,
.relic-btn:focus-visible::after {

    color: #f4d35e;

    letter-spacing: .42em;

    text-shadow:
        0 0 8px rgba(244,211,94,.55),
        0 0 20px rgba(212,175,55,.25);
}


/* ---------------------------------------------------------
   9. MOVING LIGHT ACROSS THE STONE
--------------------------------------------------------- */

.relic-btn {

    background-size:
        100% 100%,
        100% 100%,
        100% 100%,
        100% 100%,
        100% 100%,
        100% 100%,
        100% 100%,
        100% 100%;
}


/* separate light sweep using the existing inner layer */

.relic-btn .relic-glow-ring::after {

    content: "";

    position: absolute;

    top: -20%;
    bottom: -20%;

    left: -80%;

    width: 35%;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,235,175,.28),
            transparent
        );

    transform: skewX(-18deg);

    opacity: 0;

    pointer-events: none;
}

.relic-btn:hover .relic-glow-ring::after {

    opacity: 1;

    animation:
        stoneLightSweep 1.5s ease-out forwards;
}

@keyframes stoneLightSweep {

    from {
        left: -70%;
    }

    to {
        left: 140%;
    }
}


/* ---------------------------------------------------------
   10. PEDESTAL
--------------------------------------------------------- */

.relic-pedestal {

    width: 68% !important;

    height: 17px !important;

    margin-top: 4px !important;

    position: relative;

    z-index: 6;

    background:

        linear-gradient(
            90deg,
            #2a1a0c,
            #d1a955 20%,
            #f0cd78 50%,
            #d1a955 80%,
            #2a1a0c
        ) !important;

    border-radius: 3px;

    box-shadow:

        0 9px 18px rgba(0,0,0,.75),

        inset 0 2px 3px rgba(255,240,180,.45),

        0 0 10px rgba(212,175,55,.15);

    transition:
        transform .45s ease,
        box-shadow .45s ease;
}

.relic-btn:hover .relic-pedestal {

    transform:
        translateZ(50px)
        scaleX(1.08);

    box-shadow:

        0 12px 22px rgba(0,0,0,.8),

        0 0 18px rgba(244,211,94,.4),

        inset 0 2px 3px rgba(255,240,180,.6);
}


/* ---------------------------------------------------------
   11. LABEL — CARVED BRASS PLAQUE
--------------------------------------------------------- */

.relic-label {

    position: relative;

    z-index: 8;

    margin-top: 13px !important;

    min-width: 125px;

    padding: 8px 16px !important;

    font-family: 'Cinzel', serif;

    font-size: .72rem !important;

    font-weight: 700;

    letter-spacing: .15em;

    text-transform: uppercase;

    color: #d8b86a !important;

    background:

        linear-gradient(
            180deg,
            rgba(75,53,30,.95),
            rgba(25,16,9,.98)
        ) !important;

    border:
        1px solid rgba(212,175,55,.55) !important;

    border-radius: 4px !important;

    box-shadow:

        inset 0 0 10px rgba(0,0,0,.7),

        0 5px 12px rgba(0,0,0,.6);

    transition:
        color .35s ease,
        background .35s ease,
        box-shadow .35s ease,
        transform .35s ease;
}

.relic-btn:hover .relic-label,
.relic-btn:focus-visible .relic-label {

    color: #201408 !important;

    background:
        linear-gradient(
            180deg,
            #f5d979,
            #b88624
        ) !important;

    box-shadow:

        0 0 15px rgba(244,211,94,.45),

        inset 0 1px 2px rgba(255,250,210,.65);

    transform:
        translateZ(60px)
        translateY(-3px);
}


/* ---------------------------------------------------------
   12. SERVICE-SPECIFIC IDENTITY
--------------------------------------------------------- */

/* PROFILE */

.relic-btn[data-relic="profile"] {

    --service-glow: rgba(244,211,94,.55);
}


/* VIRTUAL TOUR */

.relic-btn[data-relic="tour"] {

    --service-glow: rgba(46,139,125,.55);
}

.relic-btn[data-relic="tour"]:hover {

    box-shadow:
        0 35px 55px rgba(0,0,0,.8),
        0 0 0 4px rgba(46,139,125,.75),
        0 0 45px rgba(46,139,125,.25);
}


/* BORROW */

.relic-btn[data-relic="borrow"] {

    --service-glow: rgba(255,145,65,.55);
}

.relic-btn[data-relic="borrow"]:hover {

    box-shadow:
        0 35px 55px rgba(0,0,0,.8),
        0 0 0 4px rgba(255,145,65,.75),
        0 0 45px rgba(255,145,65,.22);
}


/* MAP */

.relic-btn[data-relic="map"] {

    --service-glow: rgba(90,140,200,.55);
}

.relic-btn[data-relic="map"]:hover {

    box-shadow:
        0 35px 55px rgba(0,0,0,.8),
        0 0 0 4px rgba(90,140,200,.75),
        0 0 45px rgba(90,140,200,.22);
}


/* ---------------------------------------------------------
   13. MOUSE ACTIVE STATE
--------------------------------------------------------- */

.relic-btn.is-mouse-active {

    --card-scale: 1.025;
}


/* ---------------------------------------------------------
   14. CLICK — ACTIVATION
--------------------------------------------------------- */

.relic-btn.is-activated {

    animation:
        relicActivation .65s cubic-bezier(.2,.8,.2,1) !important;
}

@keyframes relicActivation {

    0% {
        transform:
            perspective(1100px)
            scale(1);
    }

    35% {
        transform:
            perspective(1100px)
            scale(1.06);
    }

    70% {
        transform:
            perspective(1100px)
            scale(.985);
    }

    100% {
        transform:
            perspective(1100px)
            scale(1);
    }
}


/* ---------------------------------------------------------
   15. REMOVE OLD DEAD FLOAT
--------------------------------------------------------- */

.relic-station .relic-btn {

    animation: none !important;
}


/* ---------------------------------------------------------
   16. MOBILE
--------------------------------------------------------- */

@media (max-width: 720px) {

    .relic-grid .relic-station:nth-child(1),
    .relic-grid .relic-station:nth-child(2),
    .relic-grid .relic-station:nth-child(3),
    .relic-grid .relic-station:nth-child(4) {

        transform: none;
    }

    .relic-btn {

        width: min(100%, 310px) !important;

        min-height: 330px !important;
    }

    .relic-figure {

        width: 135px !important;
    }

}


/* ---------------------------------------------------------
   17. ACCESSIBILITY
--------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {

    .relic-btn,
    .relic-figure,
    .relic-glow-ring,
    .relic-label {

        animation: none !important;

        transition: none !important;
    }
}
