/* =========================================================
   GU LIBRARY — KNOWLEDGE GUARDIAN
   Interactive Egyptian Character
========================================================= */

.knowledge-guardian {
    position: relative;
    width: min(330px, 25vw);
    min-width: 230px;
    height: 560px;

    display: flex;
    justify-content: center;
    align-items: flex-end;

    isolation: isolate;

    perspective: 900px;

    user-select: none;
    pointer-events: auto;

    margin: 0 auto;

    z-index: 20;
}


/* =========================================================
   AURA
========================================================= */

.guardian-aura {
    position: absolute;

    width: 280px;
    height: 280px;

    left: 50%;
    top: 32%;

    transform: translate(-50%, -50%);

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            rgba(212,175,55,.13),
            rgba(212,175,55,.05) 35%,
            transparent 72%
        );

    filter: blur(10px);

    opacity: .55;

    animation:
        guardianAura 6s ease-in-out infinite;

    pointer-events: none;

    z-index: -2;
}


@keyframes guardianAura {

    0%,100% {
        transform:
            translate(-50%, -50%)
            scale(.94);

        opacity: .38;
    }

    50% {
        transform:
            translate(-50%, -50%)
            scale(1.08);

        opacity: .68;
    }

}


/* =========================================================
   GROUND
========================================================= */

.guardian-ground {

    position: absolute;

    bottom: 18px;

    left: 50%;

    width: 190px;
    height: 28px;

    transform:
        translateX(-50%);

    border-radius: 50%;

    background:
        radial-gradient(
            ellipse,
            rgba(0,0,0,.8),
            transparent 70%
        );

    filter: blur(4px);

    z-index: -1;
}


/* =========================================================
   SVG
========================================================= */

.guardian-svg {

    width: 100%;
    height: 100%;

    overflow: visible;

    transform-origin:
        50% 90%;

    animation:
        guardianBreathing 5.5s ease-in-out infinite;

    filter:
        drop-shadow(
            0 18px 20px rgba(0,0,0,.65)
        );

    transition:
        filter .5s ease,
        transform .4s ease;

    cursor: default;
}


@keyframes guardianBreathing {

    0%,100% {
        transform:
            translateY(0)
            scale(1);
    }

    50% {
        transform:
            translateY(-3px)
            scale(1.006);
    }

}


/* =========================================================
   CLOAK
========================================================= */

.guardian-cloak {

    transform-origin:
        150px 230px;

    animation:
        cloakBreath 6s ease-in-out infinite;
}


@keyframes cloakBreath {

    0%,100% {
        transform:
            scaleX(1);
    }

    50% {
        transform:
            scaleX(1.012);
    }

}


/* =========================================================
   HEAD
========================================================= */

.guardian-head {

    transform-origin:
        150px 150px;

    animation:
        guardianHeadIdle 7s ease-in-out infinite;

    transition:
        transform .25s ease-out;
}


@keyframes guardianHeadIdle {

    0%,100% {
        transform:
            rotate(0deg);
    }

    50% {
        transform:
            rotate(-.7deg);
    }

}


/* =========================================================
   EYES
========================================================= */

.guardian-eyes {

    transform-origin:
        150px 105px;

    transition:
        transform .15s ease-out;
}


/* Eye glow */

.guardian-eye-left,
.guardian-eye-right {

    filter:
        drop-shadow(
            0 0 5px rgba(244,211,94,.7)
        );

    animation:
        guardianEyeGlow 4s ease-in-out infinite;

}


@keyframes guardianEyeGlow {

    0%,100% {
        opacity: .65;
    }

    50% {
        opacity: 1;
    }

}


/* =========================================================
   URAEUS
========================================================= */

.guardian-uraeus {

    transform-origin:
        150px 75px;

    animation:
        uraeusMotion 5s ease-in-out infinite;
}


@keyframes uraeusMotion {

    0%,100% {
        transform:
            rotate(0deg);
    }

    50% {
        transform:
            rotate(2deg);
    }

}


/* =========================================================
   ARMS
========================================================= */

.guardian-arm-left {

    transform-origin:
        92px 220px;

    animation:
        leftArmIdle 6s ease-in-out infinite;
}


.guardian-arm-right {

    transform-origin:
        208px 220px;

    animation:
        rightArmIdle 6s ease-in-out infinite;
}


@keyframes leftArmIdle {

    0%,100% {
        transform:
            rotate(0deg);
    }

    50% {
        transform:
            rotate(-1deg);
    }

}


@keyframes rightArmIdle {

    0%,100% {
        transform:
            rotate(0deg);
    }

    50% {
        transform:
            rotate(1deg);
    }

}


/* =========================================================
   STAFF
========================================================= */

.guardian-staff {

    transform-origin:
        250px 455px;

    animation:
        staffIdle 5s ease-in-out infinite;
}


@keyframes staffIdle {

    0%,100% {
        transform:
            rotate(0deg);
    }

    50% {
        transform:
            rotate(.8deg);
    }

}


.staff-energy {

    animation:
        staffEnergy 3s ease-in-out infinite;
}


@keyframes staffEnergy {

    0%,100% {
        opacity: .08;
    }

    50% {
        opacity: .4;
    }

}


/* =========================================================
   CHEST SYMBOL
========================================================= */

.guardian-symbol {

    transform-origin:
        150px 270px;

    animation:
        symbolPulse 4s ease-in-out infinite;
}


@keyframes symbolPulse {

    0%,100% {
        opacity: .65;
    }

    50% {
        opacity: 1;
        filter:
            drop-shadow(
                0 0 8px rgba(244,211,94,.45)
            );
    }

}


/* =========================================================
   HIEROGLYPHS
========================================================= */

.guardian-hieroglyphs {

    font-family:
        "Times New Roman",
        serif;

    font-size: 23px;

    fill: #d4af37;

    opacity: .32;

    animation:
        hieroglyphFloat 6s ease-in-out infinite;
}


@keyframes hieroglyphFloat {

    0%,100% {
        transform:
            translateY(0);
        opacity: .22;
    }

    50% {
        transform:
            translateY(-7px);
        opacity: .48;
    }

}


/* =========================================================
   HOVER — GUARDIAN AWAKENS
========================================================= */

.knowledge-guardian:hover .guardian-svg {

    transform:
        translateY(-7px)
        scale(1.015);

    filter:
        drop-shadow(
            0 18px 20px rgba(0,0,0,.7)
        )
        drop-shadow(
            0 0 25px rgba(212,175,55,.22)
        );
}


.knowledge-guardian:hover .guardian-aura {

    opacity: .9;

    animation:
        guardianAuraAwake 2.5s ease-in-out infinite;
}


@keyframes guardianAuraAwake {

    0%,100% {
        transform:
            translate(-50%,-50%)
            scale(.95);
    }

    50% {
        transform:
            translate(-50%,-50%)
            scale(1.18);
    }

}


.knowledge-guardian:hover
.guardian-eye-left,
.knowledge-guardian:hover
.guardian-eye-right {

    filter:
        drop-shadow(
            0 0 8px #f4d35e
        )
        drop-shadow(
            0 0 18px rgba(244,211,94,.55)
        );

    opacity: 1;
}


/* =========================================================
   INSCRIPTION
========================================================= */

.guardian-inscription {

    position: absolute;

    bottom: -5px;

    left: 50%;

    transform:
        translateX(-50%);

    width: 260px;

    display: flex;

    justify-content: center;
