/* =========================================================
   3 MINI EGYPTIAN SHELF GUARDIANS
========================================================= */

#bookGrid {
    position: relative !important;
    overflow: visible !important;
}

.mini-shelf-guardian {

    position: absolute;

    width: 58px;
    height: 92px;

    z-index: 100;

    pointer-events: none;

    transition:
        left .18s ease-out,
        transform .18s ease-out;

    filter:
        drop-shadow(0 6px 5px rgba(0,0,0,.8))
        drop-shadow(0 0 8px rgba(212,175,55,.25));

}

.guardian-body {

    position: relative;

    width: 100%;
    height: 100%;

}


/* HEAD */

.guardian-head {

    position: absolute;

    left: 50%;
    top: 5px;

    transform: translateX(-50%);

    width: 28px;
    height: 28px;

    border-radius: 50%;

    display: flex;

    align-items: center;
    justify-content: center;

    font-size: 18px;

    color: #f4d35e;

    background:
        radial-gradient(
            circle,
            #9b703d 0%,
            #5a3b20 70%
        );

    border:
        2px solid #d4af37;

    z-index: 5;

}


/* CROWN */

.guardian-crown {

    position: absolute;

    left: 50%;
    top: 0;

    transform: translateX(-50%);

    width: 38px;
    height: 16px;

    background:
        linear-gradient(
            90deg,
            #8b6825,
            #f4d35e,
            #8b6825
        );

    clip-path:
        polygon(
            0 100%,
            8% 15%,
            28% 55%,
            50% 0,
            72% 55%,
            92% 15%,
            100% 100%
        );

    z-index: 6;

}


/* BODY */

.guardian-torso {

    position: absolute;

    left: 50%;
    top: 31px;

    transform: translateX(-50%);

    width: 31px;
    height: 42px;

    background:
        linear-gradient(
            90deg,
            #3a2817,
            #8b683d,
            #3a2817
        );

    border:
        2px solid #d4af37;

    clip-path:
        polygon(
            20% 0,
            80% 0,
            100% 100%,
            0 100%
        );

}


/* ARMS */

.guardian-arm {

    position: absolute;

    top: 35px;

    width: 8px;
    height: 34px;

    background: #8b6335;

    border: 1px solid #d4af37;

}

.guardian-arm.left {
    left: 7px;
    transform: rotate(12deg);
}

.guardian-arm.right {
    right: 7px;
    transform: rotate(-12deg);
}


/* LEGS */

.guardian-leg {

    position: absolute;

    top: 68px;

    width: 9px;
    height: 22px;

    background: #4a321c;

    border:
        1px solid #d4af37;

}

.guardian-leg.left {
    left: 19px;
}

.guardian-leg.right {
    right: 19px;
}


/* STAFF */

.guardian-staff {

    position: absolute;

    width: 3px;
    height: 62px;

    right: 2px;
    top: 29px;

    background:
        linear-gradient(
            #f4d35e,
            #8b6825
        );

}


/* =========================================================
   DIFFERENT GUARDIANS
========================================================= */


/* Guardian 1 */

.guardian-1 .guardian-head {

    background:
        radial-gradient(
            circle,
            #a87842,
            #5c3b1e
        );

}


/* Guardian 2 */

.guardian-2 .guardian-crown {

    width: 45px;
    height: 20px;

    background:
        linear-gradient(
            90deg,
            #183b3a,
            #d4af37,
            #183b3a
        );

}


.guardian-2 .guardian-torso {

    background:
        linear-gradient(
            90deg,
            #173b39,
            #8c7135,
            #173b39
        );

}


/* Guardian 3 */

.guardian-3 .guardian-crown {

    width: 34px;
    height: 22px;

    background:
        linear-gradient(
            #4b251d,
            #d4af37
        );

}


.guardian-3 .guardian-torso {

    background:
        linear-gradient(
            90deg,
            #301b15,
            #9b703d,
            #301b15
        );

}


/* HOVER / FOLLOW */

.mini-shelf-guardian.guardian-following {

    filter:
        drop-shadow(0 6px 5px rgba(0,0,0,.8))
        drop-shadow(
            0 0 16px
            rgba(244,211,94,.55)
        );

}


/* walking animation */

.mini-shelf-guardian:not(.guardian-following)
.guardian-leg.left {

    animation:
        guardianWalkLeft .45s
        ease-in-out infinite alternate;

}

.mini-shelf-guardian:not(.guardian-following)
.guardian-leg.right {

    animation:
        guardianWalkRight .45s
        ease-in-out infinite alternate;

}


@keyframes guardianWalkLeft {

    from {
        transform: rotate(8deg);
    }

    to {
        transform: rotate(-8deg);
    }

}


@keyframes guardianWalkRight {

    from {
        transform: rotate(-8deg);
    }

    to {
        transform: rotate(8deg);
    }

}


/* breathing */

.mini-shelf-guardian {
    animation:
        guardianFloat 2.2s
        ease-in-out infinite;
    transition:
        left .45s cubic-bezier(.22,.61,.36,1),
        transform .35s ease;
}

@keyframes guardianFloat {

    0%,100% {
        margin-top: 0;
    }

    50% {
        margin-top: -3px;
    }

}
