/* ---------- GAME CARDS ---------- */

.games-chamber .game-card,
.games-chamber .portal-card,
.games-chamber .game-portal {
  position: relative;
  transform: translateY(0);
  transition:
    transform 0.55s cubic-bezier(.2,.8,.2,1),
    filter 0.55s ease,
    border-color 0.45s ease,
    box-shadow 0.55s ease;

  /* subtle idle movement */
  animation: gameCardFloat 5s ease-in-out infinite;

  will-change: transform, filter;
}

/* Don't let the 3 cards move together */
.games-chamber .game-card:nth-child(2),
.games-chamber .portal-card:nth-child(2),
.games-chamber .game-portal:nth-child(2) {
  animation-delay: -1.6s;
}

.games-chamber .game-card:nth-child(3),
.games-chamber .portal-card:nth-child(3),
.games-chamber .game-portal:nth-child(3) {
  animation-delay: -3.2s;
}


/* ---------- CARD HOVER ---------- */

.games-chamber .game-card:hover,
.games-chamber .portal-card:hover,
.games-chamber .game-portal:hover {
  transform: translateY(-12px) scale(1.025);

  filter:
    brightness(1.12)
    saturate(1.12);

  box-shadow:
    0 18px 45px rgba(0,0,0,.55),
    0 0 18px rgba(77, 225, 211, .18),
    inset 0 0 22px rgba(214, 179, 106, .06);

