/* =========================================================
   GAMES CHAMBER — BIG CARD MOTION
   ========================================================= */

.games-chamber .game-card {
    position: relative;
    overflow: hidden;
    transform-style: preserve-3d;

    transition:
        transform .7s cubic-bezier(.16,1,.3,1),
        box-shadow .7s ease,
        border-color .5s ease;

    animation: bigCardFloat 4s ease-in-out infinite;
}


/* كل بطاقة لها حركة مختلفة */
.games-chamber .game-card:nth-child(1) {
    animation-delay: 0s;
}

.games-chamber .game-card:nth-child(2) {
    animation-delay: -1.3s;
}

.games-chamber .game-card:nth-child(3) {
    animation-delay: -2.6s;
}


/* =========================================================
   BIG IDLE FLOAT
   ========================================================= */

@keyframes bigCardFloat {

    0%,
    100% {
        transform:
            translateY(0)
            rotateZ(0deg);
    }

    25% {
        transform:
            translateY(-8px)
            rotateZ(-.8deg);
    }

    50% {
        transform:
            translateY(-14px)
            rotateZ(.8deg);
    }

    75% {
        transform:
            translateY(-6px)
            rotateZ(-.4deg);
    }
}


/* =========================================================
   BIG HOVER
   ========================================================= */

.games-chamber .game-card:hover {

    animation-play-state: paused;

    transform:
        translateY(-28px)
        scale(1.08)
        rotateX(6deg)
        rotateY(-5deg)
        rotateZ(-1deg);

    z-index: 50;

    border-color:
        rgba(214,179,106,.95) !important;

    box-shadow:

        0 35px 70px rgba(0,0,0,.75),

        0 0 25px rgba(214,179,106,.22),

        0 0 55px rgba(99,210,200,.12),

        inset 0 0 30px rgba(214,179,106,.08);
}


/* =========================================================
   MOVING LIGHT
   ========================================================= */

.games-chamber .game-card::before {

    content: "";

    position: absolute;

    width: 35%;
    height: 180%;

    top: -40%;
    left: -80%;

    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(255,255,255,.05),
            rgba(214,179,106,.45),
            rgba(255,255,255,.12),
            transparent
        );

    transform: rotate(22deg);

    opacity: 0;

    pointer-events: none;

    transition:
        left 1s cubic-bezier(.2,.8,.2,1),
        opacity .3s ease;

    z-index: 20;
}


.games-chamber .game-card:hover::before {

    left: 140%;

    opacity: 1;
}


/* =========================================================
   ICON — BIG LIFT
   ========================================================= */

.games-chamber .game-card .game-icon,
.games-chamber .game-card .icon,
.games-chamber .game-card svg {

    transition:
        transform .7s cubic-bezier(.16,1,.3,1),
        filter .7s ease;
}


.games-chamber .game-card:hover .game-icon,
.games-chamber .game-card:hover .icon,
.games-chamber .game-card:hover svg {

    transform:
        translateY(-18px)
        scale(1.16)
        rotate(-5deg);

    filter:
        drop-shadow(0 8px 10px rgba(0,0,0,.7))
        drop-shadow(0 0 12px rgba(214,179,106,.28));
}


/* =========================================================
   TITLE — COMES FORWARD
   ========================================================= */

.games-chamber .game-card h3,
.games-chamber .game-card .game-title {

    transition:
        transform .6s cubic-bezier(.16,1,.3,1),
        letter-spacing .5s ease;
}


.games-chamber .game-card:hover h3,
.games-chamber .game-card:hover .game-title {

    transform:
        translateY(-8px)
        translateZ(20px);

    letter-spacing:
        .14em;
}


/* =========================================================
   INNER LIGHT
   ========================================================= */

.games-chamber .game-card::after {

    content: "";

    position: absolute;

    inset: 3px;

    border:
        1px solid rgba(214,179,106,.18);

    border-radius:
        inherit;

    box-shadow:
        inset 0 0 0 rgba(214,179,106,0);

    pointer-events: none;

    transition:
        border-color .6s ease,
        box-shadow .6s ease;
}


.games-chamber .game-card:hover::after {

    border-color:
        rgba(214,179,106,.7);

    box-shadow:
        inset 0 0 25px rgba(214,179,106,.08),
        0 0 20px rgba(214,179,106,.12);
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width:700px) {

    .games-chamber .game-card:hover {

        transform:
            translateY(-15px)
            scale(1.035)
            rotateZ(-1deg);
    }

}
