    top: 0;

    width: 4px;
    height: 70px;

    transform: translateX(-50%);

    background:
        repeating-linear-gradient(
            to bottom,
            #6d4c17 0px,
            #d4af37 4px,
            #f0d36a 7px,
            #755218 10px
        );

    border-radius: 4px;

    box-shadow:
        0 0 6px rgba(212,175,55,.7),
        0 0 15px rgba(212,175,55,.3);
}

/* جسم الثعبان */
.serpent-body {
    position: absolute;

    left: 50%;
    top: 62px;

    width: 25px;
    height: 75px;

    transform: translateX(-50%);

    display: flex;
    flex-direction: column;
    align-items: center;

    animation: serpentIdle 2.5s ease-in-out infinite;
}

.serpent-body span {
    width: 20px;
    height: 13px;

    margin: -1px 0;

    background:
        linear-gradient(
            90deg,
            #705018,
            #f0d36b,
            #9a721f
        );

    border: 1px solid #f7dc75;

    clip-path: polygon(
        50% 0,
        100% 50%,
        50% 100%,
        0 50%
    );

    box-shadow:
        0 0 5px rgba(212,175,55,.4);
}

/* رأس الثعبان */
.serpent-head {
    position: absolute;

    left: 50%;
    top: 125px;

    width: 52px;
    height: 45px;

    transform: translateX(-50%);

    background:
        linear-gradient(
            135deg,
            #ffe99a 0%,
            #d4af37 45%,
            #795517 100%
        );

    clip-path: polygon(
        50% 0,
        88% 20%,
        100% 55%,
        76% 100%,
        50% 78%,
        24% 100%,
        0 55%,
        12% 20%
    );

    filter:
        drop-shadow(0 0 8px rgba(212,175,55,.9))
        drop-shadow(0 0 20px rgba(212,175,55,.4));
}

/* العين */
.serpent-eye {
    position: absolute;

    top: 15px;

    width: 7px;
    height: 7px;

    border-radius: 50%;

    background: #080502;

    box-shadow:
        0 0 4px #fff0a0,
        0 0 8px rgba(255,210,70,.8);
}

.serpent-eye.left {
    left: 12px;
}

.serpent-eye.right {
    right: 12px;
}

/* اللسان */
.serpent-tongue {
    position: absolute;

    left: 50%;
    bottom: -11px;

    width: 18px;
    height: 12px;

    transform: translateX(-50%);

    border-bottom: 2px solid #9d261b;
}

.serpent-tongue::before,
.serpent-tongue::after {
    content: "";

    position: absolute;

    bottom: -4px;

    width: 8px;
    height: 7px;

    border-bottom: 2px solid #9d261b;
}

.serpent-tongue::before {
    left: 0;
    transform: rotate(-25deg);
}

.serpent-tongue::after {
    right: 0;
    transform: rotate(25deg);
}

/* حركة هادئة */
@keyframes serpentIdle {

    0%, 100% {
        transform:
            translateX(-50%)
            rotate(-3deg);
    }

    50% {
        transform:
            translateX(-50%)
            rotate(3deg);
    }
}

/* حركة عند اللعب */
.games-chamber.serpent-alert .hanging-serpent {
    animation: serpentReact .55s ease-in-out infinite alternate;
}

@keyframes serpentReact {

    from {
        transform:
            translateX(-50%)
            rotate(-10deg);
    }

    to {
        transform:
            translateX(-50%)
            translateX(16px)
            rotate(10deg);
    }
}
