/* ============================================================
   GU LIBRARY — STUDENT HALL V2
   ROYAL EGYPTIAN CEREMONY
   ============================================================ */

.student-hall {
  position: relative !important;
  isolation: isolate !important;
  overflow: hidden !important;

  background:
    radial-gradient(
      ellipse at 50% 36%,
      rgba(214,177,69,.16) 0%,
      rgba(120,83,25,.08) 24%,
      transparent 52%
    ),
    linear-gradient(
      180deg,
      #0c0805 0%,
      #191109 45%,
      #0b0704 100%
    ) !important;
}


/* ============================================================
   STONE WALL
   ============================================================ */

.student-hall::before {
  content: "";

  position: absolute;
  inset: 0;

  z-index: -10;
  pointer-events: none;

  opacity: .75;

  background:
    repeating-linear-gradient(
      0deg,
      transparent 0 72px,
      rgba(218,181,93,.035) 73px,
      transparent 75px
    ),
    repeating-linear-gradient(
      90deg,
      transparent 0 118px,
      rgba(218,181,93,.025) 119px,
      transparent 121px
    ),
    radial-gradient(
      circle at 20% 25%,
      rgba(255,220,130,.04),
      transparent 24%
    ),
    radial-gradient(
      circle at 80% 35%,
      rgba(255,220,130,.035),
      transparent 25%
    );
}


/* ============================================================
   INNER TEMPLE FRAME
   ============================================================ */

.student-hall::after {
  content: "";

  position: absolute;

  top: 26px;
  bottom: 26px;
  left: 24px;
  right: 24px;

  z-index: -9;

  border:
    1px solid rgba(211,172,65,.18);

  box-shadow:
    inset 0 0 80px rgba(0,0,0,.75),
    inset 0 0 25px rgba(213,176,69,.045);

  pointer-events: none;
}


