   TEMPLE GATE BEHIND STUDENTS
   ============================================================ */

.student-hall .student-podium::before {
  content: "";

  position: absolute;

  left: 50%;
  top: 40%;

  width: min(600px, 72vw);
  height: min(650px, 70vw);

  transform: translate(-50%, -50%);

  border:
    7px solid rgba(118,82,28,.72);

  border-bottom: 0;

  border-radius:
    300px 300px 0 0;

  background:
    radial-gradient(
      ellipse at center 30%,
      rgba(226,191,87,.18),
      rgba(68,44,14,.10) 45%,
      rgba(0,0,0,.38) 75%,
      transparent 76%
    );

  box-shadow:
    0 0 0 12px rgba(31,20,8,.9),
    0 0 0 14px rgba(202,160,48,.12),
    inset 0 0 55px rgba(216,175,64,.08),
    0 0 80px rgba(213,174,65,.07);

  pointer-events: none;

  z-index: -4;
}


