  transform:
    translateY(-22px)
    scale(1.055)
    rotateX(3deg) !important;

  box-shadow:
    0 40px 75px rgba(0,0,0,.82),
    0 0 45px rgba(231,194,76,.30),
    0 0 100px rgba(231,194,76,.12);
}


/* ============================================================
   IMAGE
   ============================================================ */

.student-hall .student-card .student-frame {
  transition:
    transform .55s cubic-bezier(.2,.8,.2,1),
    box-shadow .45s ease;
}


.student-hall .student-card:hover .student-frame {

  transform:
    translateZ(18px)
    scale(1.025);

  box-shadow:
    0 0 0 4px rgba(28,19,9,.95),
    0 0 0 6px rgba(215,174,64,.30),
    0 0 35px rgba(215,174,64,.22),
    0 18px 35px rgba(0,0,0,.65);
}


/* ============================================================
   IMAGE ZOOM
   ============================================================ */

.student-hall .student-card .student-frame img {

  transition:
    transform .65s cubic-bezier(.2,.8,.2,1),
    filter .5s ease;
}


.student-hall .student-card:hover
.student-frame img {

  transform:
    scale(1.07);

  filter:
    brightness(1.08)
    contrast(1.06)
    saturate(1.08);
}


/* ============================================================
   GOLDEN LIGHT
   ============================================================ */

.student-hall .student-card .student-frame {

  overflow: hidden;
}


.student-hall .student-card .student-frame::after {

  content: "";

  position: absolute;

  top: -100%;
  left: -70%;

  width: 35%;
  height: 300%;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255,224,139,.20),
      transparent
    );

  transform: rotate(25deg);

  opacity: 0;

  pointer-events: none;

  z-index: 20;
}


.student-hall .student-card:hover
.student-frame::after {

  left: 145%;

  opacity: 1;

  transition:
    left .85s ease,
    opacity .15s ease;
}


/* ============================================================
   NAME
   ============================================================ */

.student-hall .student-card h2,
.student-hall .student-card h3 {

  transition:
    transform .4s ease,
    text-shadow .4s ease;
}


.student-hall .student-card:hover h2,
.student-hall .student-card:hover h3 {

  transform:
    translateY(-4px);

  text-shadow:
    0 0 14px rgba(231,194,76,.35),
    0 3px 6px rgba(0,0,0,.85);
}


/* ============================================================
   PLACE
   ============================================================ */

.student-hall .student-card p {

  transition:
    letter-spacing .4s ease,
    opacity .4s ease,
    transform .4s ease;
}


.student-hall .student-card:hover p {

  letter-spacing:
    3px;

  transform:
    translateY(-2px);

  text-shadow:
    0 0 10px rgba(226,188,72,.3);
}


/* ============================================================
   CROWN
   ============================================================ */

.student-hall .student-card.first .student-crown {

  transition:
    transform .45s cubic-bezier(.2,.8,.2,1),
    filter .4s ease;
}


.student-hall .student-card.first:hover .student-crown {

  transform:
    translateX(-50%)
    translateY(-12px)
    scale(1.16)
    rotate(-4deg) !important;

  filter:
    drop-shadow(0 5px 5px rgba(0,0,0,.8))
    drop-shadow(0 0 20px rgba(239,204,92,.75));
}


/* ============================================================
   IDLE FLOAT
   ============================================================ */

@keyframes studentIdleFloat {

  0%,
  100% {
    transform:
      translateY(0);
  }

  50% {
    transform:
      translateY(-5px);
  }

}


/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 700px) {

  .student-hall .student-card:hover {

    transform:
      translateY(-10px)
      scale(1.02) !important;
  }

}
/* ============================================================
   STUDENT HALL — CLEAR PORTRAITS
   KEEP GOLD FRAME / REMOVE GOLD WASH FROM FACES
   ============================================================ */


/* ============================================================
   IMAGE — MAKE FACES CLEAR
   ============================================================ */

.student-hall .student-card .student-frame img {
  position: relative !important;

  z-index: 2 !important;

  opacity: 1 !important;

  /*
    نرجع التفاصيل والـcontrast
  */
  filter:
    brightness(.86)
    contrast(1.18)
    saturate(.94) !important;

  transition:
    transform .65s cubic-bezier(.2,.8,.2,1),
    filter .45s ease !important;
}


/* ============================================================
   HOVER — CLEAR + SLIGHTLY BRIGHTER
   ============================================================ */

.student-hall .student-card:hover
.student-frame img {

  filter:
    brightness(.94)
    contrast(1.15)
    saturate(1.02) !important;

  transform:
    scale(1.045) !important;
}


/* ============================================================
   GOLD LIGHT SWEEP
   خلي الشعاع فوق الإطار لكن خفيف جدًا على الصورة
   ============================================================ */

.student-hall .student-card .student-frame::after {

  opacity: 0 !important;

  background:
    linear-gradient(
      90deg,
      transparent 0%,
      rgba(255,224,139,.08) 48%,
      transparent 100%
    ) !important;
}


.student-hall .student-card:hover
.student-frame::after {

  opacity: .65 !important;

  left: 145% !important;

  transition:
    left .85s ease,
    opacity .2s ease !important;
}


/* ============================================================
   IMAGE PROTECTION LAYER
   يمنع أي تأثير ذهبي خارجي من غسل الصورة
   ============================================================ */

.student-hall .student-frame {
  isolation: isolate !important;
}


/* ============================================================
   PREVENT BLENDING WITH GOLD DECORATIONS
   ============================================================ */

.student-hall .student-frame img {
  mix-blend-mode: normal !important;
}


/* ============================================================
   FACE AREA — NATURAL COLORS
   ============================================================ */

.student-hall .student-card.first
.student-frame img {

  filter:
    brightness(.84)
    contrast(1.20)
    saturate(.95) !important;
}


.student-hall .student-card.first:hover
.student-frame img {

  filter:
    brightness(.93)
    contrast(1.16)
    saturate(1.02) !important;
}


/* ============================================================
   IMAGE FRAME — GOLD STAYS OUTSIDE
   ============================================================ */

.student-hall .student-frame {
  box-shadow:
    0 0 0 4px rgba(32,22,10,.95),
    0 0 0 6px rgba(211,169,61,.35),
    0 10px 25px rgba(0,0,0,.65) !important;
}


/* ============================================================
   KEEP PHARAONIC DECORATIONS VISIBLE
   ============================================================ */

.student-hall .student-card::before,
.student-hall .student-card::after {
  pointer-events: none !important;
}
/* ============================================================
   STUDENT HALL — FINAL OVERFLOW FIX
   لا يغير تصميم الموقع أو الـ Temple
   ============================================================ */

/* 1 — امنع Student Hall من توسيع الصفحة */
.student-hall {
  position: relative;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  overflow-x: clip;
  overflow-y: visible;
  box-sizing: border-box;
}

/* 2 — خلي كل العناصر داخله محسوبة صح */
.student-hall,
.student-hall *,
.student-hall *::before,
.student-hall *::after {
  box-sizing: border-box;
}

/* 3 — الـ Cards لا تتسبب في زيادة عرض الصفحة */
.student-hall .student-card {
  max-width: 100%;
  min-width: 0;
}

/* 4 — الـ Frame يحتفظ بكل التأثيرات داخله */
.student-hall .student-frame {
  position: relative;
  max-width: 100%;
  min-width: 0;
  overflow: hidden;
  isolation: isolate;
}

/* 5 — الصورة لا تكبر خارج الـFrame */
.student-hall .student-frame img {
  display: block;
  max-width: 100%;
}

/* 6 — الشعاع الذهبي ممنوع يخرج من الـFrame */
.student-hall .student-frame::after {
  max-width: none;
  pointer-events: none;
}

/* 7 — الـ3D Hover يفضل داخل مساحة الـHall */
.student-hall .student-card:hover,
.student-hall .student-card.first:hover {
  z-index: 100;
}

/* 8 — لا تسمح للـDecorations بتوسيع الصفحة */
.student-hall .student-card::before,
.student-hall .student-card::after {
  pointer-events: none;
}

/* ============================================================
   FINAL VIEWPORT PROTECTION
   مهم: لا نستخدم 100vw
   ============================================================ */

html {
  overflow-x: clip;
}

/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 700px) {

  .student-hall {
    width: 100%;
    max-width: 100%;
  }

  .student-hall .student-card {
    max-width: 100%;
  }

}
/* ============================================================
   GU LIBRARY — RELIC SERVICES
   ALTERNATING TEMPLE DISPLAY
   ============================================================ */

.relic-grid {
  position: relative;
  z-index: 20;

  width: min(1180px, 90%);
  margin: 0 auto;

  display: grid;
  grid-template-columns: repeat(4, 1fr);

  gap: clamp(25px, 3.5vw, 55px);

  align-items: start;

  padding: 100px 0 150px;
}


/* ============================================================
   STATION
   ============================================================ */

.relic-station {
  position: relative;

  width: 100%;

  display: flex;
  justify-content: center;

  transition:
    transform .45s cubic-bezier(.16,1,.3,1);
}


/* طلوع / نزول */

.relic-station:nth-child(odd) {
  transform: translateY(-42px);
}

.relic-station:nth-child(even) {
  transform: translateY(42px);
}


/* حركة بسيطة للعنصر كله */

.relic-station:hover {
  transform: translateY(-50px);
}

.relic-station:nth-child(even):hover {
  transform: translateY(34px);
}


/* ============================================================
   CARD
   ============================================================ */

.relic-btn {
  position: relative;

  width: 100%;
  max-width: 245px;
  height: 330px;

  padding: 22px 16px 24px;

  border: 0;

  border-radius: 6px;

  cursor: pointer;

  overflow: visible;

  isolation: isolate;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;

  background:
    linear-gradient(
      135deg,
      rgba(77, 52, 25, .98) 0%,
      rgba(39, 27, 15, .98) 42%,
      rgba(67, 43, 19, .98) 100%
    );

  box-shadow:
    0 22px 35px rgba(0,0,0,.45),
    0 5px 0 rgba(12,8,4,.9);

  transition:
    transform .35s cubic-bezier(.16,1,.3,1),
    box-shadow .35s ease,
    filter .35s ease;

  will-change: transform;
}


/* ============================================================
   OUTER GOLD FRAME
   ============================================================ */

.relic-btn::before {
  content: "";

  position: absolute;
  inset: 0;

  border: 2px solid rgba(205,160,62,.72);

  border-radius: 6px;

  box-shadow:
    inset 0 0 0 4px rgba(27,18,9,.85),
    inset 0 0 0 5px rgba(231,190,88,.20);

  pointer-events: none;

  z-index: 8;
}


/* ============================================================
   INNER FRAME
   ============================================================ */

.relic-btn::after {
  content: "";

  position: absolute;

  inset: 12px;

  border: 1px solid rgba(221,178,77,.38);

  pointer-events: none;

  z-index: 7;
}


/* ============================================================
   TOP TEMPLE ORNAMENT
   ============================================================ */

.relic-btn > .relic-glow-ring {
  position: absolute;

  top: -17px;
  left: 50%;

  width: 76px;
  height: 34px;

  transform: translateX(-50%);

  border: 2px solid rgba(218,174,70,.72);

  border-bottom: 0;

  border-radius: 50% 50% 0 0;

  background:
    linear-gradient(
      180deg,
      rgba(125,87,28,.9),
      rgba(45,29,13,.95)
    );

  opacity: 1;

  box-shadow:
    0 -4px 12px rgba(211,164,53,.12);

  z-index: 10;

  transition:
    width .35s ease,
    box-shadow .35s ease;
}


/* ============================================================
   CENTER ORNAMENT
   ============================================================ */

.relic-btn > .relic-glow-ring::after {
  content: "𓂀";

  position: absolute;

  left: 50%;
  top: 50%;

  transform: translate(-50%,-50%);

  font-size: 16px;

  color: #f1cc68;

  text-shadow:
    0 0 8px rgba(241,204,104,.35);
}


/* ============================================================
   ART AREA
   ============================================================ */

.relic-figure {
  position: relative;

  z-index: 6;

  width: 155px;
  height: 185px;

  margin-bottom: 8px;

  display: block;

  transform: translateY(0) scale(1);

  filter:
    drop-shadow(0 12px 9px rgba(0,0,0,.45));

  transition:
    transform .4s cubic-bezier(.16,1,.3,1),
    filter .4s ease;
}


/* كل عنصر يطلع عند الـhover */

.relic-btn:hover .relic-figure {
  transform:
    translateY(-14px)
    scale(1.055);

  filter:
    drop-shadow(0 18px 14px rgba(0,0,0,.5))
    drop-shadow(0 0 10px rgba(220,174,65,.18));
}


/* ============================================================
   DIFFERENT OBJECT SIZES
   ============================================================ */

.relic-guardian {
  width: 145px;
}

.relic-mirror {
  width: 165px;
}

.relic-scroll {
  width: 165px;
}

.relic-tablet {
  width: 150px;
}


/* ============================================================
   GOLD FLOOR / PEDESTAL
   ============================================================ */

.relic-pedestal {
  position: absolute;

  left: 50%;
  bottom: 62px;

  width: 145px;
  height: 12px;

  transform: translateX(-50%);

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(216,174,68,.95) 20%,
      rgba(250,215,112,1) 50%,
      rgba(216,174,68,.95) 80%,
      transparent
    );

  box-shadow:
    0 5px 14px rgba(0,0,0,.55),
    0 0 13px rgba(220,174,65,.18);

  border-radius: 50%;

  z-index: 5;

  transition:
    width .35s ease,
    box-shadow .35s ease;
}


.relic-btn:hover .relic-pedestal {
  width: 165px;

  box-shadow:
    0 6px 16px rgba(0,0,0,.6),
    0 0 20px rgba(220,174,65,.28);
}


/* ============================================================
   LABEL
   ============================================================ */

.relic-label {
  position: relative;

  z-index: 10;

  min-width: 130px;

  margin-top: 12px;
  padding: 9px 16px;

  color: #f1d078;

  font-family:
    "Cinzel",
    Georgia,
    serif;

  font-size: 13px;
  font-weight: 700;

  letter-spacing: 2px;

  text-transform: uppercase;

  text-align: center;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(20,13,7,.8),
      transparent
    );

  border-top: 1px solid rgba(218,174,70,.32);
  border-bottom: 1px solid rgba(218,174,70,.32);

  text-shadow:
    0 2px 4px rgba(0,0,0,.9);

  transition:
    color .3s ease,
    letter-spacing .3s ease,
    border-color .3s ease;
}


.relic-btn:hover .relic-label {
  color: #ffe49a;

  letter-spacing: 2.7px;

  border-color:
    rgba(244,211,94,.65);
}


/* ============================================================
   HOVER CARD
   ============================================================ */

.relic-btn:hover {
  transform: translateY(-10px);

  box-shadow:
    0 30px 45px rgba(0,0,0,.52),
    0 0 25px rgba(206,160,56,.12),
    0 5px 0 rgba(10,7,3,.95);
}


.relic-btn:hover > .relic-glow-ring {
  width: 88px;

  box-shadow:
    0 -5px 20px rgba(225,180,67,.22);
}


/* ============================================================
   SMALL DECORATIVE CORNERS
   ============================================================ */

.relic-btn {
  background-image:
    linear-gradient(
      135deg,
      rgba(255,220,130,.04) 0%,
      transparent 20%,
      transparent 80%,
      rgba(255,220,130,.035) 100%
    );
}


/* ============================================================
   REMOVE HEAVY CONTINUOUS ANIMATION
   ============================================================ */

.relic-btn,
.relic-figure,
.relic-glow-ring,
.relic-pedestal,
.relic-label {
  animation: none;
}


/* ============================================================
   TABLET
   ============================================================ */

@media (max-width: 1050px) {

  .relic-grid {
    grid-template-columns: repeat(2, 1fr);

    width: min(700px, 88%);

    gap: 70px 35px;
  }

  .relic-station:nth-child(odd),
  .relic-station:nth-child(even) {
    transform: none;
  }

  .relic-station:nth-child(3) {
    transform: translateY(-25px);
  }

  .relic-station:nth-child(4) {
    transform: translateY(25px);
  }
}


/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 560px) {

  .relic-grid {
    grid-template-columns: 1fr;

    width: min(300px, 85%);

    gap: 35px;

    padding-top: 60px;
  }

  .relic-station:nth-child(n) {
    transform: none;
  }

  .relic-btn {
    max-width: 250px;
  }
}
