/* ============================================================
   GU LIBRARY — HALL OF STORIES
   ROYAL PHARAONIC MANUSCRIPT
   MATCHES THE CURRENT HTML EXACTLY
   ============================================================ */


/* ============================================================
   MAIN BOOK
   ============================================================ */

.stories-heading {
  position: relative;

  z-index: 30;

  width: min(1000px, 90vw);
  height: 405px;

  margin: 0 auto 80px;

  padding: 0;

  perspective: 1800px;

  transform-style: preserve-3d;

  isolation: isolate;

  overflow: visible;
}


/* ============================================================
   COVER / BACK OF BOOK
   ============================================================ */

.book-cover {
  position: absolute;

  inset: 0;

  z-index: -5;

  border-radius: 22px;

  background:
    linear-gradient(
      90deg,
      #171008 0%,
      #4a3014 6%,
      #765020 11%,
      #38230e 42%,
      #120b06 49.5%,
      #080402 50%,
      #120b06 50.5%,
      #38230e 58%,
      #765020 89%,
      #4a3014 94%,
      #171008 100%
    );

  border:
    2px solid rgba(195,151,67,.72);

  box-shadow:
    0 30px 48px rgba(0,0,0,.62),
    0 9px 0 #0d0704,
    inset 0 0 35px rgba(0,0,0,.68),
    inset 0 0 0 3px rgba(238,197,105,.09);
}


/* inner cover frame */

.book-cover::before {
  content: "";

  position: absolute;

  inset: 10px;

  border:
    1px solid rgba(221,179,83,.27);

  border-radius: 15px;

  box-shadow:
    inset 0 0 0 4px rgba(94,59,18,.10),
    inset 0 0 20px rgba(0,0,0,.28);
}


/* ============================================================
   REAL PAGES
   ============================================================ */

.book-page {
  position: absolute;

  top: 18px;
  bottom: 18px;

  width: calc(50% - 13px);

  overflow: hidden;

  box-sizing: border-box;

  border:
    1px solid rgba(91,57,17,.70);

  background:

    radial-gradient(
      ellipse at 20% 18%,
      rgba(255,238,181,.22),
      transparent 30%
    ),

    radial-gradient(
      ellipse at 80% 75%,
      rgba(100,62,18,.16),
      transparent 28%
    ),

    repeating-linear-gradient(
      0deg,
      rgba(83,51,14,.075) 0,
      rgba(83,51,14,.075) 1px,
      transparent 1px,
      transparent 6px
    ),

    repeating-linear-gradient(
      90deg,
      rgba(255,241,180,.055) 0,
      rgba(255,241,180,.055) 1px,
      transparent 1px,
      transparent 9px
    ),

    linear-gradient(
      145deg,
      #b88d4b 0%,
      #d9bc7a 24%,
      #e6cf96 52%,
      #d2b16c 76%,
      #a97a3c 100%
    );

  box-shadow:
    inset 0 0 25px rgba(73,42,10,.22);
}


/* ============================================================
   LEFT PAGE
   ============================================================ */

.book-page-left {

  left: 16px;

  border-radius:
    20px 4px 4px 20px;

  transform-origin: right center;

  transform:
    perspective(1700px)
    rotateY(7deg)
    rotateZ(-.35deg);

  box-shadow:
    10px 7px 0 rgba(88,55,16,.22),
    5px 4px 0 rgba(128,88,33,.18),
    inset -20px 0 25px rgba(70,40,9,.15),
    inset 0 0 28px rgba(70,40,9,.18);

  animation:
    leftManuscriptPage 9s ease-in-out infinite;
}


/* ============================================================
   RIGHT PAGE
   ============================================================ */

.book-page-right {

  right: 16px;

  border-radius:
    4px 20px 20px 4px;

  transform-origin: left center;

  transform:
    perspective(1700px)
    rotateY(-7deg)
    rotateZ(.35deg);

  box-shadow:
    -10px 7px 0 rgba(88,55,16,.22),
    -5px 4px 0 rgba(128,88,33,.18),
    inset 20px 0 25px rgba(70,40,9,.15),
    inset 0 0 28px rgba(70,40,9,.18);

  animation:
    rightManuscriptPage 9s ease-in-out infinite;
}


/* ============================================================
   PAGE INNER BORDER
   ============================================================ */

.book-page::before {
  content: "";

  position: absolute;

  inset: 12px;

  border:
    1px solid rgba(105,68,20,.36);

  border-radius: inherit;

  pointer-events: none;

  box-shadow:
    inset 0 0 0 4px rgba(255,230,158,.07);
}


/* ============================================================
   LEFT PAGE — HIEROGLYPHS
   ============================================================ */

.hieroglyphic-manuscript {
  position: absolute;

  left: 34px;
  right: 34px;

  top: 40px;
  bottom: 40px;

  z-index: 4;

  display: flex;

  flex-direction: column;

  justify-content: space-between;

  color:
    rgba(67,39,11,.60);

  font-family:
    Georgia,
    serif;

  font-size: 14px;

  line-height: 1;

  letter-spacing: 4px;

  text-align: center;

  text-shadow:
    0 1px 0 rgba(255,234,173,.30);

  opacity: .94;

  animation:
    manuscriptInk 9s ease-in-out infinite;
}


/* each manuscript line */

.glyph-line {
  position: relative;

  white-space: nowrap;

  transform-origin: center;
}


/* imperfect handwritten feeling */

.glyph-line:nth-child(1) {
  transform: rotate(-1deg);
}

.glyph-line:nth-child(2) {
  transform:
    translateX(4px)
    rotate(.6deg);
}

.glyph-line:nth-child(3) {
  transform:
    translateX(-3px)
    rotate(-.7deg);
}

.glyph-line:nth-child(4) {
  transform:
    translateX(5px)
    rotate(.8deg);
}

.glyph-line:nth-child(5) {
  transform:
    translateX(-4px)
    rotate(-.5deg);
}

.glyph-line:nth-child(6) {
  transform:
    translateX(3px)
    rotate(.6deg);
}

.glyph-line:nth-child(7) {
  transform:
    translateX(-2px)
    rotate(-.4deg);
}

.glyph-line:nth-child(8) {
  transform:
    translateX(4px)
    rotate(.7deg);
}


/* ============================================================
   ANCIENT SEAL — LEFT PAGE
   ============================================================ */

.ancient-seal {
  position: absolute;

  z-index: 6;

  left: 30px;
  bottom: 28px;

  width: 42px;
  height: 42px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 50%;

  color: #684719;

  font-family: serif;

  font-size: 19px;

  background:
    radial-gradient(
      circle,
      #e6ca87 0%,
      #c0964e 57%,
      #8d6227 100%
    );

  border:
    1px solid rgba(86,51,12,.70);

  box-shadow:
    inset 0 0 7px rgba(66,37,8,.25),
    0 3px 6px rgba(52,29,7,.22);

  transform:
    rotate(-8deg);
}


/* ============================================================
   VERTICAL GLYPHS
   ============================================================ */

.vertical-glyphs {
  position: absolute;

  right: 19px;
  top: 45px;

  color:
    rgba(70,42,11,.46);

  font-family: serif;

  font-size: 13px;

  line-height: 1.65;

  text-align: center;
}


/* ============================================================
   RIGHT PAGE DECORATIONS
   ============================================================ */

.title-page-glyph {
