/* ============================================================
   PAGE STACKS
   ============================================================ */

.page-edge {
  position: absolute;

  z-index: -1;

  top: 25px;
  bottom: 25px;

  width: calc(50% - 11px);

  background:
    linear-gradient(
      180deg,
      #9e753b,
      #bd9553
    );

  border:
    1px solid rgba(72,42,10,.42);

  opacity: .72;
}


.page-edge-left-1 {
