.page-edge-right-2 {
  right: 7px;

  border-radius:
    3px 17px 17px 3px;

  transform:
    rotate(1.5deg);

  opacity: .42;
}


/* ============================================================
   PAGE MOVEMENT
   ============================================================ */

@keyframes leftManuscriptPage {

  0%,
  100% {
    transform:
      perspective(1700px)
      rotateY(7deg)
      rotateZ(-.35deg);
  }

  50% {
    transform:
      perspective(1700px)
      rotateY(9deg)
      rotateZ(-.60deg);
  }
}


@keyframes rightManuscriptPage {

  0%,
  100% {
    transform:
      perspective(1700px)
      rotateY(-7deg)
      rotateZ(.35deg);
  }

  50% {
    transform:
      perspective(1700px)
      rotateY(-9deg)
      rotateZ(.60deg);
  }
}


@keyframes manuscriptInk {

  0%,
  100% {
    transform:
      translateX(0)
      rotate(-.2deg);
  }

  50% {
    transform:
      translateX(1px)
      rotate(.15deg);
  }
}


/* ============================================================
