.stories-heading h2,
.stories-heading .title {
    color: #ead29a;

    text-shadow:
        0 1px 0 rgba(0, 0, 0, 0.8),
        0 0 8px rgba(220, 174, 75, 0.22),
        0 0 20px rgba(220, 174, 75, 0.08);
}


/* ============================================================
   زخارف هيروغليفية عائمة
   ============================================================ */

.stories-heading .hieroglyphic-manuscript {
    color: #d8ae55;

    text-shadow:
        0 0 5px rgba(222, 175, 70, 0.55),
        0 0 14px rgba(222, 175, 70, 0.20),
        0 1px 2px rgba(0, 0, 0, 0.9);

    filter:
        drop-shadow(
            0 2px 3px rgba(0, 0, 0, 0.65)
        );
}


/* ============================================================
   توهج خفيف متحرك للهُيروغليفية
   ============================================================ */

@keyframes pharaohGlyphGlow {

    0% {
        filter:
            drop-shadow(
                0 0 3px rgba(222, 175, 70, 0.20)
            );
    }

    50% {
        filter:
            drop-shadow(
                0 0 9px rgba(222, 175, 70, 0.42)
            );
    }

    100% {
        filter:
            drop-shadow(
                0 0 3px rgba(222, 175, 70, 0.20)
            );
    }
}

.stories-heading .hieroglyphic-manuscript {
    animation:
        pharaohGlyphGlow 5s ease-in-out infinite;
}


/* ============================================================
   حواف الصفحة — إحساس جدار معبد
   ============================================================ */

.stories-section,
.hall-of-stories,
#stories,
.stories-page {

    box-shadow:
        inset 0 35px 55px rgba(0, 0, 0, 0.38),
        inset 0 -45px 70px rgba(0, 0, 0, 0.48),
        inset 35px 0 70px rgba(0, 0, 0, 0.30),
        inset -35px 0 70px rgba(0, 0, 0, 0.30);
}


/* ============================================================
   إطار فرعوني خفيف جدًا
   ============================================================ */

.stories-section {
    border-top:
        1px solid rgba(220, 176, 79, 0.18);

    border-bottom:
        1px solid rgba(220, 176, 79, 0.12);
}


/* ============================================================
   MOBILE
   ============================================================ */

@media (max-width: 768px) {

    .stories-section::after,
    .hall-of-stories::after,
    #stories::after,
    .stories-page::after {

        font-size: 70px;
        letter-spacing: 18px;
    }

    .stories-heading::before {
        left: 3%;
        right: 3%;
    }

    .stories-heading::after {
        left: 8%;
        right: 8%;
    }
}
/* ============================================================
   HIEROGLYPHIC MANUSCRIPT — TEXT / PARAGRAPH STYLE
   ============================================================ */

.hieroglyphic-manuscript {
    position: absolute;

    top: 95px;
    left: 38px;
    right: 38px;
    bottom: 85px;

    display: block;

    direction: ltr;
    text-align: left;

    overflow: hidden;

    font-family:
        "Noto Sans Egyptian Hieroglyphs",
        "Segoe UI Historic",
        serif;

    font-size: 23px;
    line-height: 1.65;

    letter-spacing: 2px;

    color: #4a2d13;

    text-shadow:
        0.4px 0.4px 0 rgba(70, 40, 15, 0.35);
}


/* كل سطر يتعامل كجزء من نفس النص */
.hieroglyphic-manuscript .glyph-line {
    display: inline;

    margin: 0;
    padding: 0;

    white-space: normal;

    font-size: inherit;
    line-height: inherit;
    letter-spacing: inherit;
}


/* مسافة صغيرة بين المقاطع فقط */
.hieroglyphic-manuscript .glyph-line::after {
    content: "   ";
}


/* ============================================================
   لمسة حبر قديم
   ============================================================ */

.hieroglyphic-manuscript {
    opacity: 0.92;

    filter:
        drop-shadow(
            0 1px 0 rgba(255, 225, 160, 0.18)
        );
}


/* ============================================================
   لو الصفحة صغيرة
   ============================================================ */

@media (max-width: 900px) {

    .hieroglyphic-manuscript {
        font-size: 19px;
        line-height: 1.55;

        left: 28px;
        right: 28px;
    }
}
 /* ============================================================
    HIEROGLYPHIC TEXT — STRONG INK / ANCIENT PAPYRUS
    ============================================================ */

.book-page-left .hieroglyphic-manuscript {
    color: #3a210d !important;

    opacity: 1 !important;

    text-shadow:
        0.6px 0.6px 0 #6b421b,
        -0.3px -0.3px 0 rgba(255, 232, 177, 0.35),
        0 1px 2px rgba(35, 18, 5, 0.35);

    filter:
        contrast(1.18)
        saturate(1.15);
}


/* كل الرموز نفسها */
.book-page-left .hieroglyphic-manuscript .glyph-line {
    color: #3a210d !important;

    opacity: 1 !important;

    font-weight: 600;

    text-shadow:
        0.6px 0.6px 0 #6b421b,
        0 1px 1px rgba(40, 20, 5, 0.35);
}


/* لمعة حبر خفيفة جدًا */
.book-page-left .hieroglyphic-manuscript .glyph-line::selection {
    background: rgba(170, 116, 42, 0.25);
}


/* لو فيه رموز داخلية أو spans */
.book-page-left .hieroglyphic-manuscript span {
    color: #3a210d !important;
    opacity: 1 !important;
}


/* تحسين وضوح الهيروغليفية على الخلفية */
.book-page-left .hieroglyphic-manuscript {
    -webkit-font-smoothing: antialiased;
    text-rendering: geometricPrecision;
}
/* ============================================================
   RIGHT PAGE — CLEAN PHARAONIC DECORATION
   ============================================================ */

.stories-heading .book-page-right .top-glyph {
