    transform: translateX(-50%);

    z-index: 3;

    font-size: 27px;
    line-height: 1;

    color: rgba(107, 66, 27, 0.5);

    pointer-events: none;
}


/* 𓇳 الصغيرة — زخرفة وليس عنوان */
.stories-heading .book-page-right .title-crown {
    position: absolute;
    top: 38%;
    left: 50%;
    transform: translateX(-50%);

    z-index: 3;

    font-size: 20px;

