    pointer-events: none;
}


/* 𓆄 𓆄 𓆄 */
.stories-heading .book-page-right .title-decoration {
    position: absolute;
    top: 43%;
    left: 50%;
    transform: translateX(-50%);

    z-index: 3;

    white-space: nowrap;

    font-size: 17px;
    letter-spacing: 7px;

