    left: 75% !important;
    top: 50% !important;

    transform: translate(-50%, 45%) !important;

    width: 30% !important;

    margin: 0 !important;

    text-align: center !important;

    z-index: 50 !important;

    color: #654522 !important;

    font-family: Georgia, "Times New Roman", serif;

