}
/* ============================================================
   HALL OF STORIES — ANCIENT PHARAONIC BOOK
   PAPER + COVER + SPINE DETAILS
   ============================================================ */


/* ============================================================
   1. BOOK — DEPTH
   ============================================================ */

.stories-heading .book-cover {
    filter:
        drop-shadow(0 18px 25px rgba(0, 0, 0, 0.42))
        drop-shadow(0 3px 5px rgba(78, 47, 15, 0.25));
}


/* ============================================================
   2. PAGES — WARM ANCIENT PAPYRUS
   ============================================================ */

.stories-heading .book-page {
    background:
        radial-gradient(
            ellipse at 50% 45%,
            rgba(255, 239, 194, 0.95) 0%,
            rgba(225, 194, 133, 0.92) 58%,
            rgba(173, 137, 82, 0.95) 100%
        ) !important;

    box-shadow:
        inset 0 0 35px rgba(91, 55, 18, 0.25),
        inset 0 0 8px rgba(255, 238, 183, 0.55),
        0 4px 12px rgba(42, 24, 7, 0.28);
}


/* ============================================================
   3. OLD PAPER TEXTURE
   ============================================================ */

.stories-heading .book-page::after {
    content: "";

    position: absolute;

    inset: 10px;

    pointer-events: none;

    z-index: 1;

    opacity: 0.35;

    background:
        radial-gradient(
            circle at 15% 20%,
            rgba(112, 71, 25, 0.18) 0 1px,
            transparent 2px
        ),
        radial-gradient(
            circle at 75% 65%,
            rgba(112, 71, 25, 0.13) 0 1px,
            transparent 2px
        ),
        radial-gradient(
            circle at 35% 85%,
            rgba(112, 71, 25, 0.15) 0 1px,
            transparent 2px
        );

    background-size:
        95px 95px,
        130px 130px,
        160px 160px;

    mix-blend-mode: multiply;
}


/* ============================================================
   4. PAGE EDGES — OLD PAPER
   ============================================================ */

.stories-heading .page-edge {
    background:
        linear-gradient(
            90deg,
            #76542c,
            #d6b77b 18%,
            #a98652 50%,
            #e0c58d 82%,
            #70502b
        ) !important;

    box-shadow:
        0 2px 5px rgba(0, 0, 0, 0.25);
}


/* ============================================================
   5. PAGE FRAME
   ============================================================ */

.stories-heading .page-frame {
    position: absolute;

    inset: 15px;

    border:
        1px solid rgba(120, 78, 27, 0.45);

    box-shadow:
        inset 0 0 0 1px rgba(255, 231, 175, 0.35),
        inset 0 0 18px rgba(103, 63, 20, 0.15);

    pointer-events: none;

    z-index: 3;
}


/* ============================================================
   6. GOLDEN INNER BORDER
   ============================================================ */

.stories-heading .page-frame::before {
    content: "";

    position: absolute;

    inset: 7px;

    border:
        1px solid rgba(157, 111, 43, 0.25);

    pointer-events: none;
}


/* ============================================================
   7. BOOK SPINE
   ============================================================ */

.stories-heading .book-spine {
    background:
        linear-gradient(
            90deg,
            #3d2813 0%,
            #765321 18%,
            #b88b3d 38%,
            #5c3d18 58%,
            #9b702e 78%,
            #34200e 100%
        ) !important;

    box-shadow:
        inset 0 0 12px rgba(0, 0, 0, 0.55),
        0 0 10px rgba(0, 0, 0, 0.35);
}


/* ============================================================
   8. SPINE HIGHLIGHT
   ============================================================ */

.stories-heading .spine-highlight {
    background:
        linear-gradient(
            180deg,
            transparent,
            rgba(240, 201, 104, 0.7),
            transparent
        ) !important;

    opacity: 0.65;
}


/* ============================================================
   9. SPINE SEAL
   ============================================================ */

.stories-heading .spine-seal {
    color: #d4a94f !important;

    text-shadow:
        0 1px 0 #4c3013,
        0 0 8px rgba(226, 179, 73, 0.35);

    filter:
        drop-shadow(0 2px 2px rgba(0, 0, 0, 0.45));
}


/* ============================================================
   10. GOLDEN PAGE CORNERS
   ============================================================ */

.stories-heading .book-page-left::after,
.stories-heading .book-page-right::after {
    border-radius: 3px;

    box-shadow:
        inset 0 0 14px rgba(108, 66, 20, 0.18);
}


/* ============================================================
   11. MANUSCRIPT RED LINE
   ============================================================ */

.stories-heading .manuscript-red-line {
    background:
        linear-gradient(
            90deg,
            transparent,
            rgba(117, 45, 25, 0.75),
            rgba(150, 66, 29, 0.55),
            transparent
        ) !important;

    box-shadow:
        0 0 5px rgba(121, 48, 25, 0.22);
}


/* ============================================================
   12. ANCIENT SEAL
   ============================================================ */

.stories-heading .ancient-seal {
    color: #79501f !important;

    text-shadow:
        0 1px 0 rgba(255, 228, 166, 0.55),
        0 2px 4px rgba(49, 27, 7, 0.35);
}


/* ============================================================
   13. FOOTER HIEROGLYPHS
   ============================================================ */

.stories-heading .manuscript-footer {
    color: #76501f !important;

    opacity: 0.75;

    text-shadow:
        0 1px 0 rgba(255, 227, 166, 0.5);
}


/* ============================================================
   14. BOOK COVER — LEATHER / GOLD
   ============================================================ */

.stories-heading .book-cover {
    background:
        linear-gradient(
            135deg,
            #2c1a0b 0%,
            #65431c 20%,
            #8c6429 48%,
            #4c3014 72%,
            #241508 100%
        ) !important;

    box-shadow:
        inset 0 0 18px rgba(0, 0, 0, 0.65),
        inset 0 0 3px rgba(230, 188, 93, 0.55),
        0 15px 30px rgba(0, 0, 0, 0.45);
}


/* ============================================================
   15. GOLDEN COVER BORDER
   ============================================================ */

.stories-heading .book-cover::before {
    content: "";

    position: absolute;

    inset: 12px;

    border:
        1px solid rgba(220, 174, 75, 0.55);

    box-shadow:
        inset 0 0 0 1px rgba(79, 47, 14, 0.7);

    pointer-events: none;
}


/* ============================================================
   16. COVER CENTER ORNAMENT
   ============================================================ */

.stories-heading .book-cover::after {
    content: "𓂀  𓋹  𓇳  𓋹  𓂀";

    position: absolute;

    left: 50%;
    top: 50%;

    transform: translate(-50%, -50%);

    white-space: nowrap;

    font-size: 20px;

    letter-spacing: 4px;

    color: rgba(220, 174, 75, 0.62);

    text-shadow:
        0 1px 0 #2c1908,
        0 0 8px rgba(221, 174, 73, 0.22);

    pointer-events: none;
}


/* ============================================================
   17. SUBTLE GOLD LIGHT
   ============================================================ */

.stories-heading .book-cover {
    animation:
        ancientBookGlow 7s ease-in-out infinite;
}


@keyframes ancientBookGlow {

    0% {
        box-shadow:
            inset 0 0 18px rgba(0, 0, 0, 0.65),
            inset 0 0 3px rgba(230, 188, 93, 0.45),
            0 15px 30px rgba(0, 0, 0, 0.45);
    }

    50% {
        box-shadow:
            inset 0 0 18px rgba(0, 0, 0, 0.65),
            inset 0 0 5px rgba(230, 188, 93, 0.7),
            0 15px 30px rgba(0, 0, 0, 0.45);
    }

    100% {
        box-shadow:
            inset 0 0 18px rgba(0, 0, 0, 0.65),
            inset 0 0 3px rgba(230, 188, 93, 0.45),
            0 15px 30px rgba(0, 0, 0, 0.45);
    }
}
/* ============================================================
   PHARAONIC BOOK — REALISTIC 3D MOTION
   ============================================================ */

.stories-heading {
    perspective: 1800px;
    perspective-origin: 50% 50%;
}


/* ============================================================
   BOOK DEPTH
   ============================================================ */

.stories-heading .book-cover,
.stories-heading .book-page,
.stories-heading .book-spine,
.stories-heading .page-edge {
    transform-style: preserve-3d;
}


/* ============================================================
   BOOK COVER — LIVING LEATHER
   ============================================================ */

.stories-heading .book-cover {
    transform-origin: center center;

    will-change: transform;

    animation:
        bookBreathing 6s ease-in-out infinite;

    transition:
        filter 0.5s ease;
}


/* ============================================================
   SLOW BOOK BREATHING
   ============================================================ */

@keyframes bookBreathing {

    0% {
        transform:
            translateY(0)
            rotateX(0deg)
            rotateY(0deg);
    }

    25% {
        transform:
            translateY(-2px)
            rotateX(0.35deg)
            rotateY(-0.4deg);
    }

    50% {
        transform:
            translateY(0)
            rotateX(0deg)
            rotateY(0.4deg);
    }

    75% {
        transform:
            translateY(-1px)
            rotateX(-0.3deg)
            rotateY(-0.35deg);
    }

    100% {
        transform:
            translateY(0)
            rotateX(0deg)
            rotateY(0deg);
    }
}


/* ============================================================
   PAGES — DIFFERENT DEPTHS
   ============================================================ */

.stories-heading .book-page-left {
    transform:
        translateZ(4px)
        rotateY(0deg);

    animation:
        leftPageFloat 7s ease-in-out infinite;
}


.stories-heading .book-page-right {
    transform:
        translateZ(5px)
        rotateY(0deg);

    animation:
        rightPageFloat 7s ease-in-out infinite;
}


@keyframes leftPageFloat {

    0%,
    100% {
        transform:
            translateZ(4px)
            rotateY(0deg);
    }

    50% {
        transform:
            translateZ(8px)
            rotateY(-0.25deg);
    }
}


@keyframes rightPageFloat {

    0%,
    100% {
        transform:
            translateZ(5px)
            rotateY(0deg);
    }

    50% {
        transform:
            translateZ(9px)
            rotateY(0.25deg);
    }
}


/* ============================================================
   SPINE — HEAVY BOOK FEEL
   ============================================================ */

.stories-heading .book-spine {
    transform-origin: center center;

    animation:
        spineBreathing 6s ease-in-out infinite;
}


@keyframes spineBreathing {

    0%,
    100% {
        transform:
            translateZ(8px)
            scaleX(1);
    }

    50% {
        transform:
            translateZ(12px)
            scaleX(1.015);
    }
}


/* ============================================================
   PAGE EDGES — SMALL INDEPENDENT MOVEMENT
   ============================================================ */

.stories-heading .page-edge-left-1 {
    animation:
        edgeLeftOne 6s ease-in-out infinite;
}


.stories-heading .page-edge-left-2 {
    animation:
        edgeLeftTwo 7s ease-in-out infinite;
}


.stories-heading .page-edge-right-1 {
    animation:
        edgeRightOne 6.5s ease-in-out infinite;
}


.stories-heading .page-edge-right-2 {
    animation:
        edgeRightTwo 7.5s ease-in-out infinite;
}


@keyframes edgeLeftOne {

    0%,
    100% {
        transform: translateX(0);
    }

    50% {
        transform: translateX(-2px);
    }
}


@keyframes edgeLeftTwo {

    0%,
    100% {
        transform: translateX(0);
    }

    50% {
        transform: translateX(-3px);
    }
}


@keyframes edgeRightOne {

    0%,
    100% {
        transform: translateX(0);
    }

    50% {
        transform: translateX(2px);
    }
}


@keyframes edgeRightTwo {

    0%,
    100% {
        transform: translateX(0);
    }

    50% {
        transform: translateX(3px);
    }
}


/* ============================================================
   GOLDEN LIGHT MOVING OVER THE COVER
   ============================================================ */

.stories-heading .book-cover {
    overflow: hidden;
}


.stories-heading .book-cover::marker {
    display: none;
}


/* ============================================================
   BOOK SHADOW — CHANGES WITH MOTION
   ============================================================ */

.stories-heading .book-cover {
    filter:
        drop-shadow(
            0 22px 20px rgba(0, 0, 0, 0.38)
        )
        drop-shadow(
            0 4px 7px rgba(73, 43, 12, 0.25)
        );
}


/* ============================================================
   REALISTIC PAGE EDGE HIGHLIGHTS
   ============================================================ */

.stories-heading .book-page-left,
.stories-heading .book-page-right {

    box-shadow:
        inset 8px 0 15px rgba(74, 43, 12, 0.10),
        inset -8px 0 15px rgba(74, 43, 12, 0.10),
        inset 0 5px 12px rgba(255, 236, 185, 0.28),
        inset 0 -8px 15px rgba(82, 48, 13, 0.12),
        0 7px 12px rgba(0, 0, 0, 0.12);
}


/* ============================================================
   BOOK HOVER — BIG INTERACTION
   ============================================================ */

.stories-heading:hover .book-cover {

    filter:
        drop-shadow(
            0 28px 25px rgba(0, 0, 0, 0.48)
        )
        drop-shadow(
            0 0 15px rgba(218, 174, 76, 0.14)
        );
}


.stories-heading:hover .book-page-left {

    transform:
        translateZ(14px)
        rotateY(-0.8deg);
}


.stories-heading:hover .book-page-right {

    transform:
        translateZ(16px)
        rotateY(0.8deg);
}


.stories-heading:hover .book-spine {

    transform:
        translateZ(18px)
        scaleX(1.025);
}


/* ============================================================
   GOLDEN SYMBOLS REACT TO BOOK MOTION
   ============================================================ */

.stories-heading .manuscript-header,
.stories-heading .manuscript-footer,
.stories-heading .ancient-seal,
.stories-heading .spine-seal {

    transition:
        transform 0.6s ease,
        text-shadow 0.6s ease;
}


.stories-heading:hover .manuscript-header {
    transform: translateY(-2px);
}


.stories-heading:hover .manuscript-footer {
    transform: translateY(2px);
}


.stories-heading:hover .spine-seal {

    transform:
        scale(1.08)
        rotate(2deg);

    text-shadow:
        0 0 8px rgba(224, 177, 73, 0.5),
        0 0 18px rgba(224, 177, 73, 0.2);
}


/* ============================================================
   TITLE — SLIGHT DEPTH
   ============================================================ */

.stories-heading > h2 {

    transition:
        transform 0.6s ease,
        text-shadow 0.6s ease;
}


.stories-heading:hover > h2 {

    transform:
        translate(-50%, -65%)
        translateZ(20px);

    text-shadow:
        0 1px 0 rgba(255, 235, 190, 0.8),
        0 3px 7px rgba(55, 27, 5, 0.35),
        0 0 15px rgba(215, 169, 71, 0.18);
}


/* ============================================================
   ACCESSIBILITY
   ============================================================ */

@media (prefers-reduced-motion: reduce) {

    .stories-heading .book-cover,
    .stories-heading .book-page-left,
    .stories-heading .book-page-right,
    .stories-heading .book-spine,
    .stories-heading .page-edge-left-1,
    .stories-heading .page-edge-left-2,
    .stories-heading .page-edge-right-1,
    .stories-heading .page-edge-right-2 {

        animation: none !important;
        transition: none !important;
    }
}
/* ============================================================
   BOOK CLICK — REPLACE THE "FLY UP" EFFECT
   ============================================================ */

/* نوقف أي حركة رفع للكتاب */
.stories-heading .book-cover,
.stories-heading .book-page-left,
.stories-heading .book-page-right,
.stories-heading .book-spine {
    transform-origin: center center;
}


/* حركة ضغط بسيطة */
.stories-heading:active .book-cover {
    animation: bookPress 0.45s ease-out;
}


@keyframes bookPress {

    0% {
        transform:
            scale(1)
            rotateX(0deg)
            rotateY(0deg);
    }

    25% {
        transform:
            scale(0.985)
            rotateX(0deg)
            rotateY(-1deg);
    }

    55% {
        transform:
            scale(1.008)
            rotateX(0deg)
            rotateY(1deg);
    }

    100% {
        transform:
            scale(1)
            rotateX(0deg)
            rotateY(0deg);
    }
}


/* الصفحات تتحرك مع الضغط بدل ما تطير لفوق */
.stories-heading:active .book-page-left {
    animation: leftPagePress 0.45s ease-out;
}


.stories-heading:active .book-page-right {
    animation: rightPagePress 0.45s ease-out;
}


@keyframes leftPagePress {

    0% {
        transform:
            translateZ(4px)
            rotateY(0deg);
    }

    45% {
        transform:
            translateZ(11px)
            rotateY(-1.2deg);
    }

    100% {
        transform:
            translateZ(4px)
            rotateY(0deg);
    }
}


@keyframes rightPagePress {

    0% {
        transform:
            translateZ(5px)
            rotateY(0deg);
    }

    45% {
        transform:
            translateZ(12px)
            rotateY(1.2deg);
    }

    100% {
        transform:
            translateZ(5px)
            rotateY(0deg);
    }
}


/* الـspine يتحرك حركة صغيرة */
.stories-heading:active .book-spine {
    animation: spinePress 0.45s ease-out;
}


@keyframes spinePress {

    0% {
        transform:
            translateZ(8px)
            scaleX(1);
    }

    50% {
        transform:
            translateZ(14px)
            scaleX(1.02);
    }

    100% {
        transform:
            translateZ(8px)
            scaleX(1);
    }
}
/* ============================================================
   HALL OF STORIES — SIMPLE MYSTICAL HOVER
   ============================================================ */


/* ------------------------------------------------------------
   الكتاب ثابت تمامًا
   ------------------------------------------------------------ */

.stories-heading:hover .book-cover,
.stories-heading:hover .book-page-left,
.stories-heading:hover .book-page-right,
.stories-heading:hover .book-spine {
    transform: none !important;
    animation: none !important;
}


/* ============================================================
   إخفاء المحتوى الأصلي عند الـhover
   ============================================================ */

.stories-heading:hover
.book-page-left
.hieroglyphic-manuscript,

.stories-heading:hover
.book-page-left
.manuscript-header,

.stories-heading:hover
.book-page-left
.manuscript-red-line,

.stories-heading:hover
.book-page-left
.ancient-seal,

.stories-heading:hover
.book-page-left
.manuscript-footer,

.stories-heading:hover > h2,

.stories-heading:hover > p {
    opacity: 0 !important;

    filter: blur(8px);

    transition:
        opacity .5s ease,
        filter .5s ease;
}


/* ============================================================
   الضباب — هادئ ومش مبالغ فيه
   ============================================================ */

.book-page-left::after,
.book-page-right::after {
    content: "";

    position: absolute;
    inset: 0;

    z-index: 20;

    pointer-events: none;

    opacity: 0;

    background:
        radial-gradient(
            ellipse at center,
            rgba(230, 196, 125, .08),
            rgba(171, 129, 57, .12) 45%,
            transparent 75%
        );

    filter: blur(10px);

    transition: opacity .6s ease;
}


.stories-heading:hover .book-page-left::after,
.stories-heading:hover .book-page-right::after {
    opacity: 1;
}


/* ============================================================
   LEFT PAGE
   جملة هيروغليفية واحدة فقط
   ============================================================ */

.book-page-left .page-frame::after {

    content:
        "𓂀 𓋹 𓏏 𓂋 𓊹 𓎛 𓏏 𓏤 𓇳";

    position: absolute;

    left: 50%;
    top: 50%;

    transform:
        translate(-50%, -50%)
        scale(.88);

    width: 82%;

    text-align: center;

    z-index: 50;

    pointer-events: none;

    opacity: 0;

    color: #553414;

    font-family:
        "Segoe UI Historic",
        "Noto Sans Egyptian Hieroglyphs",
        serif;

    font-size: 27px;

    font-weight: 800;

    letter-spacing: 5px;

    line-height: 1.7;

    text-shadow:
        0 1px 0 rgba(255, 235, 191, .9),
        0 2px 3px rgba(58, 30, 7, .35),
        0 0 10px rgba(190, 143, 53, .2);

    transition:
        opacity .65s ease,
        transform .7s cubic-bezier(.2,.8,.2,1);
}


.stories-heading:hover
.book-page-left
.page-frame::after {

    opacity: 1;

    transform:
        translate(-50%, -50%)
        scale(1);
}


/* ============================================================
   LEFT PAGE
   رموز هادئة حول الجملة
   ============================================================ */

.book-page-left .page-frame::before {

    content:
        "𓂀                 𓋹";

    position: absolute;

    left: 50%;
    top: 62%;

    transform: translateX(-50%);

    width: 80%;

    text-align: center;

    z-index: 51;

    pointer-events: none;

    opacity: 0;

    color: rgba(105, 69, 25, .65);

    font-family:
        "Segoe UI Historic",
        serif;

    font-size: 24px;

    letter-spacing: 16px;

    text-shadow:
        0 1px 0 rgba(255, 229, 173, .65);

    transition: opacity .65s ease;
}


.stories-heading:hover
.book-page-left
.page-frame::before {

    opacity: 1;
}


/* ============================================================
   RIGHT PAGE
   BEGIN READING
   ============================================================ */

.book-page-right .page-frame::after {

    content: "BEGIN READING";

    position: absolute;

    left: 50%;
    top: 50%;

    transform:
        translate(-50%, -50%)
        scale(.88);

    width: 88%;

    text-align: center;

    z-index: 50;

    pointer-events: none;

    opacity: 0;

    color: #553414;

    font-family:
        Georgia,
        "Times New Roman",
        serif;

    font-size: 31px;

    font-weight: 800;

    letter-spacing: 3px;

    line-height: 1.2;

    text-shadow:
        0 1px 0 rgba(255, 235, 191, .9),
        0 2px 3px rgba(58, 30, 7, .35),
        0 0 12px rgba(190, 143, 53, .22);

    transition:
        opacity .65s ease,
        transform .7s cubic-bezier(.2,.8,.2,1);
}


.stories-heading:hover
.book-page-right
.page-frame::after {

    opacity: 1;

    transform:
        translate(-50%, -50%)
        scale(1);
}


/* ============================================================
   RIGHT PAGE
   رموز هادئة حول BEGIN READING
   ============================================================ */

.book-page-right .page-frame::before {

    content:
        "𓇳        𓂀        𓋹";

    position: absolute;

    left: 50%;
    top: 62%;

    transform: translateX(-50%);

    width: 85%;

    text-align: center;

    z-index: 51;

    pointer-events: none;

    opacity: 0;

    color: rgba(105, 69, 25, .65);

    font-family:
        "Segoe UI Historic",
        serif;

    font-size: 22px;

    letter-spacing: 7px;

    text-shadow:
