/* =========================================================
   PYRAMID LIGHT BEACON
   ثابت فوق الأهرامات + عمود نور رأسي
========================================================= */

.pyramid-light-beacon {
    position: absolute;

    /* مكان الكشاف فوق الأهرامات */
    left: 50%;
    top: 3%;

    width: 90px;
    height: 430px;

    transform: translateX(-50%);

    pointer-events: none;

    z-index: 8;
}


/* =========================================================
   مصدر الكشاف
========================================================= */

.beacon-source {
    position: absolute;

    top: 0;
    left: 50%;

    width: 26px;
    height: 26px;

    transform: translateX(-50%);

    border-radius: 50%;

    background:
        radial-gradient(
            circle,
            #fffbe0 0%,
            #f4d35e 30%,
            #d4af37 55%,
            transparent 75%
        );

    box-shadow:
        0 0 10px #f4d35e,
        0 0 25px rgba(244,211,94,.7),
        0 0 45px rgba(244,211,94,.35);

    animation: beaconBlink 2.8s ease-in-out infinite;
}


/* =========================================================
   عمود النور
========================================================= */

.beacon-column {
    position: absolute;

    top: 18px;
    left: 50%;

    width: 34px;
    height: 400px;

    transform: translateX(-50%);

    background:
        linear-gradient(
            to bottom,
            rgba(244,211,94,.55),
            rgba(244,211,94,.28) 35%,
            rgba(244,211,94,.14) 70%,
            transparent 100%
        );

    clip-path: polygon(
        30% 0%,
        70% 0%,
        100% 100%,
        0% 100%
    );

    filter:
        blur(5px)
        drop-shadow(0 0 12px rgba(244,211,94,.55));

    transform-origin: top center;

    animation: beaconColumnBlink 2.8s ease-in-out infinite;
}


/* =========================================================
   طبقة نور داخلية — تخلي العمود أوضح
========================================================= */

.pyramid-light-beacon::after {
    content: "";

    position: absolute;

    top: 18px;
    left: 50%;

    width: 8px;
    height: 390px;

    transform: translateX(-50%);

    background:
        linear-gradient(
            to bottom,
            rgba(255,250,200,.8),
            rgba(244,211,94,.35),
            transparent
        );

    filter: blur(3px);

    opacity: .7;

    animation: beaconCoreBlink 2.8s ease-in-out infinite;
}


/* =========================================================
   BLINK
========================================================= */

@keyframes beaconBlink {

    0%,
    100% {
        opacity: .65;
        transform: translateX(-50%) scale(.9);
    }

    50% {
        opacity: 1;
        transform: translateX(-50%) scale(1.15);
    }

}


@keyframes beaconColumnBlink {

    0%,
    100% {
        opacity: .38;
    }

    50% {
        opacity: .75;
    }

}


@keyframes beaconCoreBlink {

    0%,
    100% {
        opacity: .35;
    }

    50% {
        opacity: .85;
    }

}
/* =========================================================
   EGYPTIAN STAT ICONS — ANIMATED TEMPLE STYLE
   ========================================================= */

.stat-icon {
  width: 82px;
  height: 82px;
  overflow: visible;

  transform-origin: center;

  filter:
    drop-shadow(0 0 4px rgba(212, 175, 55, 0.18));

  animation: templeIconFloat 4.5s ease-in-out infinite;

  transition:
    transform 0.45s ease,
    filter 0.45s ease;
}


/* =========================================================
   VERY LIGHT IDLE MOVEMENT
   ========================================================= */

@keyframes templeIconFloat {

  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-3px);
  }

}


/* =========================================================
   COMMON COLORS
   ========================================================= */

.stat-icon .icon-frame,
.stat-icon .icon-line,
.stat-icon .book-line,
.stat-icon .temple-line {

  fill: none;

  stroke: #8f7028;

  stroke-width: 1.5;

  stroke-linecap: round;
  stroke-linejoin: round;
}


.stat-icon .icon-gold,
.stat-icon .book-gold,
.stat-icon .temple-gold {

  fill: #d4af37;

}


.stat-icon .icon-stone,
.stat-icon .book-stone,
.stat-icon .temple-stone {

  fill: #c9a876;

}


/* =========================================================
   STUDENTS
   ========================================================= */

.stat-icon-students .icon-frame {

  fill: none;

  stroke: #9d7b32;

  stroke-width: 2;

}


.stat-icon-students .icon-gold {

  filter:
    drop-shadow(0 0 3px rgba(212, 175, 55, 0.35));

}


.stat-icon-students .icon-eye {

  fill: none;

  stroke: #d4af37;

  stroke-width: 1.5;

  animation:
    eyeGlow 3.5s ease-in-out infinite;

}


.stat-icon-students .icon-eye-dot {

  fill: #d4af37;

  animation:
    eyePulse 3.5s ease-in-out infinite;

}


@keyframes eyeGlow {

  0%,
  70%,
  100% {
    opacity: 0.8;
  }

  75%,
  85% {
    opacity: 1;
  }

}


@keyframes eyePulse {

  0%,
  70%,
  100% {
    opacity: 0.6;
  }

  78% {
    opacity: 1;
  }

}


.stat-icon-students .icon-line {

  stroke: #705522;

  stroke-width: 1.2;

}


/* =========================================================
   BOOKS
   ========================================================= */

.stat-icon-books .book-dark {

  fill: #705522;

}


.stat-icon-books .book-stone {

  fill: #a88b5d;

}


.stat-icon-books .book-front {

  fill: #d0b27e;

}


.stat-icon-books .book-gold {

  fill: #d4af37;

  filter:
    drop-shadow(0 0 2px rgba(212, 175, 55, 0.25));

}


.stat-icon-books .book-line {

  stroke: #674d20;

  stroke-width: 1.4;

}


.stat-icon-books .ankh {

  fill: none;

  stroke: #d4af37;

  stroke-width: 1.4;

  stroke-linecap: round;

  animation:
    ankhGlow 4s ease-in-out infinite;

}


@keyframes ankhGlow {

  0%,
  65%,
  100% {
    opacity: 0.55;
  }

  72%,
  82% {
    opacity: 1;
  }

}


/* =========================================================
   LIBRARY VISITS — TEMPLE
   ========================================================= */

.stat-icon-visits .visit-sun {

  fill: #d4af37;

  filter:
    drop-shadow(0 0 4px rgba(212, 175, 55, 0.4));

  transform-origin: 40px 12px;

  animation:
    sunPulse 4s ease-in-out infinite;

}


@keyframes sunPulse {

  0%,
  100% {
    transform: scale(1);
    opacity: 0.85;
  }

  50% {
    transform: scale(1.12);
    opacity: 1;
  }

}


.stat-icon-visits .temple-stone {

  fill: #b89b6b;

}


.stat-icon-visits .temple-door {

  fill: #35291f;

}


.stat-icon-visits .visit-eye {

  fill: none;

  stroke: #d4af37;

  stroke-width: 1.6;

  animation:
    horusGlow 4s ease-in-out infinite;

}


.stat-icon-visits .visit-eye-dot {

  fill: #d4af37;

}


@keyframes horusGlow {

  0%,
  65%,
  100% {
    opacity: 0.65;

    filter:
      drop-shadow(0 0 0 rgba(212, 175, 55, 0));
  }

  72%,
  82% {
    opacity: 1;

    filter:
      drop-shadow(0 0 5px rgba(212, 175, 55, 0.7));
  }

}


/* =========================================================
   HOVER — MORE ENERGY
   ========================================================= */

.stat-card:hover .stat-icon {

  animation: none;

  transform:
    translateY(-6px)
    scale(1.07);

  filter:
    drop-shadow(0 0 7px rgba(212, 175, 55, 0.45))
    drop-shadow(0 0 18px rgba(212, 175, 55, 0.14));

}


/* =========================================================
   HOVER GOLD
   ========================================================= */

.stat-card:hover
.stat-icon .icon-gold,

.stat-card:hover
.stat-icon .book-gold,

.stat-card:hover
.stat-icon .temple-gold {

  filter:
    drop-shadow(0 0 5px rgba(212, 175, 55, 0.7));

}


/* =========================================================
   HOVER EYE
   ========================================================= */

.stat-card:hover
.stat-icon-students .icon-eye,

.stat-card:hover
.stat-icon-visits .visit-eye {

  filter:
    drop-shadow(0 0 6px rgba(212, 175, 55, 0.8));

}


/* =========================================================
   REDUCE MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .stat-icon,
  .stat-icon-students .icon-eye,
  .stat-icon-students .icon-eye-dot,
  .stat-icon-books .ankh,
  .stat-icon-visits .visit-sun,
  .stat-icon-visits .visit-eye {

    animation: none;

  }

  .stat-card:hover .stat-icon {

    transform: none;

  }

}
