}
/* ============================================================
   TEMPLE EXIT — CLEAN FINAL LAYOUT
   Fixes gate / farewell / services overlap
   ============================================================ */

/* ------------------------------------------------------------
   EXIT SECTION
------------------------------------------------------------ */

.temple-exit{
  position:relative;
  width:100%;
  min-height:180vh;

  overflow:hidden;
  isolation:isolate;

  /* keep normal document flow */
  display:block;
}


/* ------------------------------------------------------------
   GATE
   The gate stays in its own area
------------------------------------------------------------ */

.temple-exit .exit-gate-wrap{

  position:relative !important;

  left:auto !important;
  top:auto !important;

  transform:none !important;

  width:min(62vw,570px);
  height:min(76vh,650px);

  margin:0 auto;

  z-index:5;

  perspective:1500px;

  filter:
    drop-shadow(
      0 35px 50px
      rgba(0,0,0,.75)
    );
}


/* ------------------------------------------------------------
   FAREWELL
   Put it BELOW the gate
------------------------------------------------------------ */

.temple-exit .exit-farewell{

  position:relative !important;

  left:auto !important;
  top:auto !important;

  width:min(650px,88%);

  margin:0 auto;

  padding:
    5vh 20px
    8vh;

  transform:
    translateY(20px);

  z-index:15;

  text-align:center;

  opacity:0;

  transition:
    opacity 1s ease,
    transform 1s ease;
}


.temple-exit .exit-farewell.visible{

  opacity:1;

  transform:
    translateY(0);
}


/* ------------------------------------------------------------
   SERVICES
   IMPORTANT:
   They remain in NORMAL FLOW and go after farewell
------------------------------------------------------------ */

.temple-exit .exit-footer{

  position:relative !important;

  left:auto !important;
  bottom:auto !important;

  transform:none !important;

  width:min(1180px,88%);

  margin:
    2vh auto 0 !important;

  padding:
    0 0 8vh !important;

  display:grid !important;

  grid-template-columns:
    repeat(4,1fr);

  gap:24px;

  z-index:12;
}


/* ------------------------------------------------------------
   SERVICE CARDS
------------------------------------------------------------ */

.temple-exit .exit-card{

  position:relative;

  min-height:190px;

  box-sizing:border-box;

  padding:
    28px 22px;
}


/* ------------------------------------------------------------
   SIGN OFF
   Comes AFTER the service cards
------------------------------------------------------------ */

.temple-exit .exit-signoff{

  position:relative !important;

  left:auto !important;
  right:auto !important;
  bottom:auto !important;

  margin:0 !important;

  padding:
    0 20px 70px !important;

  z-index:13;

  text-align:center;
}


/* ============================================================
   EXTRA SPACE BETWEEN GATE AND SERVICES
   ============================================================ */

.temple-exit .exit-gate-wrap{
  margin-bottom:4vh;
}


/* ============================================================
   TABLET
============================================================ */

@media (max-width:900px){

  .temple-exit{
    min-height:190vh;
  }

  .temple-exit .exit-gate-wrap{
    width:min(78vw,500px);
  }

  .temple-exit .exit-footer{
    grid-template-columns:
      repeat(2,1fr);
  }

}


