/* ============================================================
   CAMEL MOVEMENT
============================================================ */

.temple-exit .camel-left{

  left:-180px;
  top:34%;

  transform:scale(.72);

  animation:
    camelAcross 24s linear infinite;
}


.temple-exit .camel-right{

  right:-180px;
  top:57%;

  transform:
    scale(.5)
    scaleX(-1);

  animation:
    camelAcrossReverse 29s linear infinite;
}


@keyframes camelAcross{

  from{
    left:-180px;
  }

  to{
    left:calc(100% + 180px);
  }

}


@keyframes camelAcrossReverse{

  from{
    right:-180px;
  }

  to{
    right:calc(100% + 180px);
  }

}


