}


/* ============================================================
   GOLD LIGHT SWEEP
============================================================ */

.temple-exit .social-pill::after {
  content: "";

  position: absolute;

  top: -30%;
  left: -80%;

  width: 55%;
  height: 160%;

  background:
    linear-gradient(
      105deg,
      transparent,
      rgba(255,236,170,.28),
      rgba(255,255,220,.42),
      transparent
    );

