  transition: left .7s ease;

  pointer-events: none;
}

.temple-exit .social-pill:hover::after {
  left: 135%;
}


/* ============================================================
   ICON BASE
============================================================ */

.temple-exit .social-pill::before {
  display: flex;

  align-items: center;
  justify-content: center;

  position: relative;

  width: 31px;
  height: 31px;

  flex-shrink: 0;

  border: 1px solid rgba(212,175,55,.55);
