============================================================ */

.temple-exit{
  position:relative;
}


/* ------------------------------------------------------------
   MAIN DECORATION CONTAINER
------------------------------------------------------------ */

.temple-exit .exit-hieroglyphs{
  position:absolute;
  inset:0;
  z-index:2;
  pointer-events:none;
}


/* ------------------------------------------------------------
   LEFT / RIGHT WALL
------------------------------------------------------------ */

.temple-exit .hieroglyph-wall{
  position:absolute;

  top:10%;
  width:clamp(110px, 13vw, 190px);
  height:48%;

  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:space-evenly;

  opacity:.72;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(93,64,30,.10) 20%,
      rgba(173,127,57,.12) 50%,
      rgba(93,64,30,.10) 80%,
      transparent
    );

  border-top:
    1px solid rgba(198,153,72,.22);

  border-bottom:
    1px solid rgba(198,153,72,.18);
}


