  left:3%;
}


/* RIGHT */

.temple-exit .hieroglyph-right{
  right:3%;
}


/* ------------------------------------------------------------
   HIEROGLYPHS
------------------------------------------------------------ */

.temple-exit .glyph{
  position:relative;

  display:flex;
  align-items:center;
  justify-content:center;

  width:48px;
  height:48px;

  color:#c99b4c;

  font-family:
    "Segoe UI Historic",
    "Noto Sans Egyptian Hieroglyphs",
    serif;

  font-size:clamp(25px,3vw,38px);

  text-shadow:
    0 0 8px rgba(212,175,55,.12),
    0 2px 4px rgba(0,0,0,.8);

  opacity:.68;

  filter:
    drop-shadow(0 2px 3px rgba(0,0,0,.8));

  transition:
    opacity .4s ease,
    transform .4s ease;
}


/* Eye of Horus */

.temple-exit .glyph-eye{
  color:#dfb65c;

  font-size:clamp(30px,3.4vw,43px);

  opacity:.85;

  text-shadow:
    0 0 12px rgba(226,184,84,.25),
    0 2px 5px #000;
}


/* ------------------------------------------------------------
   DECORATIVE VERTICAL LINE
------------------------------------------------------------ */

.temple-exit .hieroglyph-line{
  position:absolute;

  top:4%;
  bottom:4%;

  width:1px;

  background:
    linear-gradient(
      to bottom,
      transparent,
      rgba(198,153,72,.45) 15%,
      rgba(198,153,72,.18) 50%,
      rgba(198,153,72,.45) 85%,
      transparent
    );

  box-shadow:
    0 0 8px rgba(212,175,55,.08);
}


/* little horizontal cuts */

.temple-exit .hieroglyph-line::before,
.temple-exit .hieroglyph-line::after{
  content:"";

  position:absolute;

  left:50%;

  width:34px;
  height:1px;

  transform:translateX(-50%);

  background:
    rgba(198,153,72,.35);
}

.temple-exit .hieroglyph-line::before{
  top:18%;
}

.temple-exit .hieroglyph-line::after{
  bottom:18%;
}


/* ------------------------------------------------------------
   SUBTLE LIFE
------------------------------------------------------------ */

.temple-exit .hieroglyph-wall .glyph:nth-child(odd){
  animation:
    glyphBreath 5s ease-in-out infinite;
}

.temple-exit .hieroglyph-wall .glyph:nth-child(even){
  animation:
    glyphBreath 6s ease-in-out infinite reverse;
}

@keyframes glyphBreath{

  0%,100%{
    opacity:.55;
    transform:scale(.96);
  }

  50%{
    opacity:.82;
    transform:scale(1);
  }

}


