/* =========================================================
   TEMPLE MUSIC RELIC
   Fixed inside the first temple entrance
========================================================= */

.entrance {
    position: relative;
}


/* =========================================================
   MAIN BUTTON
========================================================= */

.music-btn {
    position: absolute !important;

    /* ناحية الشمال من باب المعبد */
    left: clamp(35px, 9vw, 150px) !important;

    /* مستوى قريب من منتصف الباب */
    top: 53% !important;

    transform: translateY(-50%) !important;

    width: 86px !important;
    height: 86px !important;

    padding: 0 !important;
    margin: 0 !important;

    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    background: transparent !important;
    border: 0 !important;

    color: #d4af37;

    cursor: pointer;

    z-index: 100 !important;

    overflow: visible !important;

    isolation: isolate;

    /* مهم: مفيش حركة للمكان */
    transition:
        filter .35s ease,
        opacity .35s ease !important;
}


/* =========================================================
   STONE / GOLD DISC
========================================================= */

.music-emblem {
    position: relative;

    width: 64px;
    height: 64px;

    display: grid;
    place-items: center;

    border-radius: 50%;

    background:
        radial-gradient(
            circle at 38% 32%,
            #b99345 0%,
            #60451e 28%,
            #24180d 67%,
            #0d0905 100%
        );

    border:
        2px solid rgba(212,175,55,.85);

    box-shadow:

        /* الذهب الداخلي */
        inset 0 0 12px rgba(255,215,100,.18),

        /* ظل القطعة */
        0 8px 20px rgba(0,0,0,.65),

        /* هالة ذهبية */
        0 0 16px rgba(212,175,55,.18);

    z-index: 5;

    transition:
        box-shadow .35s ease,
        border-color .35s ease,
        filter .35s ease;
}


/* إطار أثري داخلي */

.music-emblem::before {
    content: "";

    position: absolute;

    inset: 6px;

    border:
        1px solid rgba(212,175,55,.45);

    border-radius: 50%;

    box-shadow:
        inset 0 0 8px rgba(212,175,55,.12);
}


/* الرمز */

.music-icon {
    position: relative;

    z-index: 4;

    font-family:
        "Noto Sans Egyptian Hieroglyphs",
        "Segoe UI Symbol",
        serif;

    font-size: 31px;

    line-height: 1;

    color: #e6c65f;

    text-shadow:
        0 0 5px rgba(255,220,100,.55),
        0 0 14px rgba(212,175,55,.3);

    transition:
        filter .35s ease;
}


/* =========================================================
   OUTER ORBITS
========================================================= */

.music-orbit {
    position: absolute;

    border-radius: 50%;

    pointer-events: none;

    border: 1px solid rgba(212,175,55,.28);

    z-index: 1;
}


.orbit-one {
    width: 76px;
    height: 76px;

    border-style: dashed;

    transform: rotate(18deg);
}


.orbit-two {
    width: 92px;
    height: 54px;

    transform: rotate(-28deg);

    border-color:
        rgba(212,175,55,.18);
}


/* =========================================================
   SMALL GOLD MARKS
========================================================= */

.music-orbit::before,
.music-orbit::after {
    content: "";

    position: absolute;

    width: 5px;
    height: 5px;

    border-radius: 50%;

    background: #d4af37;

    box-shadow:
        0 0 7px rgba(212,175,55,.7);
}


.orbit-one::before {
    top: -3px;
    left: 50%;
}


.orbit-one::after {
    bottom: -3px;
    right: 12%;
}


.orbit-two::before {
    top: 12%;
    left: -3px;
}


.orbit-two::after {
    bottom: 12%;
    right: -3px;
}


/* =========================================================
   SOUND WAVES
========================================================= */

.music-waves {
    position: absolute;

    right: -4px;
    top: 50%;

    transform: translateY(-50%);

    display: flex;

    gap: 3px;

    height: 25px;

    align-items: center;

    z-index: 8;

    opacity: .75;
}


.music-waves i {
    display: block;

    width: 2px;

    height: 7px;

    border-radius: 4px;

    background: #d4af37;

    box-shadow:
        0 0 5px rgba(212,175,55,.45);

    transition:
        height .3s ease;
}


.music-waves i:nth-child(2) {
    height: 14px;
}


.music-waves i:nth-child(3) {
    height: 20px;
}


/* =========================================================
   HIDDEN LABEL
========================================================= */

.music-text {
    position: absolute;

    left: 78px;
    top: 50%;

    transform:
        translateY(-50%)
        translateX(-10px);

    width: max-content;

    padding: 9px 17px;

    opacity: 0;
    visibility: hidden;

    pointer-events: none;

    white-space: nowrap;

    color: #e8ca68;

    font-family:
        "Cinzel",
        Georgia,
        serif;

    font-size: 12px;

    letter-spacing: 1.5px;

    background:
        linear-gradient(
            90deg,
            rgba(28,18,8,.98),
            rgba(67,46,18,.98),
            rgba(28,18,8,.98)
        );

    border:
        1px solid rgba(212,175,55,.65);

    box-shadow:
        0 8px 22px rgba(0,0,0,.55),
        inset 0 0 12px rgba(212,175,55,.08);

    transition:
        opacity .3s ease,
        visibility .3s ease,
        transform .3s ease;

    z-index: 20;
}


/* زخارف الاسم */

.music-text::before {
    content: "𓋹";

    margin-right: 8px;

    color: #d4af37;
}


.music-text::after {
    content: "𓂀";

    margin-left: 8px;

    color: #d4af37;
}


/* =========================================================
   HOVER
========================================================= */

.music-btn:hover .music-emblem {
    border-color: #f2d573;

    box-shadow:
        inset 0 0 16px rgba(255,215,100,.25),
        0 0 20px rgba(212,175,55,.32),
        0 0 42px rgba(212,175,55,.12),
        0 10px 25px rgba(0,0,0,.7);

    filter: brightness(1.12);
}


.music-btn:hover .music-icon {
    filter:
        drop-shadow(0 0 6px rgba(255,220,100,.8))
        drop-shadow(0 0 14px rgba(212,175,55,.45));
}


.music-btn:hover .music-text {
    opacity: 1;
    visibility: visible;

    transform:
        translateY(-50%)
        translateX(0);
}


/* =========================================================
   PLAYING STATE
========================================================= */

.music-btn[aria-pressed="true"] .music-emblem {

    box-shadow:
        inset 0 0 18px rgba(255,215,100,.25),
        0 0 25px rgba(212,175,55,.4),
        0 0 55px rgba(212,175,55,.14);
}


.music-btn[aria-pressed="true"] .music-waves i {
    animation:
        musicWave .75s ease-in-out infinite alternate;
}


.music-btn[aria-pressed="true"] .music-waves i:nth-child(1) {
    animation-delay: -.2s;
}


.music-btn[aria-pressed="true"] .music-waves i:nth-child(2) {
    animation-delay: -.4s;
}


.music-btn[aria-pressed="true"] .music-waves i:nth-child(3) {
    animation-delay: -.1s;
}


@keyframes musicWave {

    from {
        height: 5px;
        opacity: .45;
    }

    to {
        height: 21px;
        opacity: 1;
    }

}


/* =========================================================
   CLICK
========================================================= */

.music-btn:active .music-emblem {
    filter: brightness(1.25);

    box-shadow:
        0 0 35px rgba(212,175,55,.5),
        inset 0 0 20px rgba(255,215,100,.25);
}


