   ضيف الكود ده في آخر ملف CSS
============================================================ */


/* ------------------------------------------------------------
   SKY LAYERS
------------------------------------------------------------ */

.entrance .sky {
  position: relative;
  overflow: hidden;
}


/* ------------------------------------------------------------
   ☁️ LARGE CLEAR MOVING CLOUDS
------------------------------------------------------------ */

.entrance .sky::before {
  content: "";

  position: absolute;
  inset: -20% -30%;

  z-index: 1;
  pointer-events: none;

  background:

    /* Large cloud mass 1 */
    radial-gradient(
      ellipse 320px 95px at 12% 32%,
      rgba(135, 155, 190, .72) 0%,
      rgba(90, 115, 155, .58) 38%,
      rgba(45, 65, 100, .28) 65%,
      transparent 76%
    ),

    /* Large cloud mass 2 */
    radial-gradient(
      ellipse 420px 120px at 38% 20%,
      rgba(150, 170, 205, .68) 0%,
      rgba(95, 120, 160, .52) 38%,
      rgba(45, 65, 100, .25) 68%,
      transparent 78%
    ),

    /* Large cloud mass 3 */
    radial-gradient(
      ellipse 360px 105px at 68% 30%,
      rgba(140, 165, 205, .7) 0%,
      rgba(85, 110, 150, .5) 40%,
      rgba(35, 55, 90, .22) 68%,
      transparent 78%
    ),

    /* Large cloud mass 4 */
    radial-gradient(
      ellipse 500px 130px at 88% 17%,
      rgba(155, 175, 210, .7) 0%,
      rgba(90, 115, 155, .5) 40%,
      rgba(40, 60, 95, .22) 70%,
      transparent 80%
    ),

    /* Lower clouds */
    radial-gradient(
      ellipse 450px 100px at 25% 58%,
      rgba(100, 125, 165, .55),
      rgba(50, 70, 105, .3) 55%,
      transparent 78%
    ),

    radial-gradient(
      ellipse 500px 115px at 75% 55%,
      rgba(110, 135, 175, .55),
      rgba(50, 70, 105, .28) 55%,
      transparent 78%
    );

  background-size:
    150% 100%;

  opacity: .88;

  animation:
    cloudsDriftSlow 70s linear infinite;

  will-change: transform;
}


/* ------------------------------------------------------------
   ☁️ SECOND CLOUD LAYER
   أسرع شوية وتعطي إحساس بالعمق
------------------------------------------------------------ */

.entrance .sky::after {
  content: "";

  position: absolute;
  inset: -15% -40%;

  z-index: 2;
  pointer-events: none;

  background:

    radial-gradient(
      ellipse 230px 70px at 8% 45%,
      rgba(180, 195, 220, .6),
      rgba(90, 115, 155, .35) 55%,
      transparent 75%
    ),

    radial-gradient(
      ellipse 300px 80px at 30% 34%,
      rgba(175, 195, 225, .55),
      rgba(85, 110, 150, .3) 55%,
      transparent 75%
    ),

    radial-gradient(
      ellipse 260px 75px at 55% 48%,
      rgba(170, 190, 220, .58),
      rgba(80, 105, 145, .28) 55%,
      transparent 75%
    ),

    radial-gradient(
      ellipse 340px 90px at 82% 38%,
      rgba(180, 200, 230, .6),
      rgba(85, 110, 150, .3) 55%,
      transparent 76%
    );

  opacity: .75;

  animation:
    cloudsDriftFast 42s linear infinite;

  will-change: transform;
}


/* ------------------------------------------------------------
   ☁️ CLOUD MOVEMENT
------------------------------------------------------------ */

@keyframes cloudsDriftSlow {

  0% {
    transform: translateX(-8%);
  }

  50% {
    transform: translateX(8%);
  }

  100% {
    transform: translateX(-8%);
  }

}


@keyframes cloudsDriftFast {

  0% {
    transform: translateX(12%);
  }

  50% {
    transform: translateX(-12%);
  }

  100% {
    transform: translateX(12%);
  }

}


/* ------------------------------------------------------------
   ⭐ MANY STARS
------------------------------------------------------------ */

.entrance .skyline-silhouette::before {
  content: "";

  position: absolute;

  inset: -100vh -50vw;

  z-index: 5;

  pointer-events: none;

  background-image:

    /* Tiny stars */
    radial-gradient(
      circle,
      rgba(255,255,255,.95) 0 1px,
      transparent 1.5px
    ),

    /* Blue stars */
    radial-gradient(
      circle,
      rgba(190,215,255,.9) 0 1.2px,
      transparent 1.8px
    ),

    /* Golden stars */
    radial-gradient(
      circle,
      rgba(255,225,150,.9) 0 1px,
      transparent 1.7px
    ),

    /* Very tiny stars */
    radial-gradient(
      circle,
      rgba(255,255,255,.75) 0 .7px,
      transparent 1.2px
    );

  background-size:
    95px 85px,
    145px 125px,
    190px 165px,
    65px 70px;

  background-position:
    10px 20px,
    40px 60px,
    90px 30px,
    25px 100px;

  opacity: .8;

  animation:
    starsDrift 120s linear infinite,
    starsTwinkle 5s ease-in-out infinite alternate;

}


/* ------------------------------------------------------------
   ✨ STAR MOVEMENT
------------------------------------------------------------ */

@keyframes starsDrift {

  from {
    transform: translate3d(0, 0, 0);
  }

  to {
    transform: translate3d(-180px, 70px, 0);
  }

}


@keyframes starsTwinkle {

  0% {
    opacity: .55;
  }

  50% {
    opacity: .9;
  }

  100% {
    opacity: .65;
  }

}


/* ------------------------------------------------------------
   ✨ BRIGHTER BIG STARS
------------------------------------------------------------ */

.entrance .skyline-silhouette::after {
  content: "";

  position: absolute;

  inset: 0;

  z-index: 6;

  pointer-events: none;

  background:

    radial-gradient(
      circle at 18% 18%,
      rgba(255,255,255,1) 0 2px,
      rgba(190,215,255,.7) 3px,
      transparent 7px
    ),

    radial-gradient(
      circle at 37% 12%,
      rgba(255,230,170,1) 0 2px,
      rgba(255,220,150,.55) 3px,
      transparent 7px
    ),

    radial-gradient(
      circle at 61% 24%,
      rgba(255,255,255,1) 0 1.8px,
      rgba(190,215,255,.6) 3px,
      transparent 7px
    ),

    radial-gradient(
      circle at 79% 14%,
      rgba(255,255,255,1) 0 2px,
      rgba(200,220,255,.6) 3px,
      transparent 7px
    ),

    radial-gradient(
      circle at 91% 34%,
      rgba(255,225,160,1) 0 2px,
      rgba(255,220,150,.5) 3px,
      transparent 7px
    );

  opacity: .9;

  animation:
    bigStarsPulse 3.5s ease-in-out infinite alternate;

}


@keyframes bigStarsPulse {

  from {
    opacity: .55;
    transform: scale(.98);
  }

  to {
    opacity: 1;
    transform: scale(1.02);
  }

}


