/* ============================================================
   🏺 PHARAONIC OBELISKS — REALISTIC NIGHT VERSION
============================================================ */

.entrance .pylon {
  /* الحجم والشكل */
  width: clamp(55px, 4.5vw, 85px) !important;
  height: clamp(250px, 38vh, 390px) !important;

  /* مسلة مصرية: عريضة من أسفل ورفيعة من أعلى */
  clip-path: polygon(
    30% 100%,
    70% 100%,
    62% 10%,
    50% 0%,
    38% 10%
  );

  /* حجر داكن مضاء بالقمر */
  background:
    linear-gradient(
      90deg,
      #17130f 0%,
      #3b3023 18%,
      #786348 38%,
      #403326 55%,
      #211b15 78%,
      #0e0d0b 100%
    ) !important;

  filter:
    brightness(.82)
    saturate(.72)
    drop-shadow(0 12px 18px rgba(0,0,0,.8))
    drop-shadow(0 0 5px rgba(220,180,90,.12));

  opacity: 1 !important;

  z-index: 8 !important;
}


/* ============================================================
   ✨ GOLDEN EDGE — حافة ذهبية خفيفة
============================================================ */

.entrance .pylon::before {
  content: "";

  position: absolute;
  inset: 0;

  background:
    linear-gradient(
      90deg,
      transparent 0%,
      transparent 35%,
      rgba(232,197,112,.35) 43%,
      rgba(255,220,130,.55) 50%,
      rgba(232,197,112,.18) 57%,
      transparent 68%,
      transparent 100%
    );

  opacity: .65;

  pointer-events: none;
}


/* ============================================================
   🔺 PYRAMIDION — قمة المسلة
============================================================ */

.entrance .pylon::after {
  content: "";

  position: absolute;

  left: 50%;
  top: 0;

  width: 34%;
  height: 13%;

  transform: translateX(-50%);

  clip-path: polygon(
    50% 0%,
    100% 100%,
    0% 100%
  );

  background:
    linear-gradient(
      135deg,
      #d6b766 0%,
      #80652e 35%,
      #3c2e18 70%,
      #17130d 100%
    );

  box-shadow:
    0 0 8px rgba(220,180,80,.22);

  z-index: 3;
}


/* ============================================================
   🏺 BASE — قاعدة المسلة
============================================================ */

.entrance .pylon {
  box-shadow:
    inset 8px 0 12px rgba(0,0,0,.45),
    inset -8px 0 12px rgba(0,0,0,.55),
    inset 0 -18px 20px rgba(0,0,0,.4),
